local config = {
  ui_story_5004_50040101_1_dialog_content = "PlayerName!",
  ui_story_5004_50040101_2_dialog_content = "Para trás, PlayerName!",
  ui_story_5004_50040101_3_dialog_content = "(Ondas gigantescas e violentas quase me derrubam.)",
  ui_story_5004_50040101_4_dialog_content = "(Relâmpagos em tons de roxo e vermelho repartem o escuro céu nebuloso. O estrondo dos trovões ecoa nos meus ouvidos.",
  ui_story_5004_50040101_5_dialog_content = "(Eu olho fixamente para os inúmeros meteoritos que caem sobre nós.)",
  ui_story_5004_50040101_6_dialog_content = "(O ameaçador castelo continua a erguer-se lentamente das profundezas do oceano, trazendo consigo uma certa melancolia.)",
  ui_story_5004_50040101_7_dialog_content = "(Vice e Carleen estão à frente, tentando, em vão, me proteger...)",
  ui_story_5004_50040101_8_dialog_content = "(É tarde demais.)",
  ui_story_5004_50040101_9_dialog_content = "(Eu nunca pensei que seria responsável pela catástrofe e destruição que se aproximam...)",
  ui_story_5004_50040101_10_dialog_content = "Então vou deixá-la sob seus cuidados. Adeus.",
  ui_story_5004_50040101_11_dialog_content = "Espera aí, você não pode simplesmente aparecer aqui com uma garota e entregá-la pra mim!",
  ui_story_5004_50040101_12_dialog_content = "Eu nem ao menos sei o nome dela!",
  ui_story_5004_50040101_13_dialog_content = "...",
  ui_story_5004_50040101_14_dialog_content = "Oi...",
  ui_story_5004_50040101_15_dialog_content = "Meu nome é...",
  ui_story_5004_50040101_16_dialog_content = "O nome dela é <color=#FFB400>Beryl</color>. Agora que estão devidamente apresentados, eu preciso ir.",
  ui_story_5004_50040101_17_dialog_content = "Espera um pouco aí! Isso não é suficiente!",
  ui_story_5004_50040101_18_dialog_content = "Bem, se você insiste, PlayerName, eu ficaria feliz em esclarecê-lo com A Verdade...",
  ui_story_5004_50040101_19_dialog_content = "Não fuja do assunto! Você não disse mais cedo que ela...",
  ui_story_5004_50040101_20_dialog_content = "...",
  ui_story_5004_50040101_21_dialog_content = "Digo, Beryl. Você não disse que ela está <color=#FFB400>doente</color>? Que tipo de doença?",
  ui_story_5004_50040101_22_dialog_content = "Não tenho certeza.",
  ui_story_5004_50040101_23_dialog_content = "O quê?",
  ui_story_5004_50040101_24_dialog_content = "Estou deixando ela sob seus cuidados porque eu não sei.",
  ui_story_5004_50040101_25_dialog_content = "Você é um Celestita com habilidades psíquicas, cercado de Aurorians e com experiência em Lumináticas de cura.",
  ui_story_5004_50040101_26_dialog_content = "Lady Victoria e eu concordamos que seria melhor se você cuidasse dela.",
  ui_story_5004_50040101_27_dialog_content = "Desde quando a True Order faz caridade?",
  ui_story_5004_50040101_28_dialog_content = "...",
  ui_story_5004_50040101_29_dialog_content = "Espera, Faust, vamos tentar de novo.",
  ui_story_5004_50040101_30_dialog_content = "Quer dizer...",
  ui_story_5004_50040101_31_dialog_content = "Ela é...",
  ui_story_5004_50040101_32_option_content = "A filha de Lady Victoria?",
  ui_story_5004_50040101_33_dialog_content = "Não. Lady Victoria dedica seu tempo apenas para a busca da Verdade. Ela não tem aspirações tão mundanas.",
  ui_story_5004_50040101_34_option_content = "Você está oferecendo Beryl como sacrifício pra um de seus rituais sinistros?!",
  ui_story_5004_50040101_35_dialog_content = "Claro que não. Por favor, não insulte a nossa busca pela Verdade.",
  ui_story_5004_50040101_36_dialog_content = "Além disso, Beryl é uma integrante vital da True Order.",
  ui_story_5004_50040101_37_dialog_content = "Hmm...",
  ui_story_5004_50040101_38_dialog_content = "Tudo bem, contanto que isso não envolva nada suspeito...",
  ui_story_5004_50040101_39_dialog_content = "Ainda assim, não entendo por que Lady Victoria me escolheu.",
  ui_story_5004_50040101_40_dialog_content = "Não precisamos entender suas decisões.",
  ui_story_5004_50040101_41_dialog_content = "Chegamos mais perto da Verdade seguindo e executando suas ordens.",
  ui_story_5004_50040101_42_dialog_content = "(Isso só piora minhas suspeitas...)",
  ui_story_5004_50040101_43_dialog_content = "Bem, já que Raphaela está na Colossus, é melhor ir fazer uma visita.",
  ui_story_5004_50040101_44_dialog_content = "<color=#e8d9bb>Alguns minutos depois...</color>",
  ui_story_5004_50040101_45_dialog_content = "Hum...",
  ui_story_5004_50040101_46_dialog_content = "Hmm... Uh-huh...",
  ui_story_5004_50040101_47_dialog_content = "E aí?",
  ui_story_5004_50040101_48_dialog_content = "Já tentei de tudo, mas ainda não sei o que há de errado com ela.",
  ui_story_5004_50040101_49_dialog_content = "Seu nome é Beryl, não é?",
  ui_story_5004_50040101_50_dialog_content = "Sim.",
  ui_story_5004_50040101_51_dialog_content = "Diga, Beryl, você está sentindo alguma dor?",
  ui_story_5004_50040101_52_dialog_content = "Beryl...?",
  ui_story_5004_50040101_53_dialog_content = "Desculpe, eu levo algum tempo pra entender o que se passa no meu corpo.",
  ui_story_5004_50040101_54_dialog_content = "Mas tenho me sentido exausta ultimamente, com dificuldades de controlar minha Lúmina...",
  ui_story_5004_50040101_55_dialog_content = "Às vezes, sinto muita dor no corpo inteiro, como se ele estivesse sendo devorado por milhões de insetos.",
  ui_story_5004_50040101_56_dialog_content = "Entendi.",
  ui_story_5004_50040101_57_dialog_content = "É a primeira vez que vejo um paciente com os seus sintomas.",
  ui_story_5004_50040101_58_dialog_content = "O que acha, PlayerName?",
  ui_story_5004_50040101_59_dialog_content = "(Beryl tem um olhar franzido, como se estivesse preocupada com algo.)",
  ui_story_5004_50040101_60_option_content = "Talvez ela esteja descontente com alguma coisa?",
  ui_story_5004_50040101_61_dialog_content = "É bem possível!",
  ui_story_5004_50040101_62_dialog_content = "Carleen fazia essa cara sempre que discutia com o Senhor da Cidade.",
  ui_story_5004_50040101_63_dialog_content = "Igualzinho à Beryl.",
  ui_story_5004_50040101_64_option_content = "Eu posso tentar minhas habilidades psíquicas...",
  ui_story_5004_50040101_65_dialog_content = "Não! Isso é muito agressivo para uma garotinha.",
  ui_story_5004_50040101_66_dialog_content = "É como abri-la com um bisturi para descobrir a causa!",
  ui_story_5004_50040101_67_dialog_content = "Enfim!",
  ui_story_5004_50040101_68_dialog_content = "Seja o problema físico ou emocional, eu dou conta!",
  ui_story_5004_50040101_69_dialog_content = "Não se preocupe, Beryl. Ficarei ao seu lado como sua médica particular!",
  ui_story_5004_50040101_70_dialog_content = "Encontrarei a causa, custe o que custar!",
  ui_story_5004_50040101_71_dialog_content = "Custe o que custar... É melhor que isso não custe a vida dela...",
  ui_story_5004_50040101_72_dialog_content = "PlayerName!",
  ui_story_5004_50040101_X72_dialog_content = "Não brinque assim na frente dos pacientes!",
  ui_story_5004_50040101_73_dialog_content = "Eu agradeço.",
  ui_story_5004_50040101_74_dialog_content = "O que está acontecendo?",
  ui_story_5004_50040101_75_dialog_content = "Olá, PlayerName. Ah, olá, Raphaela. Vejo que também está aqui.",
  ui_story_5004_50040101_76_dialog_content = "Carleen! O que faz aqui?",
  ui_story_5004_50040101_77_dialog_content = "Vim em nome de Lumópolis para uma visita oficial de rotina e conversar um pouco com Vice.",
  ui_story_5004_50040101_78_dialog_content = "E esses dois...?",
  ui_story_5004_50040101_79_dialog_content = "Este é Faust.",
  ui_story_5004_50040101_80_dialog_content = "Bom dia, madame.",
  ui_story_5004_50040101_81_dialog_content = "Você está com a <color=#FFB400>True Order</color>?",
  ui_story_5004_50040101_82_dialog_content = "Não esperava que você conhecesse a True Order.",
  ui_story_5004_50040101_83_dialog_content = "Você também busca a Verdade?",
  ui_story_5004_50040101_84_dialog_content = "Essa tal Verdade não me interessa. Eu tenho minhas próprias crenças.",
  ui_story_5004_50040101_85_dialog_content = "Que pena.",
  ui_story_5004_50040101_86_dialog_content = "Contundo, enquanto você considerar a Verdade, estará mais perto dela.",
  ui_story_5004_50040101_87_dialog_content = "Talvez nos encontremos no fim.",
  ui_story_5004_50040101_88_dialog_content = "Quanta indolência... Quem é a garota, PlayerName?",
  ui_story_5004_50040101_89_dialog_content = "O nome dela é Beryl. Faust a trouxe aqui, eles parecem ser amigos.",
  ui_story_5004_50040101_90_dialog_content = "Beryl está agora sob meus cuidados, Carleen.",
  ui_story_5004_50040101_91_dialog_content = "Entendo. Muito bem, Raphaela.",
  ui_story_5004_50040101_92_dialog_content = "Cuide bem da paciente em nome da Noite Branca.",
  ui_story_5004_50040101_93_dialog_content = "Heehee, mas é claro!",
  ui_story_5004_50040101_94_dialog_content = "Mas ainda não sabemos o que está incomodando a Beryl.",
  ui_story_5004_50040101_X94_dialog_content = "Nosso palpite é um problema emocional ou ligado ao estresse.",
  ui_story_5004_50040101_95_dialog_content = "Você também trata doenças emocionais? Achei que fosse só um anjo de combate que dispara mísseis!",
  ui_story_5004_50040101_96_dialog_content = "Não subestime os Anjos de Lumópolis, Vice!",
  ui_story_5004_50040101_97_dialog_content = "(Legal, parece que Raphaela está se dando bem com Vice!)",
  ui_story_5004_50040101_98_dialog_content = "Por que você tá com esse sorriso bobo, PlayerName? Ah, eu trouxe uma coisa incrível.",
  ui_story_5004_50040101_99_dialog_content = "Talvez você ache útil.",
  ui_story_5004_50040101_100_dialog_content = "Uma carta pra você.",
  ui_story_5004_50040101_101_dialog_content = "Pra mim?",
  ui_story_5004_50040101_102_dialog_content = "Eho me entregou antes de sair correndo. No envelope está escrito <color=#FFB400>Hotel Tir'</color>.",
  ui_story_5004_50040101_103_dialog_content = "Mas o estranho é que não tem nenhum remetente.",
  ui_story_5004_50040101_104_dialog_content = "Você não vai abrir?",
  ui_story_5004_50040101_105_option_content = "Me parece suspeito. Que tal depois?",
  ui_story_5004_50040101_106_dialog_content = "Deixa disso. Vai ficar tudo bem!",
  ui_story_5004_50040101_107_dialog_content = "Deixa eu abrir pra você!",
  ui_story_5004_50040101_108_dialog_content = "Cuidado, pode ser uma bomba!",
  ui_story_5004_50040101_109_dialog_content = "É só um papel. Um baita papel, por sinal.",
  ui_story_5004_50040101_110_dialog_content = "Ufa. Que bom que nada aconteceu.",
  ui_story_5004_50040101_111_option_content = "Acho que é seguro. Vamos abrir.",
  ui_story_5004_50040101_112_dialog_content = "Pode abrir. Também quero saber o que tem dentro.",
  ui_story_5004_50040101_113_dialog_content = "Hum, é só uma folha de papel.",
  ui_story_5004_50040101_114_dialog_content = "Só isso?",
  ui_story_5004_50040101_115_dialog_content = "O que está escrito, PlayerName?",
  ui_story_5004_50040101_116_dialog_content = "Bom...",
  ui_story_5004_50040101_117_dialog_content = "Caro PlayerName,",
  ui_story_5004_50040101_118_dialog_content = "Convidamos você para visitar o Hotel Tir' durante suas férias.",
  ui_story_5004_50040101_X118_dialog_content = "Participe do nosso emocionante evento, o <color=#FFB400>Monarca do Oceano</color>.",
  ui_story_5004_50040101_119_dialog_content = "Em anexo, você encontrará um convite com até seis acompanhantes.",
  ui_story_5004_50040101_120_dialog_content = "Aproveite a nossa suíte de luxo e todas as suas comodidades!",
  ui_story_5004_50040101_121_dialog_content = "Que maravilha! Faz tempo que quero ir à praia!",
  ui_story_5004_50040101_122_dialog_content = "O festival vai fazer muito bem à Beryl!",
  ui_story_5004_50040101_123_dialog_content = "Se sua condição for de fato emocional, uma viagem relaxante pode ser a solução!",
  ui_story_5004_50040101_124_dialog_content = "Vamos levar Beryl para a praia, PlayerName? Por favorzinho?",
  ui_story_5004_50040101_125_dialog_content = "Espera aí, ainda estou processando tudo isso. Eu nunca nem ouvi falar nesse lugar...",
  ui_story_5004_50040101_126_dialog_content = "Não se preocupe, PlayerName, esse hotel é bem famoso.",
  ui_story_5004_50040101_127_dialog_content = "É verdade, o Hotel Tir' tem uma grande reputação entre os Nobres Lumos. Até eu já ouvi falar.",
  ui_story_5004_50040101_128_dialog_content = "Supostamente, o proprietário gerencia um excelente estabelecimento.",
  ui_story_5004_50040101_129_dialog_content = "O convite para o tal Monarca do Oceano deve ser só para dar mais publicidade.",
  ui_story_5004_50040101_130_dialog_content = "Mas por que me convidaram?",
  ui_story_5004_50040101_131_dialog_content = "Deve ser uma jogada de marketing.",
  ui_story_5004_50040101_132_dialog_content = "A maioria dos Aurorians gosta de saber mais sobre Celestitas.",
  ui_story_5004_50040101_133_dialog_content = "Um edifício, um quarto, até mesmo uma mesa onde um Celestita ficou ou comeu pode virar um trunfo para promover o hotel.",
  ui_story_5004_50040101_134_dialog_content = "Isso faz com que eu me sinta um tipo de animal exótico...",
  ui_story_5004_50040101_135_dialog_content = "...",
  ui_story_5004_50040101_136_dialog_content = "...",
  ui_story_5004_50040101_137_dialog_content = "Você não vai nem contestar isso?",
  ui_story_5004_50040101_138_dialog_content = "Já que é um local de lazer para os nobres e beneficia os dois lados...",
  ui_story_5004_50040101_139_dialog_content = "Deve ser perfeitamente seguro, certo?",
  ui_story_5004_50040101_140_dialog_content = "Parece que temos um consenso.",
  ui_story_5004_50040101_141_dialog_content = "Você ainda tá aqui?",
  ui_story_5004_50040101_142_dialog_content = "Vou deixar Beryl com você. Aproveitem a viagem. Adeus.",
  ui_story_5004_50040101_143_dialog_content = "Faust ainda vai e vem quando bem entende, como sempre.",
  ui_story_5004_50040101_144_dialog_content = "Ótimo! Vou exercer o meu dever médico e cuidar de você, Beryl!",
  ui_story_5004_50040101_145_dialog_content = "Eu não acho que as coisas são tão simples quanto parecem...",
  ui_story_5004_50040101_146_dialog_content = "Olha, ali! O mar!",
  ui_story_5004_50040101_147_dialog_content = "É a primeira vez que vejo o oceano, PlayerName.",
  ui_story_5004_50040101_148_dialog_content = "Você também, Vice?",
  ui_story_5004_50040101_149_dialog_content = "Achei que eu era o único...",
  ui_story_5004_50040101_150_dialog_content = "Claro que você não é o único! Afinal, é difícil viajar pra tão longe sem uma Colossus.",
  ui_story_5004_50040101_151_dialog_content = "A brisa marinha é tão agradável. O lindo azul por toda parte realmente ajuda a relaxar.",
  ui_story_5004_50040101_152_dialog_content = "Isso vai ser perfeito para Beryl!",
  ui_story_5004_50040101_153_dialog_content = "Você fica dizendo que é pela Beryl, mas sua real intenção era curtir uma praia, hã?",
  ui_story_5004_50040101_154_dialog_content = "Sim, essa é uma das razões.",
  ui_story_5004_50040101_155_dialog_content = "Porque para a maioria dos Aurorians, ir à praia é uma coisa rara.",
  ui_story_5004_50040101_156_dialog_content = "Você provavelmente não entende, tendo passado tanto tempo dentro na Colossus.",
  ui_story_5004_50040101_157_dialog_content = "Para os Aurorians, férias na praia tornaram-se um <color=#FFB400>rito de passagem</color>!",
  ui_story_5004_50040101_158_dialog_content = "O que quer dizer com isso?",
  ui_story_5004_50040101_159_dialog_content = "Pense bem, agora vários Eclipsitas se encontram ao longo da costa.",
  ui_story_5004_50040101_160_dialog_content = "É preciso curtir o sol e as ondas sempre preparado para um ataque.",
  ui_story_5004_50040101_161_dialog_content = "A combinação de perigo e lazer não é estimulante?",
  ui_story_5004_50040101_162_dialog_content = "Estimulante? Isso parece muito perigoso!",
  ui_story_5004_50040101_163_dialog_content = "Digamos que eu esteja com o corpo enterrado na areia quando os Eclipsitas aparecerem.",
  ui_story_5004_50040101_164_dialog_content = "Você não vai me deixar lá e fugir, não é, Vice?",
  ui_story_5004_50040101_165_dialog_content = "Somos colegas, não somos? Eu nunca faria isso!",
  ui_story_5004_50040101_166_dialog_content = "Além do mais, o sol e a água do mar refrescante fazem bem para a mente.",
  ui_story_5004_50040101_167_dialog_content = "Beryl certamente vai relaxar aqui.",
  ui_story_5004_50040101_168_dialog_content = "O mar é bom para nadar, né? Mas não trouxemos nenhum <color=#FFB400>traje de banho</color>.",
  ui_story_5004_50040101_169_dialog_content = "Não precisa se preocupar com isso.",
  ui_story_5004_50040101_170_dialog_content = "Esses hotéis vendem seus próprios trajes de banho.",
  ui_story_5004_50040101_171_dialog_content = "Afinal de contas, seus clientes são nobres de Lumópolis.",
  ui_story_5004_50040101_172_dialog_content = "Eles vendem até traje de banho? Pensaram em tudo mesmo.",
  ui_story_5004_50040101_173_dialog_content = "Claro. Trajes de banho na praia são como armaduras numa batalha.",
  ui_story_5004_50040101_174_dialog_content = "Seja você um soldado de Illumina ou um nobre de Lumópolis, traje de banho na praia é fundamental.",
  ui_story_5004_50040101_175_dialog_content = "É apenas a moda da praia!",
  ui_story_5004_50040101_176_dialog_content = "Entendo...",
  ui_story_5004_50040101_177_dialog_content = "(Por que é diferente do que Soroz me contou? É essa a função do traje de banho?)",
  ui_story_5004_50040101_178_dialog_content = "Como você sabe tanto sobre hotéis e trajes de banho, Carleen?",
  ui_story_5004_50040101_179_dialog_content = "Isso é estranho? Afinal, sou a Capitã dos Guardiões de Lumópolis.",
  ui_story_5004_50040101_180_dialog_content = "Parte do meu trabalho é ficar em dia com as tendências da nobreza.",
  ui_story_5004_50040101_181_dialog_content = "Enfim, estou ansiosa para provar meu biquíni, PlayerName.",
  ui_story_5004_50040101_182_dialog_content = "(Carleen de biquíni?)",
  ui_story_5004_50040101_183_dialog_content = "Ah, claro.",
  ui_story_5004_50040101_184_dialog_content = "Por que está me olhando assim, PlayerName?",
  ui_story_5004_50040101_185_dialog_content = "Estou estranha?",
  ui_story_5004_50040101_186_dialog_content = "De jeito nenhum! Ah, o que mais você sabe sobre esse hotel?",
  ui_story_5004_50040101_187_dialog_content = "Sei que pertencia a um nobre de Lumópolis.",
  ui_story_5004_50040101_188_dialog_content = "Até que foi vendido para alguém de Umbraton na tentativa de evitar a falência.",
  ui_story_5004_50040101_189_dialog_content = "Umbraton é um lugar confuso, então é difícil confirmar essa informação.",
  ui_story_5004_50040101_190_dialog_content = "Sem falar que o comprador está fazendo de tudo para permanecer anônimo.",
  ui_story_5004_50040101_191_dialog_content = "Forasteiros nunca saberiam de nada sem uma fonte local confiável.",
  ui_story_5004_50040101_192_dialog_content = "Entendi. Umbraton é mesmo indecifrável.",
  ui_story_5004_50040101_193_dialog_content = "Sim. Sua estabilidade e harmonia atual se devem a...",
  ui_story_5004_50040101_194_dialog_content = "Espera, chega de conversa séria!",
  ui_story_5004_50040101_195_dialog_content = "O objetivo dessa viagem é ajudar Beryl a relaxar e se recuperar.",
  ui_story_5004_50040101_196_dialog_content = "Estou bem...",
  ui_story_5004_50040101_197_dialog_content = "!!!",
  ui_story_5004_50040101_198_dialog_content = "PlayerName?!",
  ui_story_5004_50040101_199_dialog_content = "Soroz!",
  ui_story_5004_50040101_200_dialog_content = "Foi detectada uma forte interferência no sistema de navegação vindo do nosso destino, PlayerName.",
  ui_story_5004_50040101_201_dialog_content = "Se continuarmos, poderemos perder o controle.",
  ui_story_5004_50040101_202_dialog_content = "Argh...!",
  ui_story_5004_50040101_203_dialog_content = "Beryl?",
  ui_story_5004_50040101_204_dialog_content = "O que foi?",
  ui_story_5004_50040101_205_dialog_content = "Afaste-se do destino e encontre um lugar para pousar imediatamente, Soroz!",
  ui_story_5004_50040101_206_dialog_content = "Entendi.",
  ui_story_5004_50040101_207_dialog_content = "Você tá bem, Beryl?",
  ui_story_5004_50040101_208_dialog_content = "Onde...",
  ui_story_5004_50040101_209_dialog_content = "Onde estou?",
  ui_story_5004_50040101_210_dialog_content = "O calor das chamas, o cheiro de fumaça, os gritos de inúmeros Aurorians...",
  ui_story_5004_50040101_211_dialog_content = "Mas não consigo ver nada...",
  ui_story_5004_50040101_212_dialog_content = "Onde estou, exatamente?",
  ui_story_5004_50040101_213_dialog_content = "PlayerName!",
  ui_story_5004_50040101_214_dialog_content = "PlayerName!!",
  ui_story_5004_50040101_215_dialog_content = "Vice?",
  ui_story_5004_50040101_216_dialog_content = "Você tá bem, PlayerName?",
  ui_story_5004_50040101_217_dialog_content = "O que houve?",
  ui_story_5004_50040101_218_dialog_content = "Você ficou paralisado depois de esbarrar na Beryl.",
  ui_story_5004_50040101_219_dialog_content = "Sentiu alguma coisa?",
  ui_story_5004_50040101_220_dialog_content = "Sim, mas era como um borrão... Não importa. Qual a nossa situação atual?",
  ui_story_5004_50040101_221_dialog_content = "Estamos fora do alcance da interferência e agora estou buscando um lugar para pousar.",
  ui_story_5004_50040101_222_dialog_content = "Você tá bem, Beryl?",
  ui_story_5004_50040101_223_dialog_content = "Sim...",
  ui_story_5004_50040101_224_dialog_content = "O que foi aquilo?",
  ui_story_5004_50040201_1_dialog_content = "O que... Por que eu preciso levar vocês? Não fui eu quem forçou a Colossus a pousar!",
  ui_story_5004_50040201_2_dialog_content = "Eu tava pensando em tocar no bar.",
  ui_story_5004_50040201_3_dialog_content = "Aquele hotel sei-lá-o-quê realmente tem um super sistema de som de luxo?",
  ui_story_5004_50040201_4_dialog_content = "Se mentir pra mim... vou assar você com o poder do sol ardente!",
  ui_story_5004_50040201_5_dialog_content = "Pare de bater no teto antes que eu caia!",
  ui_story_5004_50040201_6_dialog_content = "Eles devem ter...",
  ui_story_5004_50040201_7_dialog_content = "Se não...",
  ui_story_5004_50040201_8_dialog_content = "Vou substituir o aparelho da Colossus por aquele sistema de som pauleira que você queria!",
  ui_story_5004_50040201_9_dialog_content = "Enfim, cuidado na direção. Eu ainda tô no teto! Valeu.",
  ui_story_5004_50040201_10_dialog_content = "Desculpe, PlayerName precisou ficar no teto do carro..",
  ui_story_5004_50040201_11_dialog_content = "Não tem problema. Eu tô bem...",
  ui_story_5004_50040201_12_dialog_content = "Não seria apropriado para as garotas.",
  ui_story_5004_50040201_13_dialog_content = "Não esperava que você fosse tão atencioso, PlayerName.",
  ui_story_5004_50040201_14_dialog_content = "Não tire os olhos da pista! E bota essas mãos no volante, por favor!",
  ui_story_5004_50040201_15_dialog_content = "Não esquenta. Todos os membros da Rediesel Wrench nasceram pra pilotar!",
  ui_story_5004_50040201_16_dialog_content = "Se aparecer um Eclipsita de alto nível, eu passo por cima.",
  ui_story_5004_50040201_17_dialog_content = "Sorte sua que o <color=#FFB400>carro</color> do <color=#FFB400>Brock</color> tava na garagem, ou você iria a pé...",
  ui_story_5004_50040201_18_dialog_content = "Cuidado!",
  ui_story_5004_50040201_19_dialog_content = "Regina, Eclipsitas!",
  ui_story_5004_50040201_20_dialog_content = "Hã?",
  ui_story_5004_50040201_21_dialog_content = "Ai! Malditos Eclipsitas, apareceram do nada! Minha primeira vez dirigindo em vinte anos...",
  ui_story_5004_50040201_22_dialog_content = "Aahhhhhh!",
  ui_story_5004_50040201_23_dialog_content = "Argh, que tontura... Será que o impacto arremessou o Eclipsita pra longe?",
  ui_story_5004_50040201_24_dialog_content = "Tá todo mundo bem?",
  ui_story_5004_50040201_25_dialog_content = "Sim, foi só um arranhão.",
  ui_story_5004_50040201_26_dialog_content = "Wooga!",
  ui_story_5004_50040201_27_dialog_content = "De onde vieram todos esses Eclipsitas? Preparem-se para lutar!",
  ui_story_5004_50040201_28_dialog_content = "Rápido! As armas estão no porta-malas!",
  ui_story_5004_50040201_29_dialog_content = "Daqui a pouco vamos ficar cercados!",
  ui_story_5004_50040201_30_dialog_content = "Beryl, acorda. Beryl!",
  ui_story_5004_50040201_31_dialog_content = "Ai...",
  ui_story_5004_50040201_32_dialog_content = "Raphaela...",
  ui_story_5004_50040201_33_dialog_content = "Cuidado!",
  ui_story_5004_50040201_34_dialog_content = "...!",
  ui_story_5004_50040201_35_dialog_content = "Crystal...",
  ui_story_5004_50040201_36_dialog_content = "Argh...",
  ui_story_5004_50040201_37_dialog_content = "Gah!! Gah!!!",
  ui_story_5004_50040201_38_dialog_content = "Estão tentando virar o carro!",
  ui_story_5004_50040201_39_dialog_content = "Floresça!",
  ui_story_5004_50040201_40_dialog_content = "Grr...",
  ui_story_5004_50040201_41_dialog_content = "Nossa, isso foi rápido!",
  ui_story_5004_50040201_42_dialog_content = "Não esperava que você tivesse tanto poder.. Acho que a True Order não brinca em serviço.",
  ui_story_5004_50040201_43_dialog_content = "O número de cristais liberados e de Eclipsitas derrotados num piscar de olhos se equipara ao poder dos Anjos de Lumópolis.",
  ui_story_5004_50040201_44_dialog_content = "De fato.",
  ui_story_5004_50040201_45_dialog_content = "Isso foi incrível... Ah, valeu, Beryl!",
  ui_story_5004_50040201_46_dialog_content = "Arf, arf...",
  ui_story_5004_50040201_47_dialog_content = "Você tá bem, Beryl?",
  ui_story_5004_50040201_48_dialog_content = "Já acabou o bate-papo? Peguem suas armas, tem mais Eclipsitas a caminho!",
  ui_story_5004_50040301_1_dialog_content = "Ufa, quase lá. Nunca mais quero dirigir na vida.",
  ui_story_5004_50040301_2_dialog_content = "Valeu por trazer a gente em um só pedaço.",
  ui_story_5004_50040301_3_dialog_content = "Deixa de conversa e encontra um lugar pra estacionar.",
  ui_story_5004_50040301_4_dialog_content = "Ei, o que vocês estão fazendo aqui?",
  ui_story_5004_50040301_5_dialog_content = "Ei... por que o capô do meu carro tá todo amassado?",
  ui_story_5004_50040301_6_dialog_content = "Somos amigos, PlayerName, mas é melhor me contar logo o que aconteceu!",
  ui_story_5004_50040301_7_option_content = "Bem, na verdade Regina queria pegar o carro pra dar uma volta...",
  ui_story_5004_50040301_8_dialog_content = "Bela tentativa. Ela não dirigiria nem se precisasse ir pra um show de rock.",
  ui_story_5004_50040301_9_dialog_content = "O que você sabe sobre ela?",
  ui_story_5004_50040301_10_dialog_content = "Ei! Por acaso eu tenho cara de quem tá escondendo alguma coisa?",
  ui_story_5004_50040301_11_dialog_content = "Então, PlayerName concordou em melhorar o sistema de som pra você?",
  ui_story_5004_50040301_12_dialog_content = "Não acredito, Brock. Você acertou!",
  ui_story_5004_50040301_13_dialog_content = "Mas é claro, eu não sou burro! Saquei isso desde o começo.",
  ui_story_5004_50040301_14_option_content = "Eu concertei o carro e resolvi trazer ele especialmente pra você!",
  ui_story_5004_50040301_15_dialog_content = "É mesmo? Eu te disse que estaria aqui?",
  ui_story_5004_50040301_16_dialog_content = "Eu usei habilidades psíquicas. Pode crer.",
  ui_story_5004_50040301_17_dialog_content = "Dessa distância? Incrível!",
  ui_story_5004_50040301_18_dialog_content = "A marca no capô tem a forma de um Eclipsita...",
  ui_story_5004_50040301_19_dialog_content = "Você consegue perceber?",
  ui_story_5004_50040301_20_dialog_content = "Não me subestime. Eu bato em centenas de Eclipsitas todo ano.",
  ui_story_5004_50040301_21_dialog_content = "Conheço esse formato de longe! Você bateu de frente com um Rompe-Linha?",
  ui_story_5004_50040301_22_dialog_content = "Você sabe até mesmo o tipo? Ops, foi mal, eu conserto pra você depois.",
  ui_story_5004_50040301_23_dialog_content = "Não esquenta, você adicionou mais um Eclipsita pro histórico do meu bebê.",
  ui_story_5004_50040301_24_dialog_content = "Vou chamar um <color=#FFB400>mecânico</color> amigo meu pra consertar.",
  ui_story_5004_50040301_25_dialog_content = "Aliás, por que vocês vieram até aqui? Tirando umas férias?",
  ui_story_5004_50040301_26_dialog_content = "Sim! PlayerName recebeu um convite do Hotel Tir' com tudo pago!",
  ui_story_5004_50040301_27_dialog_content = "Como? Que estranho. Não sabia que o proprietário era tão generoso.",
  ui_story_5004_50040301_28_dialog_content = "Talvez o proprietário queira se aproveitar do status de Celestita de PlayerName pra promover o hotel.",
  ui_story_5004_50040301_29_dialog_content = "Hmm, isso faz mais sentido.",
  ui_story_5004_50040301_X29_dialog_content = "É você!",
  ui_story_5004_50040301_30_dialog_content = "Você é o bandido da Rediesel Wrench que escapou da prisão...",
  ui_story_5004_50040301_31_dialog_content = "Espera! Estamos viajando com a Beryl, não caçando criminosos!",
  ui_story_5004_50040301_32_dialog_content = "E não estamos em Lumópolis, de qualquer forma. Não precisamos brigar!",
  ui_story_5004_50040301_33_dialog_content = "Está bem.",
  ui_story_5004_50040301_34_dialog_content = "Mas se você se atrever a prejudicar Lumópolis enquanto isso,",
  ui_story_5004_50040301_35_dialog_content = "vou levar você de volta para ser julgado.",
  ui_story_5004_50040301_36_dialog_content = "Mas e então, por que tá aqui, Brock? Você parece conhecer bem o proprietário.",
  ui_story_5004_50040301_37_dialog_content = "Sobre isso... Vim aqui ajudar  um velho amigo, o mecânico de quem eu falei.",
  ui_story_5004_50040301_38_dialog_content = "É que... ele já cuidou de mim e do meu carro várias vezes. É assim que pagamos nossas dívidas na Rediesel Wrench!",
  ui_story_5004_50040301_39_dialog_content = "Você deve acabar encontrando ele se estiver indo para o Hotel Tir'.",
  ui_story_5004_50040301_40_dialog_content = "Ele não é exatamente do tipo que passa despercebido.",
  ui_story_5004_50040301_41_dialog_content = "Ah, mais uma coisa.",
  ui_story_5004_50040301_42_dialog_content = "Soroz se deparou com uma interferência no caminho até aqui. Sabe algo sobre isso?",
  ui_story_5004_50040301_43_dialog_content = "Não. Eu nunca pilotei uma Colossus.",
  ui_story_5004_50040301_44_dialog_content = "Você age como se todo mundo tivesse uma.",
  ui_story_5004_50040301_45_dialog_content = "Mas as Colossi são um misto de ser vivo e máquina, né?",
  ui_story_5004_50040301_46_dialog_content = "Talvez Soroz tenha pego um resfriado.",
  ui_story_5004_50040301_47_dialog_content = "<size=30>PlayerName, eu deveria rir dessa piada?</size>",
  ui_story_5004_50040301_48_dialog_content = "<size=30>Não sei. É difícil dizer quando ele tá brincando ou falando sério.</size>",
  ui_story_5004_50040301_49_dialog_content = "Pare de cochichar na minha frente.",
  ui_story_5004_50040301_50_dialog_content = "Vou levar o meu carro. Você vai acabar no hotel se seguir essa estrada.",
  ui_story_5004_50040301_51_dialog_content = "(As ondas azuis quebrando sobre a areia dourada criam um cenário tão bonito.)",
  ui_story_5004_50040301_52_dialog_content = "(Árvores verdes e frondosas, cujos nomes eu desconheço, balançando com a brisa marinha.)",
  ui_story_5004_50040301_53_dialog_content = "(Algumas pessoas estão brincando na areia.)",
  ui_story_5004_50040301_54_dialog_content = "(Me deixo levar pela paisagem. Tudo aqui, sob a luz do sol, é tão vibrante.)",
  ui_story_5004_50040301_55_dialog_content = "...",
  ui_story_5004_50040301_56_dialog_content = "Esse lugar... é muito melhor do que eu pensei.",
  ui_story_5004_50040301_57_dialog_content = "Essa é a praia, PlayerName?",
  ui_story_5004_50040301_58_dialog_content = "Nunca pensei que haveria um lugar tão relaxante em meio à crise atual.",
  ui_story_5004_50040301_59_dialog_content = "O mar é tão lindo...",
  ui_story_5004_50040301_60_dialog_content = "Tem uma fila enorme naquela barraca! Beryl, vamos lá ver o que estão vendendo!",
  ui_story_5004_50040301_61_dialog_content = "Heh, vejo que todos vocês estão gostando da <color=#FFB400>Costa Celestial</color>, não é?",
  ui_story_5004_50040301_62_dialog_content = "?!",
  ui_story_5004_50040301_63_dialog_content = "Bem-vindos. Sou <color=#FFB400>Bonacie</color>, a representante do hotel e anfitriã do Monarca do Oceano!",
  ui_story_5004_50040301_64_dialog_content = "Oi, Bonacie.",
  ui_story_5004_50040301_65_dialog_content = "Você também está aqui, Beryl! Aquele cara irritante de óculos tá com você?",
  ui_story_5004_50040301_66_dialog_content = "O sr. Faust? Ele precisava trabalhar e me deixou com PlayerName.",
  ui_story_5004_50040301_67_dialog_content = "Esplêndido. Então você deve ser PlayerName, certo?",
  ui_story_5004_50040301_68_dialog_content = "Que adorável, um patinho sortudo no meio de lindas damas, hã?",
  ui_story_5004_50040301_69_dialog_content = "Somos só amigos.",
  ui_story_5004_50040301_70_dialog_content = "Claro, só amigos, hehe.",
  ui_story_5004_50040301_71_dialog_content = "Mas não vejo nada peculiar em PlayerName para um Celestita. Nenhum olho a mais, nenhum chifre...",
  ui_story_5004_50040301_72_option_content = "Eu deveria me desculpar por isso?",
  ui_story_5004_50040301_73_dialog_content = "Você tem um ótimo senso de humor, né?",
  ui_story_5004_50040301_74_option_content = "Celestitas e Aurorians têm uma aparência muito similar.",
  ui_story_5004_50040301_75_dialog_content = "É engraçado ver você responder de forma tão séria.",
  ui_story_5004_50040301_76_dialog_content = "Era só uma piada. Por favor, não leve a mal.",
  ui_story_5004_50040301_77_dialog_content = "Todos vocês são hóspedes VIP do hotel e convidados de honra do Monarca do Oceano.",
  ui_story_5004_50040301_78_dialog_content = "Permitam que eu, Bonacie, mostre a vocês o deslumbrante e exótico verão na praia e seus encantos...",
  ui_story_5004_50040301_79_dialog_content = "Agradeço, mas estamos bem...",
  ui_story_5004_50040301_80_dialog_content = "Eu tenho uma pergunta. O que exatamente é o Monarca do Oceano?",
  ui_story_5004_50040301_81_dialog_content = "É uma cerimônia deixada pelos Aurorians que viviam nessa praia.",
  ui_story_5004_50040301_82_dialog_content = "\"O mar é a origem de toda a vida, abraçando e nutrindo a todos em seu seio.\"",
  ui_story_5004_50040301_83_dialog_content = "\"A deusa do mar dança ao lado de todos os competidores aqui.\"",
  ui_story_5004_50040301_84_dialog_content = "No Monarca do Oceano, os participantes enfrentarão as lendárias provações.",
  ui_story_5004_50040301_85_dialog_content = "Um vencedor será definido após disputas de <color=#FFB400>força</color>, <color=#FFB400>sabedoria</color> e <color=#FFB400>bravura</color>.",
  ui_story_5004_50040301_86_dialog_content = "Os deuses concederão ao campeão recompensas e abençoarão essa bela região.",
  ui_story_5004_50040301_87_dialog_content = "O vencedor também receberá o título de <color=#FFB400>Guerreiro da Praia</color>,",
  ui_story_5004_50040301_88_dialog_content = "e até mesmo um misterioso grande prêmio!",
  ui_story_5004_50040301_89_dialog_content = "Aproveite o sul e divirta-se enquanto compete com as garotas nas disputas.",
  ui_story_5004_50040301_90_dialog_content = "Você não vai recusar, não é, PlayerName?",
  ui_story_5004_50040301_91_dialog_content = "Guerreiro... da Praia...",
  ui_story_5004_50040301_92_dialog_content = "Ainda preciso conversar melhor com todos.",
  ui_story_5004_50040301_93_dialog_content = "Tudo bem. Deixe-me levá-los até o hotel para acomodar todos.",
  ui_story_5004_50040301_94_dialog_content = "O festival começa depois de amanhã. Aproveitem para relaxar um pouco da forma que preferirem.",
  ui_story_5004_50040301_95_dialog_content = "Aqui é tão luxuoso!",
  ui_story_5004_50040301_96_dialog_content = "É de fato uma arquitetura diferente de Lumópolis e Illumina.",
  ui_story_5004_50040301_97_dialog_content = "Provavelmente é herança de uma civilização antiga.",
  ui_story_5004_50040301_98_dialog_content = "Aqui é o saguão. Vou deixá-los com o gerente, <color=#FFB400>Fleur</color>!",
  ui_story_5004_50040301_99_dialog_content = "Hmm, Fleur? Pode dar uma pressinha?",
  ui_story_5004_50040301_100_dialog_content = "Tenho outros assuntos pra resolver, mas volto logo em seguida.",
  ui_story_5004_50040301_101_dialog_content = "Fleur?",
  ui_story_5004_50040301_102_dialog_content = "Foi mal!",
  ui_story_5004_50040301_103_dialog_content = "Já chego aí!",
  ui_story_5004_50040301_104_dialog_content = "Fleur!",
  ui_story_5004_50040301_105_dialog_content = "Sr. Fleur!",
  ui_story_5004_50040301_106_dialog_content = "Você está livre hoje à noite, sr. Fleur?",
  ui_story_5004_50040301_107_dialog_content = "Me leve para a academia e vou te mostrar meu tanquinho!",
  ui_story_5004_50040301_108_dialog_content = "Acabei de preparar isso. Abra bem a boca e experimente...",
  ui_story_5004_50040301_109_dialog_content = "O que tá acontecendo? Uma multidão esquisita ao redor daquele tal Fleur.",
  ui_story_5004_50040301_110_dialog_content = "Tem alguma coisa estranha em relação àquele cara.",
  ui_story_5004_50040301_111_dialog_content = "Parece que Fleur é mais popular que você, PlayerName.",
  ui_story_5004_50040301_112_dialog_content = "Pare de caçoar de mim...",
  ui_story_5004_50040301_113_dialog_content = "Mil desculpas. Sou Fleur. Vocês devem ser o grupo da Colossus.",
  ui_story_5004_50040301_114_dialog_content = "PlayerName, Brock fala bastante de você.",
  ui_story_5004_50040301_115_dialog_content = "Você conhece o Brock?",
  ui_story_5004_50040301_116_dialog_content = "Sim. Na verdade, sou um mecânico da Rediesel Wrench e o conheço há muito tempo.",
  ui_story_5004_50040301_117_dialog_content = "Então é você o mecânico de quem Brock estava falando! (E também é muito suspeito.)",
  ui_story_5004_50040301_118_dialog_content = "Sim, eu pedi a ajuda dele.",
  ui_story_5004_50040301_119_dialog_content = "Eu me lembro, Fleur é uma lenda na Academia de Mecânica de Illumina!",
  ui_story_5004_50040301_120_dialog_content = "Ouvi alunos mais velhos em Illumina falando sobre você.",
  ui_story_5004_50040301_121_dialog_content = "Dizem que você leva jeito com máquinas e que é gentil, <size=40>mas também contam </size><size=35>outras histórias meio esquisitas</size> e <size=30><color=#FFB400>não tão legais</color> assim...</size>",
  ui_story_5004_50040301_122_dialog_content = "É, foi por isso que ele correu para a Rediesel Wrench.",
  ui_story_5004_50040301_123_dialog_content = "E ajudou Sinsa a consertar Lepidoz. Impressionante.",
  ui_story_5004_50040301_124_dialog_content = "Você não recebeu umas folgas de Sinsa para tirar férias de verão?",
  ui_story_5004_50040301_125_dialog_content = "E aqui está você, gerenciando um saguão... ainda que não se pareça com um gerente.",
  ui_story_5004_50040301_126_dialog_content = "Você não deveria ao menos usar uma gravata, como aqueles nobres Lumo convencidos?",
  ui_story_5004_50040301_127_dialog_content = "...",
  ui_story_5004_50040301_128_dialog_content = "(Ei, temos uma nobre Lumo conosco!)",
  ui_story_5004_50040301_129_dialog_content = "Estou aqui a  pedido de Bonacie, além de algumas outras coisas.",
  ui_story_5004_50040301_130_dialog_content = "Acho que te enganaram direitinho, mas isso é a sua cara.",
  ui_story_5004_50040301_131_dialog_content = "Meu trabalho de guia e motorista acaba aqui. Hora de conferir aqueles sistemas de som no bar.",
  ui_story_5004_50040301_132_dialog_content = "Não me procure, a não ser que aconteça algum problema.",
  ui_story_5004_50040301_133_dialog_content = "Vai com calma, Regina.",
  ui_story_5004_50040301_134_dialog_content = "Por aqui, pessoal. Vou acomodar vocês.",
  ui_story_5004_50040301_135_dialog_content = "Como vocês gostariam de dividir os quartos?",
  ui_story_5004_50040301_136_dialog_content = "Bem, eu quero...",
  ui_story_5004_50040301_137_dialog_content = "Eu, eu! Quero dividir um quarto com a Beryl!",
  ui_story_5004_50040301_138_dialog_content = "Sou sua médica particular, e não posso ficar longe dela!",
  ui_story_5004_50040301_139_dialog_content = "Tudo bem, né? Né?",
  ui_story_5004_50040301_140_dialog_content = "Tá... Tá bem. Não tem problema.",
  ui_story_5004_50040301_141_dialog_content = "Vice e eu vamos ficar em quartos separados.",
  ui_story_5004_50040301_142_option_content = "Quer dizer que eu...",
  ui_story_5004_50040301_143_dialog_content = "Você vai dormir sozinho, claro. Não me diga que tem medo do escuro, depois de mais de uma década a bordo de Soroz?",
  ui_story_5004_50040301_144_dialog_content = "Claro que não!",
  ui_story_5004_50040301_145_option_content = "E a Regina?",
  ui_story_5004_50040301_146_dialog_content = "Regina? Ela vai passar dias fuçando os sistemas de som.",
  ui_story_5004_50040301_147_dialog_content = "Posso acomodá-la e entregar sua chave depois.",
  ui_story_5004_50040301_148_dialog_content = "Então ficam cinco quartos no total.",
  ui_story_5004_50040301_149_dialog_content = "Hm, gorjetas...",
  ui_story_5004_50040301_150_dialog_content = "Estes são hóspedes VIPs, não podemos pedir gorjeta a eles. Lembre-se disso, certo?",
  ui_story_5004_50040301_151_dialog_content = "Ah, tá.",
  ui_story_5004_50040301_152_dialog_content = "Aqui estão suas chaves.",
  ui_story_5004_50040301_153_dialog_content = "Tem algo estranho com aquele atendente...",
  ui_story_5004_50040301_154_dialog_content = "Haha, isso não foi muito educado da sua parte, PlayerName",
  ui_story_5004_50040301_155_dialog_content = "Eu também tenho chifres.",
  ui_story_5004_50040301_156_dialog_content = "Mesmo assim, espero que todos se sintam à vontade.",
  ui_story_5004_50040301_157_dialog_content = "(Uma pessoa bondosa...)",
  ui_story_5004_50040301_158_dialog_content = "Pra ser sincero, eles podem ser meio estranhos...",
  ui_story_5004_50040301_159_dialog_content = "O proprietário os contratou pelos baixos salários e horas extras não remuneradas.",
  ui_story_5004_50040301_160_dialog_content = "Então vários deles estão aqui por isso.",
  ui_story_5004_50040301_161_dialog_content = "O Brock disse que o proprietário não faz o tipo empresário.",
  ui_story_5004_50040301_162_dialog_content = "Parece que o proprietário é o líder de uma gangue em Umbraton,",
  ui_story_5004_50040301_163_dialog_content = "com um tino para negócios e louco por dinheiro. Dizem que ele participa de atividades suspeitas enquanto gerencia esse hotel.",
  ui_story_5004_50040301_164_dialog_content = "Não me sinto muito à vontade com isso, mas já que tenho um trato com Bonacie, estou preso aqui por enquanto.",
  ui_story_5004_50040301_165_dialog_content = "Ah, só um aviso. Tem algumas armadilhas para turistas no hotel e na praia. Elas podem custar muita grana.",
  ui_story_5004_50040301_166_dialog_content = "Quer dizer vendedores inescrupulosos? Muito bem, vamos ter cuidado.",
  ui_story_5004_50040301_167_dialog_content = "Deixe-me levá-los até os seus quartos. por aqui.",
  ui_story_5004_50040401_168_dialog_content = "Pode entrar, PlayerName.",
  ui_story_5004_50040401_169_dialog_content = "Esse é o meu quarto?",
  ui_story_5004_50040401_170_dialog_content = "Espero que goste.",
  ui_story_5004_50040401_171_dialog_content = "Ah, eu gostaria de conversar sobre máquinas com você, um dono de Colossus.",
  ui_story_5004_50040401_172_dialog_content = "Mas você deve estar exausto, então fica pra outra hora, se não for muito incômodo.",
  ui_story_5004_50040401_173_dialog_content = "Qualquer pergunta ou problema, não deixe de usar aquele <color=#FFB400>comunicador</color> pra ligar para o balcão.",
  ui_story_5004_50040401_174_dialog_content = "Tudo bem, obrigado.",
  ui_story_5004_50040401_175_dialog_content = "...",
  ui_story_5004_50040401_176_dialog_content = "O quarto está arrumado e parece ter uma cama macia. Posso ver a praia à noite da janela.",
  ui_story_5004_50040401_177_dialog_content = "É diferente da organização de Illumina e da sofisticação de Lumópolis, é mais viva e animada.",
  ui_story_5004_50040401_178_dialog_content = "Ufa...",
  ui_story_5004_50040401_179_dialog_content = "A cama é mesmo macia.",
  ui_story_5004_50040401_180_dialog_content = "Um convite inesperado, e agora estou deitado numa cama confortável na praia. Mas ainda não processei tudo isso...",
  ui_story_5004_50040401_181_dialog_content = "Sem falar do Monarca do Oceano... Parece esquisito. Será que devo participar?",
  ui_story_5004_50040401_182_dialog_content = "O que será que os outros estão fazendo agora?",
  ui_story_5004_50040401_183_dialog_content = "<color=#e8d9bb>Bip, bip, bip!</color>",
  ui_story_5004_50040401_184_dialog_content = "O que é isso? O comunicador que Fleur mencionou?",
  ui_story_5004_50040401_185_dialog_content = "Olá?",
  ui_story_5004_50040401_186_dialog_content = "Alô! Ei!",
  ui_story_5004_50040401_187_dialog_content = "Seu panfleto diz \"Descubra seu verdadeiro potencial para se fortalecer em sete dias.\" Isso é verdade?",
  ui_story_5004_50040401_188_dialog_content = "Brock? Do que você tá falando?",
  ui_story_5004_50040401_189_dialog_content = "PlayerName? Acho que disquei o número errado.",
  ui_story_5004_50040401_190_dialog_content = "A gente se vê depois!",
  ui_story_5004_50040401_191_dialog_content = "<color=#e8d9bb>Bip... bip...</color>",
  ui_story_5004_50040401_192_dialog_content = "Ele desligou. Espero que não tenha caído em nenhuma falcatrua.",
  ui_story_5004_50040401_193_dialog_content = "Acho que posso ligar para os outros discando o número do quarto, né?",
  ui_story_5004_50040401_194_dialog_content = "Vamos tentar...",
  ui_story_5004_50040401_195_option_content = "Ligar para Vice",
  ui_story_5004_50040401_196_dialog_content = "PlayerName?",
  ui_story_5004_50040401_197_dialog_content = "Não sabia que o hotel tinha comunicadores tão convenientes!",
  ui_story_5004_50040401_198_dialog_content = "Estou interrompendo alguma coisa? Só queria saber o que você tá fazendo agora.",
  ui_story_5004_50040401_199_dialog_content = "Não, nada demais. Só relaxando na cama... Ela é bem confortável!",
  ui_story_5004_50040401_200_dialog_content = "E então, você acha que a gente devia participar do Monarca do Oceano?",
  ui_story_5004_50040401_201_dialog_content = "Claro! Você ouviu o Fleur, né?",
  ui_story_5004_50040401_202_dialog_content = "Podemos ficar no hotel de graça, mas temos que pagar pelo resto: comida, trajes de banho e todas as atividades.",
  ui_story_5004_50040401_203_dialog_content = "Se ficarmos só gastando dinheiro sem receber nada, então...",
  ui_story_5004_50040401_204_dialog_content = "Eu... não faço o tipo atlético...",
  ui_story_5004_50040401_205_dialog_content = "Não se preocupe, você tem a mim e a todos os outros. Vamos trabalhar em equipe.",
  ui_story_5004_50040401_206_dialog_content = "Não se esqueça de que ninguém é melhor que você quando se trata de comandar, PlayerName!",
  ui_story_5004_50040401_207_dialog_content = "Acho que tem razão...",
  ui_story_5004_50040401_208_dialog_content = "Mas e se o prêmio não for em Noitium?",
  ui_story_5004_50040401_209_dialog_content = "Tudo bem, podemos dar para Sheol vender.",
  ui_story_5004_50040401_210_dialog_content = "Não se preocupe, PlayerName. Descanse um pouco, e com certeza vamos vencer!",
  ui_story_5004_50040401_211_dialog_content = "Se é assim que você se sente, então vamos lá!",
  ui_story_5004_50040401_212_option_content = "Ligar para Carleen",
  ui_story_5004_50040401_213_dialog_content = "PlayerName? Algum problema?",
  ui_story_5004_50040401_214_dialog_content = "Desculpe. Só queria saber o que você tá fazendo, Carleen.",
  ui_story_5004_50040401_215_dialog_content = "Me preparando para dormir, de acordo com meu cronograma diário.",
  ui_story_5004_50040401_216_dialog_content = "Você é tão disciplinada.",
  ui_story_5004_50040401_217_dialog_content = "Ah, o que você acha do Monarca do Oceano?",
  ui_story_5004_50040401_218_dialog_content = "Nós certamente vamos vencer.",
  ui_story_5004_50040401_219_dialog_content = "Como pode dizer isso, se ainda nem decidimos se vamos participar?",
  ui_story_5004_50040401_220_dialog_content = "Por que não? Fomos convidados por um motivo. É nosso destino responder ao desafio.",
  ui_story_5004_50040401_221_dialog_content = "Um verdadeiro guerreio nunca recua.",
  ui_story_5004_50040401_222_dialog_content = "Sei que você deve estar confuso e ansioso, PlayerName.",
  ui_story_5004_50040401_223_dialog_content = "Mas acredite quando digo que você pode superar os obstáculos e seguir seu próprio caminho.",
  ui_story_5004_50040401_224_dialog_content = "Você é especial para todos os Aurorians, inclusive para mim.",
  ui_story_5004_50040401_225_dialog_content = "Você tá me dando coragem?",
  ui_story_5004_50040401_226_dialog_content = "Claro, esse é meu discurso motivacional.",
  ui_story_5004_50040401_227_dialog_content = "Não é à toa que você é a Capitã dos Guardiões de Lumópolis. Já me sinto inspirado.",
  ui_story_5004_50040401_228_dialog_content = "Ótimo. Agora descanse.",
  ui_story_5004_50040401_229_dialog_content = "Tudo bem. Vou cair na cama, agora que decidimos participar do Monarca do Oceano!",
  ui_story_5004_50040401_230_dialog_content = "Falando nisso, todos os quartos possuem apenas uma cama de solteiro?",
  ui_story_5004_50040401_230X1_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5004_50040401_230X2_dialog_content = "Ai!",
  ui_story_5004_50040401_230X3_dialog_content = "Desculpa! Você está bem?",
  ui_story_5004_50040401_230X4_dialog_content = "Por que você ficou na porta com uma bandeja na mão? Isso não podia acabar bem!",
  ui_story_5004_50040401_230X5_dialog_content = "Arf, arf... Você corre muito rápido, Raphaela...",
  ui_story_5004_50040401_230X6_dialog_content = "Eu estava entregando a sobremesa que o hóspede desse quarto pediu.",
  ui_story_5004_50040401_230X7_dialog_content = "Se acabamos aqui, eu preciso ir. A cozinha tá movimentada.",
  ui_story_5004_50040401_230X8_dialog_content = "Por que tá tão barulhento lá fora?",
  ui_story_5004_50040401_230X9_dialog_content = "<color=#e8d9bb>Toc, toc!</color>",
  ui_story_5004_50040401_231_dialog_content = "E sobre Beryl, e...",
  ui_story_5004_50040401_232_dialog_content = "Estamos aqui pra ficar com você, PlayerName! Ei, você tá lanchando escondido?",
  ui_story_5004_50040401_233_dialog_content = "Raphaela? Não, não tô comendo nada...",
  ui_story_5004_50040401_234_dialog_content = "B-Boa noite...",
  ui_story_5004_50040401_235_dialog_content = "Você também tá aqui, Beryl?",
  ui_story_5004_50040401_236_dialog_content = "Não tem nada pra dizer a PlayerName, Beryl?",
  ui_story_5004_50040401_237_dialog_content = "Bom...",
  ui_story_5004_50040401_238_dialog_content = "Está com vergonha? Quer que eu diga?",
  ui_story_5004_50040401_239_dialog_content = "Sim...",
  ui_story_5004_50040401_240_dialog_content = "OK.",
  ui_story_5004_50040401_241_dialog_content = "É que Beryl quer muito participar do Monarca do Oceano.",
  ui_story_5004_50040401_242_dialog_content = "Claro.",
  ui_story_5004_50040401_243_dialog_content = "Mas ela não pode participar.",
  ui_story_5004_50040401_244_dialog_content = "O quê?",
  ui_story_5004_50040401_245_dialog_content = "Você não consegue usar essa cabeça, PlayerName?",
  ui_story_5004_50040401_246_dialog_content = "Não culpe PlayerName, Raphaela. Eu não me expressei bem.",
  ui_story_5004_50040401_247_dialog_content = "PlayerName, lembra das recompensas que Bonacie mencionou?",
  ui_story_5004_50040401_248_dialog_content = "Ah, a Beryl precisa de dinheiro? Na verdade, eu...",
  ui_story_5004_50040401_249_dialog_content = "Não, o título de Guerreiro da Praia!",
  ui_story_5004_50040401_250_dialog_content = "...",
  ui_story_5004_50040401_251_dialog_content = "Que cara é essa? Você tem algum problema com o sonho de uma garotinha inocente?",
  ui_story_5004_50040401_252_dialog_content = "Nunca! Eu só me distraí por um momento.",
  ui_story_5004_50040401_253_dialog_content = "Está falando sério, Beryl?",
  ui_story_5004_50040401_254_dialog_content = "Sim...!",
  ui_story_5004_50040401_255_dialog_content = "Cooperação não é o problema. Todo mundo está pensando a mesma coisa.",
  ui_story_5004_50040401_256_dialog_content = "Sério?",
  ui_story_5004_50040401_257_dialog_content = "Isso é ótimo!",
  ui_story_5004_50040401_258_dialog_content = "Mas o que quis dizer sobre não participar?",
  ui_story_5004_50040401_259_dialog_content = "Bem, Beryl...",
  ui_story_5004_50040401_260_dialog_content = "Posso contar pessoalmente a PlayerName. Obrigada, Raphaela.",
  ui_story_5004_50040401_261_dialog_content = "Ufa...",
  ui_story_5004_50040401_262_dialog_content = "Hoje, você viu do que eu sou capaz...",
  ui_story_5004_50040401_263_dialog_content = "Sim, foi um poder incrível.",
  ui_story_5004_50040401_264_dialog_content = "Mas eu também posso perder o controle facilmente... é perigoso.",
  ui_story_5004_50040401_265_dialog_content = "Quanto mais poder eu libero, mais isso me afeta física e emocionalmente...",
  ui_story_5004_50040401_266_dialog_content = "Eu me esforcei demais para derrotar aqueles Eclipsitas e não posso participar de atividades pesadas pelos próximos dias.",
  ui_story_5004_50040401_267_dialog_content = "Entendi. Certo, você nos ajudou, e agora todos nós vamos te ajudar!",
  ui_story_5004_50040401_268_dialog_content = "Vou conversar com os outros e colocar você na equipe reserva.",
  ui_story_5004_50040401_269_dialog_content = "Você decide se ou quando estará pronta pra participar da disputa.",
  ui_story_5004_50040401_270_dialog_content = "Assim está bom pra você?",
  ui_story_5004_50040401_271_dialog_content = "Sim!",
  ui_story_5004_50040401_272_dialog_content = "Mas eu tenho uma pergunta. Você disse antes que isso tem um impacto emocional. Pode ser mais específica?",
  ui_story_5004_50040401_273_dialog_content = "Eu fico muito triste e deprimida, o que aumenta o meu poder... e a chance de eu perder o controle.",
  ui_story_5004_50040401_274_dialog_content = "Isso sim é um círculo vicioso!",
  ui_story_5004_50040401_275_dialog_content = "Uhum.",
  ui_story_5004_50040401_276_dialog_content = "Espero que um dia você se livre da tristeza e da depressão, e encontre a coragem para controlar esse poder.",
  ui_story_5004_50040401_277_dialog_content = "Espero ansiosamente isso acontecer.",
  ui_story_5004_50040501_1_dialog_content = "...",
  ui_story_5004_50040501_2_dialog_content = "...",
  ui_story_5004_50040501_3_dialog_content = "Ainda não me acostumei a dormir longe da Colossus.",
  ui_story_5004_50040501_4_option_content = "Tentar sair da cama",
  ui_story_5004_50040501_5_dialog_content = "<color=#e8d9bb>Toc, toc!</color>",
  ui_story_5004_50040501_6_dialog_content = "Está acordado, PlayerName?",
  ui_story_5004_50040501_7_option_content = "Tentar sair da cama novamente",
  ui_story_5004_50040501_8_dialog_content = "Sim. Espera só um segundo enquanto me levanto.",
  ui_story_5004_50040501_9_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5004_50040501_10_dialog_content = "Bom dia, PlayerName. Hora de levantar.",
  ui_story_5004_50040501_11_dialog_content = "Carleen e os outros estão esperando no refeitório!",
  ui_story_5004_50040501_12_dialog_content = "Bom dia, PlayerName. Parece que você não dormiu muito bem.",
  ui_story_5004_50040501_13_dialog_content = "Bom dia. Não estou acostumado a dormir longe da Colossus...",
  ui_story_5004_50040501_14_dialog_content = "Mas não tem problema, eu gosto de experiências especiais como essa.",
  ui_story_5004_50040501_15_dialog_content = "Já vivi coisas que nunca imaginei antes desde que conheci Vice e Carleen.",
  ui_story_5004_50040501_16_dialog_content = "Você parece mais maduro quando fala assim, PlayerName.",
  ui_story_5004_50040501_17_dialog_content = "Tem alguma magia na brisa marinha?",
  ui_story_5004_50040501_18_dialog_content = "Haha... Ou talvez tenha sido a falta de sono da noite passada.",
  ui_story_5004_50040501_19_dialog_content = "E vocês, Raphaela e Beryl?",
  ui_story_5004_50040501_20_option_content = "Dormiram bem?",
  ui_story_5004_50040501_21_dialog_content = "Muito bem, apesar da cama estar meio cheia.",
  ui_story_5004_50040501_22_dialog_content = "(Eu sabia, só tem uma cama.)",
  ui_story_5004_50040501_23_dialog_content = "Uma curiosidade sobre Beryl, PlayerName: ela gosta de dormir abraçada com alguma coisa! Não é uma gracinha?",
  ui_story_5004_50040501_24_dialog_content = "É normal segurar um travesseiro ao dormir... certo?",
  ui_story_5004_50040501_25_option_content = "Tem uma cama de casal no seu quarto?",
  ui_story_5004_50040501_26_dialog_content = "Não, é pequeno demais...",
  ui_story_5004_50040501_27_dialog_content = "Porque além da gente, tem um travesseiro gigante.",
  ui_story_5004_50040501_28_dialog_content = "Isso é m...",
  ui_story_5004_50040501_29_dialog_content = "Não imaginei que Beryl gostasse de segurar algo enquanto dorme.",
  ui_story_5004_50040501_30_dialog_content = "É normal segurar um travesseiro ao dormir!",
  ui_story_5004_50040501_31_dialog_content = "Claro, um travesseiro durante parte da noite...",
  ui_story_5004_50040501_32_dialog_content = "Podemos mudar de assunto, por favor?",
  ui_story_5004_50040501_33_dialog_content = "Bom dia, pessoal! Descansaram bastante?",
  ui_story_5004_50040501_34_dialog_content = "E aí, bom dia, Fleur!",
  ui_story_5004_50040501_35_dialog_content = "Foi bom. As acomodações eram boas e a cama muito confortável.",
  ui_story_5004_50040501_36_dialog_content = "Mas ainda estou me adaptando.",
  ui_story_5004_50040501_37_dialog_content = "Hahaha, vários clientes já falaram isso, mas sei que você dará um jeito.",
  ui_story_5004_50040501_38_dialog_content = "As pessoas se sentem mais seguras em casa, especialmente com tantos Eclipsitas zanzando por aí.",
  ui_story_5004_50040501_39_dialog_content = "Tem razão, Fleur. Ah, Carleen comentou que tem uma <color=#FFB400>loja de trajes de banho</color> aqui.",
  ui_story_5004_50040501_40_dialog_content = "Sabe como chegar lá Fleur?",
  ui_story_5004_50040501_41_dialog_content = "Claro, fica no <color=#FFB400>lado nordeste do refeitório</color>.",
  ui_story_5004_50040501_42_dialog_content = "Ótimo, vamos lá depois do café da manhã!",
  ui_story_5004_50040501_43_dialog_content = "Sim!",
  ui_story_5004_50040601_44_dialog_content = "Demora tanto assim para escolher algo?",
  ui_story_5004_50040601_45_dialog_content = "Me disseram para esperar na <color=#FFB400>praia</color>, mas já passou mais de uma hora.",
  ui_story_5004_50040601_46_dialog_content = "A luz do sol é bastante intensa, mas serve para se bronzear.",
  ui_story_5004_50040601_47_dialog_content = "Vice e o resto são amigos de velha data... Chega de Eclipsitas ou seus planos perversos...",
  ui_story_5004_50040601_48_dialog_content = "Aproveitar o tempo livre e desencanar... que relaxante!",
  ui_story_5004_50040601_49_dialog_content = "...",
  ui_story_5004_50040601_50_dialog_content = "Até a areia é quentinha e reconfortante, talvez eu desenhe algo.",
  ui_story_5004_50040601_51_dialog_content = "O que está desenhando, PlayerName? Um polvo?",
  ui_story_5004_50040601_52_dialog_content = "O quê? Não! É um felino! Gato!",
  ui_story_5004_50040601_53_dialog_content = "Então os tentáculos tortos são bigodes?",
  ui_story_5004_50040601_54_dialog_content = "Vou te ajudar a desenhar bigodes mais legais!",
  ui_story_5004_50040601_55_dialog_content = "Não use os pés, Vice! Maravilha, agora os bigodes ficaram mais grossos do que meus braços!",
  ui_story_5004_50040601_56_dialog_content = "...",
  ui_story_5004_50040601_57_dialog_content = "O quê?",
  ui_story_5004_50040601_58_dialog_content = "Ahn... nada mal.",
  ui_story_5004_50040601_59_dialog_content = "Nada mal o quê?",
  ui_story_5004_50040601_60_dialog_content = "Você está diferente, PlayerName.",
  ui_story_5004_50040601_61_dialog_content = "Tudo bem, vou apenas curtir a paisagem.",
  ui_story_5004_50040601_62_dialog_content = "Só é verão mesmo quando você veste um traje de banho na praia.",
  ui_story_5004_50040601_63_dialog_content = "Seu traje de banho não serve como armadura de batalha, se quer saber.",
  ui_story_5004_50040601_64_dialog_content = "PlayerName! Vou mostrar a você o que é ser um cavaleiro que não teme ondas grandes!",
  ui_story_5004_50040601_65_dialog_content = "(Apesar das diferenças de opinião, Carleen também parece estar empolgada...)",
  ui_story_5004_50040601_66_dialog_content = "(Tanto assim que me deixou vê-la usando traje de banho)",
  ui_story_5004_50040601_67_dialog_content = "O que acha, PlayerName?",
  ui_story_5004_50040601_68_dialog_content = "Como assim, o que eu acho?",
  ui_story_5004_50040601_69_dialog_content = "Os trajes de banho, é claro. Quem você acha que vai conquistar a praia?",
  ui_story_5004_50040601_70_option_content = "Vice ficou uma gracinha e exuberante em seu traje de banho.",
  ui_story_5004_50040601_72_dialog_content = "Você gosta, PlayerName?",
  ui_story_5004_50040601_73_dialog_content = "Mas Vice ficou famosa por ser dinâmica na escola.",
  ui_story_5004_50040601_74_dialog_content = "Desde se esforçar em dobro para cumprir uma meta de treinamento até estudar a noite inteira para uma prova, ela fez tudo.",
  ui_story_5004_50040601_75_dialog_content = "Claro! Ninguém é páreo para mim!",
  ui_story_5004_50040601_76_option_content = "A Carleen fica elegante e sofisticada nesse traje de banho.",
  ui_story_5004_50040601_78_dialog_content = "Também acho!",
  ui_story_5004_50040601_79_dialog_content = "Não se pode esbanjar a graça nobre que ela tem sem passar pelo rígido treinamento de etiqueta que a Carleen fez.",
  ui_story_5004_50040601_80_dialog_content = "Illumina incentiva a disciplina militar, ao contrário de Lumópolis.",
  ui_story_5004_50040601_81_dialog_content = "É verdade, Vice sempre me superava nas aulas de ciência...",
  ui_story_5004_50040601_82_dialog_content = "Hehehe, domino melhor nessa área.",
  ui_story_5004_50040601_83_dialog_content = "Mas sou um desastre em relação à arte.",
  ui_story_5004_50040601_84_dialog_content = "É porque em Lumópolis não havia aulas de desenho mecânico.",
  ui_story_5004_50040601_85_dialog_content = "Chama isso de arte? É algo que apenas se vê em Illumina!",
  ui_story_5004_50040601_86_dialog_content = "Então, posso ter talento musical! Já ajudei PlayerName a iniciar a Colossus antes!",
  ui_story_5004_50040601_87_dialog_content = "Sim, eu sei e agradeço novamente em nome de Soroz, Tenente Vice.",
  ui_story_5004_50040601_88_dialog_content = "Graças a você, todos podem se divertir junto ao mar.",
  ui_story_5004_50040601_89_dialog_content = "Desculpem o atraso!",
  ui_story_5004_50040601_90_dialog_content = "Raphaela! Você não vestiu um traje de banho.",
  ui_story_5004_50040601_91_dialog_content = "Estou no plantão médico. Seria antiético atender a um paciente em traje de banho.",
  ui_story_5004_50040601_92_dialog_content = "Saquei. E cadê a Beryl?",
  ui_story_5004_50040601_93_dialog_content = "Beryl?",
  ui_story_5004_50040601_94_dialog_content = "Vem aqui, Beryl!",
  ui_story_5004_50040601_95_dialog_content = "Não... Isso é constrangedor...",
  ui_story_5004_50040601_96_dialog_content = "Nunca usei nada que deixasse tantas partes do corpo à mostra...",
  ui_story_5004_50040601_97_dialog_content = "Não seja tímida, você ficou uma gracinha!",
  ui_story_5004_50040601_98_dialog_content = "Não é mesmo, PlayerName?",
  ui_story_5004_50040601_99_dialog_content = "Sim. Você está completamente diferente, no bom sentido, e ficou perfeito em você.",
  ui_story_5004_50040601_100_dialog_content = "Isso mesmo, nem eu negaria sua competência como cavaleiro.",
  ui_story_5004_50040601_101_dialog_content = "O ajuste personalizado deve facilitar o movimento.",
  ui_story_5004_50040601_102_dialog_content = "Concordo. Muito mais agradável que o traje habitual da Beryl.",
  ui_story_5004_50040601_103_dialog_content = "Vem nadar com a gente nesse traje fofo!",
  ui_story_5004_50040601_104_dialog_content = "Viu, todo mundo achou que ficou lindo em você, Beryl!",
  ui_story_5004_50040601_105_dialog_content = "Sem falar que todo mundo está vestido assim!",
  ui_story_5004_50040601_106_dialog_content = "Bom...",
  ui_story_5004_50040601_107_dialog_content = "Pode ser.",
  ui_story_5004_50040601_108_dialog_content = "Pare de se preocupara tanto, Beryl!",
  ui_story_5004_50040601_108X1_dialog_content = "<color=#e8d9bb>Estalo.</color>",
  ui_story_5004_50040601_108X2_dialog_content = "<color=#e8d9bb>Estalo, estalo</color>",
  ui_story_5004_50040601_108X3_dialog_content = "É o assistente de ontem?",
  ui_story_5004_50040601_108X4_dialog_content = "Aquele segurando uma câmera? Deve ser uma câmera, já vi algo parecido em Lumópolis!",
  ui_story_5004_50040601_108X5_dialog_content = "Que estranho. Por que alguém ficaria tirando fotos escondido num canto?",
  ui_story_5004_50040601_108X6_dialog_content = "Talvez para promover a paisagem? Vou tentar pegar a câmera emprestada para tirar uma foto!",
  ui_story_5004_50040601_108X7_dialog_content = "Ah, as garotas em trajes de banho deviam me render um bônus...",
  ui_story_5004_50040601_108X8_dialog_content = "Com licença!",
  ui_story_5004_50040601_108X9_dialog_content = "Argh!",
  ui_story_5004_50040601_108X10_dialog_content = "Mas que...? Você jogou em mim antes de eu pedir!",
  ui_story_5004_50040601_108X11_dialog_content = "Suponho que não se importe de me emprestar então, valeu!",
  ui_story_5004_50040601_108X12_dialog_content = "Você me assustou...",
  ui_story_5004_50040601_108X13_dialog_content = "M-me devolve...",
  ui_story_5004_50040601_108X14_dialog_content = "O assistente parece relutante, Raphaela. Talvez seja melhor devolver a câmera",
  ui_story_5004_50040601_108X15_dialog_content = "Beryl é uma garota muito meiga. Pega, não joga por aí de novo.",
  ui_story_5004_50040601_108X16_dialog_content = "Obrigada...",
  ui_story_5004_50040601_109_dialog_content = "Certo, vamos nos divertir, Beryl!",
  ui_story_5004_50040601_110_dialog_content = "Você também vem, PlayerName.",
  ui_story_5004_50040601_111_dialog_content = "Claro!",
  ui_story_5004_50040701_1_dialog_content = "De onde tiram tanta animação e energia?",
  ui_story_5004_50040701_2_dialog_content = "(Vice nada como se tivesse uma hélice nas pernas, espirrando água pra todo lado)",
  ui_story_5004_50040701_3_dialog_content = "(Carleen está içando todos os tipos de criaturas marinhas para fora da água com sua lança.)",
  ui_story_5004_50040701_4_dialog_content = "(E jogando criaturas bem maiores do que ela na praia)",
  ui_story_5004_50040701_5_dialog_content = "(Até Beryl e Raphaelal estão pegando conchas e fazendo castelos de areia freneticamente)",
  ui_story_5004_50040701_6_dialog_content = "(Devo reconhecer que Beryl construiu um castelo de areia realmente incrível...)",
  ui_story_5004_50040701_7_dialog_content = "(Além dos espinhos se projetando para fora e os pináculos, tem uma torre de relógio gigante)",
  ui_story_5004_50040701_X7_dialog_content = "(É como se esse castelo fosse governado por forças do mal...)",
  ui_story_5004_50040701_8_dialog_content = "Então, mais uma vez estou sendo... fracote?",
  ui_story_5004_50040701_9_dialog_content = "Mal me exercitava na Colossus.",
  ui_story_5004_50040701_10_dialog_content = "Praticamente não saia do lugar e dava ordens durante o combate...",
  ui_story_5004_50040701_11_dialog_content = "Talvez deva dar uma corridinha pela praia para entrar em forma.",
  ui_story_5004_50040701_12_dialog_content = "Ei, se não é o Grande Mestre da Colossus, o futuro comandante de Illumina, o Guardião de Lumópolis...",
  ui_story_5004_50040701_13_dialog_content = "E melhor amigo do próximo chefe de Rediesel Wrench, PlayerName?",
  ui_story_5004_50040701_14_dialog_content = "Brock? O que faz aqui?",
  ui_story_5004_50040701_15_dialog_content = "Não devia estar ajudando Fleur?",
  ui_story_5004_50040701_16_dialog_content = "A propósito, não acho que possa vencer Sinsa e ser o novo chefe.",
  ui_story_5004_50040701_17_dialog_content = "Você é um bom comandante PlayerName, mas não sabe avaliar as pessoas.",
  ui_story_5004_50040701_18_dialog_content = "Sinsa está acabado, enquanto eu, sou uma estrela em ascensão!",
  ui_story_5004_50040701_X18_dialog_content = "...",
  ui_story_5004_50040701_19_dialog_content = "Tenho o apoio de muitas pessoas na Rediesel Wrench!",
  ui_story_5004_50040701_20_dialog_content = "Muitas? Tipo quem?",
  ui_story_5004_50040701_21_dialog_content = "Tem o Fleur...",
  ui_story_5004_50040701_22_dialog_content = "...",
  ui_story_5004_50040701_23_dialog_content = "E?",
  ui_story_5004_50040701_24_dialog_content = "Fleur, Fleur e Fleur. Ah, melhor falar com Regina a respeito!",
  ui_story_5004_50040701_25_dialog_content = "Não creio que Regina esteja interessada.",
  ui_story_5004_50040701_26_dialog_content = "Então vou falar com você.",
  ui_story_5004_50040701_27_dialog_content = "Então pode anunciar que tem o apoio da raça Celestita?",
  ui_story_5004_50040701_28_dialog_content = "Qual é, PlayerName, você é o Celestita mais inteligente que conheço!",
  ui_story_5004_50040701_29_dialog_content = "Isso, sou o único Celestita que você conhece!",
  ui_story_5004_50040701_30_dialog_content = "Shiu.",
  ui_story_5004_50040701_31_dialog_content = "...?",
  ui_story_5004_50040701_32_dialog_content = "Tá vendo aquela<color=#FFB400> pessoa ali</color>, PlayerName?",
  ui_story_5004_50040701_33_dialog_content = "A garota?",
  ui_story_5004_50040701_34_dialog_content = "Isso. Ela está bisbilhotando, vasculhando tudo.",
  ui_story_5004_50040701_35_dialog_content = "Que nada, provavelmente está procurando algo que perdeu.",
  ui_story_5004_50040701_36_dialog_content = "Já viu alguém levantar uma rocha tão grande para procurar algo que perdeu?",
  ui_story_5004_50040701_37_dialog_content = "Tudo bem, vamos conferir.",
  ui_story_5004_50040701_38_option_content = "Tá bom...",
  ui_story_5004_50040701_39_dialog_content = "Mas a troco de que toda essa curiosidade sobre ela?",
  ui_story_5004_50040701_40_dialog_content = "E se for uma ladra?",
  ui_story_5004_50040701_41_dialog_content = "Como? Quem esconderia algo embaixo daquela rocha?",
  ui_story_5004_50040701_42_dialog_content = "Não lembro de você ter esse senso de justiça na Rediesel Wrench.",
  ui_story_5004_50040701_43_dialog_content = "Agora é diferente, trabalho para Fleur! Sou o <color=#FFB400>Chefe de Segurança da Costa Celestial</color>!",
  ui_story_5004_50040701_44_dialog_content = "(Que gênio contratou alguém da Rediesel Wrench como segurança?)",
  ui_story_5004_50040701_45_option_content = "Acho que não devemos nos intrometer nos assuntos de ninguém.",
  ui_story_5004_50040701_46_dialog_content = "Não lembro de você ter esse senso de justiça na Rediesel Wrench.",
  ui_story_5004_50040701_47_dialog_content = "Agora é diferente, trabalho para Fleur! Sou o <color=#FFB400>Chefe de Segurança da Costa Celestial</color>!",
  ui_story_5004_50040701_48_dialog_content = "(Que gênio contratou alguém da Rediesel Wrench como segurança?)",
  ui_story_5004_50040701_49_dialog_content = "Não faz barulho e me segue.",
  ui_story_5004_50040701_50_dialog_content = "Ei, desconfiado!",
  ui_story_5004_50040701_51_dialog_content = "...",
  ui_story_5004_50040701_52_dialog_content = "Ei!",
  ui_story_5004_50040701_53_dialog_content = "Não me toca!",
  ui_story_5004_50040701_54_dialog_content = "Viu isso, PlayerName? Ela me atacou primeiro!",
  ui_story_5004_50040701_55_dialog_content = "Espera, você não desviou? Não sejamos violentos.",
  ui_story_5004_50040701_56_dialog_content = "Quem é você? E quem é esse brutamontes?",
  ui_story_5004_50040701_57_dialog_content = "Quem pensa que é pra gritar com os outros e tentar agarrar o ombro de uma dama!",
  ui_story_5004_50040701_58_dialog_content = "Você não vai querer mexer comigo! Vai incomodar outra pessoa!",
  ui_story_5004_50040701_59_dialog_content = "Se afasta PlayerName! Vou prender essa mocinha no banco de trás!",
  ui_story_5004_50040701_60_dialog_content = "Bem na hora. Estava querendo desabafar...",
  ui_story_5004_50040701_61_dialog_content = "Hehe, faz tempo que não nos vemos. Não achei que se misturaria com essas pessoas comuns, <color=#FFB400>Smokey</color>.",
  ui_story_5004_50040701_62_dialog_content = "Ainda se considera nobre?",
  ui_story_5004_50040701_63_dialog_content = "Quem é você? O que te importa se sou ou não nobre?",
  ui_story_5004_50040701_64_dialog_content = "O que, não se lembra de mim?!",
  ui_story_5004_50040701_65_dialog_content = "Ei, ainda não acabei com você...",
  ui_story_5004_50040701_66_dialog_content = "Cala a boca!",
  ui_story_5004_50040701_67_dialog_content = "Olha melhor desta vez!",
  ui_story_5004_50040701_68_dialog_content = "Não sei quem é você, então fica longe de mim.",
  ui_story_5004_50040701_69_dialog_content = "Sou <color=#FFB400>Genevieve</color>! <color=#FFB400>Genevieve</color> dos <color=#FFB400>Vronsky</color>!",
  ui_story_5004_50040701_70_dialog_content = "Espera, estou lembrando...",
  ui_story_5004_50040701_71_dialog_content = "Petyaburg...",
  ui_story_5004_50040701_72_dialog_content = "Isso, Petyaburg!",
  ui_story_5004_50040701_73_dialog_content = "<size=30>PlayerName, qual é a dessas duas...</size>",
  ui_story_5004_50040701_74_dialog_content = "<size=30>Como posso saber?</size>",
  ui_story_5004_50040701_75_dialog_content = "Agora lembrei! Genevieve! Como você cresceu.",
  ui_story_5004_50040701_76_dialog_content = "O quê? Quanta insolência!",
  ui_story_5004_50040701_77_dialog_content = "Minha família e eu fomos desonrados por sua causa!",
  ui_story_5004_50040701_78_dialog_content = "Do que está falando? Não lembro disso.",
  ui_story_5004_50040701_79_dialog_content = "Estou ficando com dor de cabeça de tentar lembrar.",
  ui_story_5004_50040701_80_dialog_content = "Ah, estou com amnésia. Tudo bem?",
  ui_story_5004_50040701_81_dialog_content = "Bem, preciso ir. Adeus, bela senhorita Genevieve!",
  ui_story_5004_50040701_82_dialog_content = "Você não vai a lugar nenhum!",
  ui_story_5004_50040701_83_dialog_content = "...",
  ui_story_5004_50040701_84_dialog_content = "Por que está me olhando?",
  ui_story_5004_50040701_85_dialog_content = "Ei, me larga! Nunca bati numa mulher, mas posso pensar em algo.",
  ui_story_5004_50040701_86_dialog_content = "Não é adequado que nos vejam assim.",
  ui_story_5004_50040701_87_dialog_content = "Não quero que interpretem mal!",
  ui_story_5004_50040701_88_dialog_content = "A Smokey!",
  ui_story_5004_50040701_89_dialog_content = "Jamais vou te perdoar!",
  ui_story_5004_50040701_90_dialog_content = "Sinto que vai rolar pancadaria, PlayerName.",
  ui_story_5004_50040701_91_dialog_content = "Por que está tão ansioso com isso?",
  ui_story_5004_50040701_92_dialog_content = "Não entende. Lutar é uma maneira importante de se comunicar e provar seu valor na Rediesel Wrench",
  ui_story_5004_50040701_93_dialog_content = "Tanto faz... acho que a loira vai ganhar.",
  ui_story_5004_50040701_94_dialog_content = "Por que acha isso?",
  ui_story_5004_50040701_95_dialog_content = "Instinto de Celestita.",
  ui_story_5004_50040701_96_dialog_content = "Não sabe o que está falando. Olha para Smokey, a garota de cabelo prateado.",
  ui_story_5004_50040701_97_dialog_content = "Ela tem um ótimo gingado e se movimenta perfeitamente.",
  ui_story_5004_50040701_98_dialog_content = "Expressa confiança, então sabe o que está fazendo.",
  ui_story_5004_50040701_99_dialog_content = "A loira ali pode ser agressiva, mas o fato de não controlar as emoções a torna mais vulnerável.",
  ui_story_5004_50040701_100_dialog_content = "Acho que ainda vai demorar bastante para dominar sua Luminática.",
  ui_story_5004_50040701_101_dialog_content = "Isso foi esclarecedor... Onde aprendeu tudo isso?",
  ui_story_5004_50040701_102_dialog_content = "Wooga!",
  ui_story_5004_50040701_103_dialog_content = "Sai da frente!",
  ui_story_5004_50040701_103X_dialog_content = "Aqui também tem Eclipsitas?",
  ui_story_5004_50040701_103X1_dialog_content = "Nada demais. Pense nos Eclipsitas como uma peculiaridade local.",
  ui_story_5004_50040701_104_dialog_content = "Hum, essa Genevieve é experiente.",
  ui_story_5004_50040701_105_dialog_content = "Ei, Eclipsita atrás de você!",
  ui_story_5004_50040701_106_dialog_content = "Então Brock, você não é segurança? Vai ficar só assistindo?",
  ui_story_5004_50040701_107_dialog_content = "É mesmo, tinha esquecido!",
  ui_story_5004_50040701_108_dialog_content = "Certo, seus Eclipsitas imundos, hora de enterrar todos na areia!",
  ui_story_5004_50040701_109_dialog_content = "Velocidade máxima!",
  ui_story_5004_50040701_110_dialog_content = "Isso foi rápido!",
  ui_story_5004_50040701_111_dialog_content = "É óbvio, o que você esperava?",
  ui_story_5004_50040701_112_dialog_content = "Tudo bem?",
  ui_story_5004_50040701_113_dialog_content = "Quem mandou você interferir?",
  ui_story_5004_50040701_114_dialog_content = "Smokey fugiu por sua causa!",
  ui_story_5004_50040701_115_dialog_content = "Foi mal!",
  ui_story_5004_50040701_116_dialog_content = "Não fala comigo! Estou muito irritada...",
  ui_story_5004_50040701_117_dialog_content = "Preciso descobrir o que ela está tramando e frustrar seus planos!",
  ui_story_5004_50040701_118_dialog_content = "Obrigada e adeus.",
  ui_story_5004_50040701_119_dialog_content = "Ela foi embora.",
  ui_story_5004_50040701_120_dialog_content = "Viu isso PlayerName? A discórdia entre duas mulheres é mais assustadora do que qualquer Eclipsita.",
  ui_story_5004_50040701_121_dialog_content = "Acho melhor você não se envolver.",
  ui_story_5004_50040701_122_dialog_content = "Nem sequer pensar no assunto.",
  ui_story_5004_50040701_123_dialog_content = "Delícia!",
  ui_story_5004_50040701_124_dialog_content = "Tem algo na sua boca, deixa eu limpar.",
  ui_story_5004_50040701_125_dialog_content = "Agradeço.",
  ui_story_5004_50040701_126_dialog_content = "Não consigo me controlar, o refeitório em Illumina jamais serviu algo tão bom!",
  ui_story_5004_50040701_127_dialog_content = "Especialmente quando a dama com as mãos trêmulas recolocava a já escassa carne na panela enquanto pegava a comida para mim.",
  ui_story_5004_50040701_128_dialog_content = "Ainda estou progredindo, tá sabendo!",
  ui_story_5004_50040701_129_dialog_content = "Não é à toa que você praticamente morava no café quando estudava em Lumópolis.",
  ui_story_5004_50040701_132_dialog_content = "Não precisa ficar aí esperando, Fleur. Junte-se a nós, você é nosso amigo.",
  ui_story_5004_50040701_133_dialog_content = "Não posso. Vocês são nossos convidados, e devo ficar esperando.",
  ui_story_5004_50040701_134_dialog_content = "Mas...",
  ui_story_5004_50040701_135_dialog_content = "Deixe pra lá, PlayerName.",
  ui_story_5004_50040701_136_dialog_content = "Todos sabem que ele é assim mesmo, e se orgulha disso.",
  ui_story_5004_50040701_137_dialog_content = "O que gostaria de beber, Brock?",
  ui_story_5004_50040701_138_dialog_content = "Algo gelado!",
  ui_story_5004_50040701_139_dialog_content = "Entendi. Já vou providenciar.",
  ui_story_5004_50040701_140_dialog_content = "...",
  ui_story_5004_50040701_141_dialog_content = "Por que seu rosto está ficando vermelho, PlayerName?",
  ui_story_5004_50040701_142_dialog_content = "É? Acho que não...",
  ui_story_5004_50040701_143_dialog_content = "Pelo visto, Celestitas também não são imunes ao efeito.",
  ui_story_5004_50040701_144_dialog_content = "Imune? Como assim?",
  ui_story_5004_50040701_145_dialog_content = "É melhor perguntar pessoalmente.",
  ui_story_5004_50040701_146_dialog_content = "Então, o que rolou entre as duas mulheres esta tarde?",
  ui_story_5004_50040701_147_dialog_content = "Como posso saber? Nem as conheço.",
  ui_story_5004_50040701_148_dialog_content = "Isso é muito suspeito. Quem me agrediu obviamente estava procurando algo.",
  ui_story_5004_50040701_149_dialog_content = "É melhor esconder a chave do carro em algum lugar.",
  ui_story_5004_50040701_150_dialog_content = "Ninguém quer roubar seu carro!",
  ui_story_5004_50040701_151_dialog_content = "Outra pessoa procurando algo? Beryl e eu topamos com alguém assim esta tarde!",
  ui_story_5004_50040701_152_dialog_content = "Certo, Beryl?",
  ui_story_5004_50040701_153_dialog_content = "Sim. Cabelo grisalho, usando óculos escuros, nada sociável e assustadora...",
  ui_story_5004_50040701_154_dialog_content = "(Parece ser a mesma pessoa)",
  ui_story_5004_50040701_155_dialog_content = "Ela foi muito antipática, PlayerName.",
  ui_story_5004_50040701_156_dialog_content = "Até pisou no castelo de areia que a Beryl levou 3 horas para construir!",
  ui_story_5004_50040701_157_dialog_content = "Tinha mais de 2 metros e era divino! Era grande assim!",
  ui_story_5004_50040701_158_dialog_content = "Tudo bem, ela se desculpou.",
  ui_story_5004_50040701_159_dialog_content = "Mas você passou a tarde toda fazendo o castelo, Beryl!",
  ui_story_5004_50040701_160_dialog_content = "Mesmo assim, estou feliz por poder relaxar e não me preocupar com nada.",
  ui_story_5004_50040701_161_dialog_content = "Guardarei esse castelo sempre na memória. Posso vê-lo ao fechar os olhos.",
  ui_story_5004_50040701_162_dialog_content = "Se Raphaela gostou, posso construir outro amanhã.",
  ui_story_5004_50040701_163_dialog_content = "É mesmo? Me deixa ajudar da próxima vez!",
  ui_story_5004_50040701_164_dialog_content = "Claro.",
  ui_story_5004_50040701_165_dialog_content = "Anda não sabemos quem é e qual o motivo.",
  ui_story_5004_50040701_166_dialog_content = "Desencana e não esquenta a cabeça com isso, Brock.",
  ui_story_5004_50040701_167_dialog_content = "Mas prometi a Fleur que faria um bom trabalho protegendo o local.",
  ui_story_5004_50040701_168_dialog_content = "(Por isso veio correndo até mim na primeira chance que teve?)",
  ui_story_5004_50040701_169_dialog_content = "Pedi ao Brock que viesse.",
  ui_story_5004_50040701_170_dialog_content = "Aí está sua bebida com gelo adicional. Aproveite!",
  ui_story_5004_50040701_171_dialog_content = "Já disse que cumpro o que prometo... Eca!",
  ui_story_5004_50040701_172_dialog_content = "Que diacho é isso?!",
  ui_story_5004_50040701_173_dialog_content = "Desculpe, não temos as coisas com as quais está acostumado, então fiz algumas substituições.",
  ui_story_5004_50040701_174_dialog_content = "Então, com o que está acostumado, Brock? O pessoal da Rediesel Wrench certamente é outro nível!",
  ui_story_5004_50040701_175_dialog_content = "Esse é para você, PlayerName.",
  ui_story_5004_50040701_176_dialog_content = "É o nosso especial de boas-vindas.",
  ui_story_5004_50040701_177_dialog_content = "Especial... não tem nada venenoso aí, certo?",
  ui_story_5004_50040701_178_dialog_content = "Não esquenta, não tem veneno nem álcool. Qualquer um pode tomar.",
  ui_story_5004_50040701_X178_dialog_content = "Você é muito gentil!",
  ui_story_5004_50040701_179_dialog_content = "Além disso, se concordar, gostaria de ter uma conversinha em particular o mais rápido possível, PlayerName.",
  ui_story_5004_50040701_180_dialog_content = "Tenho tempo de sobra.",
  ui_story_5004_50040701_181_dialog_content = "(Equilíbrio perfeito entre doce e azedo, o aroma cítrico se destaca e acrescenta mais sabor à bebida)",
  ui_story_5004_50040701_182_dialog_content = "(Uma bebida gostosa e enigmática...)",
  ui_story_5004_50040901_1_dialog_content = "Não, preciso levantar...",
  ui_story_5004_50040901_2_dialog_content = "Adormeci sobre uma pilha de peças mecânicas de novo. As costas doem por ter deitado nas engrenagens.",
  ui_story_5004_50040901_3_dialog_content = "Provavelmente desenhei esse projeto ontem à noite...",
  ui_story_5004_50040901_4_dialog_content = "É inútil. Devia estar no lixo.",
  ui_story_5004_50040901_5_dialog_content = "Acho que preciso confiar no <color=#FFB400>conhecimento dos Celestitas</color>...",
  ui_story_5004_50040901_6_dialog_content = "Os robôs de Illumina e Lumópolis não são o suficiente. Fazendo uma análise preliminar, não consigo criar o que desejo.",
  ui_story_5004_50040901_7_dialog_content = "Um banho antes de me encontrar com PlayerName.",
  ui_story_5004_50040901_8_dialog_content = "Se não concluir o Monarca do Oceano, não conseguirei me livrar do efeito do meu <color=#FFB400>dom especial</color>.",
  ui_story_5004_50040901_9_dialog_content = "(Devia ser um mecânico comum de Illumina)",
  ui_story_5004_50040901_10_dialog_content = "(Mas devido ao dom especial dominante em meus genes...)",
  ui_story_5004_50040901_11_dialog_content = "(Quando estava na escola...)",
  ui_story_5004_50040901_12_dialog_content = "Fleur, <size=45>Fleur!</size>",
  ui_story_5004_50040901_13_dialog_content = "Oi! E olá para você também!",
  ui_story_5004_50040901_14_dialog_content = "Pode me mostrar como solucionar esse problema, Fleur?",
  ui_story_5004_50040901_15_dialog_content = "Claro. Manda ver.",
  ui_story_5004_50040901_16_dialog_content = "Por que você incomoda constantemente o pobre Fleur?",
  ui_story_5004_50040901_17_dialog_content = "Está tentando dar em cima do Fleur?",
  ui_story_5004_50040901_18_dialog_content = "E daí? <size=45>Fleur não pertence a você!</size>",
  ui_story_5004_50040901_19_dialog_content = "Ei, garotas parem de assediar Fleur o tempo todo!",
  ui_story_5004_50040901_20_dialog_content = "Ele não tem interesse em vocês. Certo, Fleur?",
  ui_story_5004_50040901_21_dialog_content = "Como assim? Você gosta de garotas ou garotos, Fleur? Responda!",
  ui_story_5004_50040901_22_dialog_content = "Gosto de todos.",
  ui_story_5004_50040901_23_dialog_content = "Ele tem talento com máquinas, trabalha muito e é legal com as pessoas.",
  ui_story_5004_50040901_24_dialog_content = "É extraordinário.",
  ui_story_5004_50040901_25_dialog_content = "Mas seu dom especial não permite que fique por perto.",
  ui_story_5004_50040901_26_dialog_content = "Seja homem ou mulher, até os animais o procuram.",
  ui_story_5004_50040901_27_dialog_content = "Sem mencionar <color=#FFB400>o incidente</color> que afetou várias vítimas.",
  ui_story_5004_50040901_28_dialog_content = "E se a gente o enviar para a nova <color=#FFB400>Subcidade 38</color>? Pelo menos não há tantos Aurorians lá...",
  ui_story_5004_50040901_29_dialog_content = "É o ideal, ninguém incomoda ele, e nos livramos de problemas.",
  ui_story_5004_50040901_30_dialog_content = "Parabéns, Fleur. Você será enviado para a Subcidade 38 como especialista em construções.",
  ui_story_5004_50040901_31_dialog_content = "É uma ótima oportunidade e a prova da crença de Illumina em você.",
  ui_story_5004_50040901_32_dialog_content = "Terá espaço suficiente para mostrar sua competência, e sabemos que você pode se destacar lá!",
  ui_story_5004_50040901_33_dialog_content = "(Foi realmente uma época feliz, fácil e tranquila)",
  ui_story_5004_50040901_34_dialog_content = "Minha esposa virá para a Subcidade 38 na próxima semana. Não nos vemos há anos",
  ui_story_5004_50040901_35_dialog_content = "Não podemos ficar com as esposas porque aquele cara está aqui. Nem nossas filhas podem vir!",
  ui_story_5004_50040901_36_dialog_content = "Nossos animais de estimação continuam indo para sua casa!",
  ui_story_5004_50040901_37_dialog_content = "Fique longe dele, a menos que queira ceder ao seu encanto!",
  ui_story_5004_50040901_38_dialog_content = "Se acalma. Fleur não é uma ameaça para todo mundo.",
  ui_story_5004_50040901_39_dialog_content = "Ha! Todos em Illumina sabem sobre <color=#FFB400>o incidente</color> que ele causou na escola!",
  ui_story_5004_50040901_40_dialog_content = "Pessoas se feriram por sua causa! Não só uma, foram várias! Por que o está protegendo?",
  ui_story_5004_50040901_42_dialog_content = "Agradeço por sua contribuição com a Subcidade 38, Fleur.",
  ui_story_5004_50040901_43_dialog_content = "Mas é hora de voltar para Gannon. As pessoas estão...",
  ui_story_5004_50040901_44_dialog_content = "Tudo bem. Eu entendo.",
  ui_story_5004_50040901_45_dialog_content = "Mas não quero voltar.",
  ui_story_5004_50040901_46_dialog_content = "Não quero sair da Subcidade 38. Tive momentos felizes e tranquilos aqui.",
  ui_story_5004_50040901_47_dialog_content = "Não há multidões me cercando, e posso fazer minha pesquisa em paz.",
  ui_story_5004_50040901_48_dialog_content = "Você disse que eu me destacaria aqui...",
  ui_story_5004_50040901_49_dialog_content = "...",
  ui_story_5004_50040901_50_dialog_content = "Desculpe, mas as coisas mudaram. Por favor, não nos obrigue a levar você de volta.",
  ui_story_5004_50040901_51_dialog_content = "O que faço se voltar?",
  ui_story_5004_50040901_52_dialog_content = "Ficaria de quarentena ou no Departamento de Pesquisa como cobaia?",
  ui_story_5004_50040901_53_dialog_content = "Desculpe...",
  ui_story_5004_50040901_54_dialog_content = "Fizemos o possível.",
  ui_story_5004_50040901_55_dialog_content = "Mas há uma chance agora!",
  ui_story_5004_50040901_56_dialog_content = "Bem-vindo ao Hotel Tir, Fleur! Creio que você leu a carta, certo?",
  ui_story_5004_50040901_57_dialog_content = "Sim. Posso ajudar com o Monarca do Oceano, mas você realmente consegue remover meu dom especial?",
  ui_story_5004_50040901_58_dialog_content = "Não se preocupe, achei as informações nas ruínas. Se a lenda for verdadeira, então consigo.",
  ui_story_5004_50040901_59_dialog_content = "Ah, esse jovem deve ser Fleur. Você será o gerente do saguão e responsável pela preparação do Monarca do Oceano.",
  ui_story_5004_50040901_59X1_dialog_content = "Saquei. Vou começar agora mesmo.",
  ui_story_5004_50040901_59X2_dialog_content = "Começamos bem. Ah, do que se trata a lenda que acabou de mencionar?",
  ui_story_5004_50040901_59X3_dialog_content = "Eu inventei. Enfim, desde que consiga trazê-los, que diferença faz, né?",
  ui_story_5004_50040901_59X4_dialog_content = "Ahn, claro. Desde que consiga tudo da lista...",
  ui_story_5004_50040901_59X5_dialog_content = "O Monarca do Oceano... vou aproveitar a oportunidade.",
  ui_story_5004_50040901_60_dialog_content = "Tudo pronto...",
  ui_story_5004_50040901_61_dialog_content = "Vai, Fleur!",
  ui_story_5004_50040901_62_dialog_content = "Fleur!",
  ui_story_5004_50040901_63_dialog_content = "<size=45>Sr. Fleur!</size>",
  ui_story_5004_50040901_64_dialog_content = "Bom dia, pessoal.",
  ui_story_5004_50040901_65_dialog_content = "Você cheira tão bem, Sr. Fleur!",
  ui_story_5004_50040901_66_dialog_content = "Tomou banho? Ouvi água escorrendo!",
  ui_story_5004_50040901_67_dialog_content = "Ah, ahn, dá licença?",
  ui_story_5004_50040901_68_dialog_content = "Posso ir ao seu quarto?",
  ui_story_5004_50040901_69_dialog_content = "Desculpe, prefiro que as peças mecânicas fiquem onde estão...",
  ui_story_5004_50040901_70_dialog_content = "Fleury, que dá aulas de ioga, disse que posso me exercitar com você se me inscrever. É verdade?",
  ui_story_5004_50040901_71_dialog_content = "É mesmo? Tá parecendo armação...",
  ui_story_5004_50040901_72_dialog_content = "Calma pessoal, por favor. Preciso encontrar alguém, então dá licença...",
  ui_story_5004_50040901_73_dialog_content = "<anim type=Shake><size=45>O quê?</size></anim>",
  ui_story_5004_50040901_74_dialog_content = "Quem é esse? Que malandrinho sorrateiro!",
  ui_story_5004_50040901_75_dialog_content = "Sr. Fleur, não seria melhor sair com a gente em vez disso?",
  ui_story_5004_50040901_76_dialog_content = "(Droga, parece que PlayerName terá que esperar)",
  ui_story_5004_50041001_1_dialog_content = "Saquei. Agora entendi.",
  ui_story_5004_50041001_2_dialog_content = "Agradeço por sua paciência e perdão, de verdade!",
  ui_story_5004_50041001_3_dialog_content = "Tudo bem. Mas Fleur, vai mesmo construir um robô sozinho?",
  ui_story_5004_50041001_4_dialog_content = "Sim, é o que mais desejo.",
  ui_story_5004_50041001_5_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5004_50041001_6_dialog_content = "Posso entrar, PlayerName?",
  ui_story_5004_50041001_7_dialog_content = "Claro.",
  ui_story_5004_50041001_8_dialog_content = "Ah, Fleur também está aqui.",
  ui_story_5004_50041001_9_dialog_content = "Você chefia o Comitê do Monarca do Oceano. Não deve ter sossego, certo?",
  ui_story_5004_50041001_10_dialog_content = "Não tenho. Vim exatamente pedir a opinião de PlayerName sobre alguns problemas de design.",
  ui_story_5004_50041001_11_dialog_content = "É melhor voltar e revisar os projetos novamente. Adeus.",
  ui_story_5004_50041001_12_dialog_content = "Decidiu se vai participar do Monarca do Oceano, PlayerName? O prêmio inclui...",
  ui_story_5004_50041001_13_dialog_content = "Nós topamos.",
  ui_story_5004_50041001_14_dialog_content = "O quê?",
  ui_story_5004_50041001_15_dialog_content = "Algum problema? Conversei com meus amigos e...",
  ui_story_5004_50041001_16_dialog_content = "Inesperado. Pensei que fosse levar mais tempo, não?",
  ui_story_5004_50041001_17_dialog_content = "É um festival, afinal de contas. O que há para pensar?",
  ui_story_5004_50041001_18_dialog_content = "Então, não tem receio que seja uma conspiração, PlayerName?",
  ui_story_5004_50041001_19_dialog_content = "Conspiração? Então estamos fora!",
  ui_story_5004_50041001_20_dialog_content = "Hahaha, que adorável. Até eu, integrante da True Order, não falaria abertamente se fosse uma conspiração!",
  ui_story_5004_50041001_21_dialog_content = "É uma honra para você tomar a decisão certa, né?",
  ui_story_5004_50041001_22_dialog_content = "(Por que todos da True Order são tão estranhos?)",
  ui_story_5004_50041001_23_dialog_content = "Já que aderiu, assine isto.",
  ui_story_5004_50041001_24_dialog_content = "Tome, use esta caneta.",
  ui_story_5004_50041001_25_dialog_content = "É luxuosa.",
  ui_story_5004_50041001_26_dialog_content = "E fria como gelo.",
  ui_story_5004_50041001_27_dialog_content = "É feita de um cristal raríssimo. Parece cara, né?",
  ui_story_5004_50041001_28_dialog_content = "E é mesmo. Vale a metade do preço deste hotel.",
  ui_story_5004_50041001_29_dialog_content = "Pode ficar de presente, PlayerName. Gostou, né?",
  ui_story_5004_50041001_30_dialog_content = "Não, não posso aceitar um presente tão valioso!",
  ui_story_5004_50041001_31_dialog_content = "Tudo bem, foi desenterrada das ruínas.",
  ui_story_5004_50041001_32_dialog_content = "Essa é a True Order que conheço, escavando ruínas por todo lado.",
  ui_story_5004_50041001_33_dialog_content = "Que lisonjeiro. Ah, ouvi dizer que o painel de controle da sua Colossus parece um... piano?",
  ui_story_5004_50041001_34_dialog_content = "Teria a sorte de vê-lo? Gosto de música, e você tem um piano incomum, certo?",
  ui_story_5004_50041001_35_dialog_content = "Posso arranjar uma visita. Tome, o papel assinado!",
  ui_story_5004_50041001_36_dialog_content = "Entendo. Certo, está confirmado, agora você é um competidor!",
  ui_story_5004_50041001_37_dialog_content = "A primeira partida será esta tarde. É melhor descansar um pouco antes disso.",
  ui_story_5004_50041001_38_dialog_content = "Torço pelo seu sucesso.",
  ui_story_5004_50041001_39_dialog_content = "Ei, correu tudo bem, né?",
  ui_story_5004_50041001_40_dialog_content = "Isso que estou sentindo é culpa?",
  ui_story_5004_50041001_X40_dialog_content = "Hum... não.",
  ui_story_5004_50041001_X40X1_dialog_content = "Então, aqui estamos, incluindo o Celestita.",
  ui_story_5004_50041001_X40X2_dialog_content = "Não achei que PlayerName fosse assinar com a caneta daquela pessoa tão fácil...",
  ui_story_5004_50041001_X40X3_dialog_content = "Me pergunto o que aquela pessoa está tramando... Esquece, esses Eclipsitas não valem nada mesmo.",
  ui_story_5004_50041001_41_dialog_content = "A primeira parte do <color=#FFB400>Movimento</color>, muito simples.",
  ui_story_5004_50041001_42_dialog_content = "PlayerName sem dúvida é uma figura interessante.",
  ui_story_5004_50041101_1_dialog_content = "<color=#e8d9bb>Enquanto isso...</color>",
  ui_story_5004_50041101_2_dialog_content = "Muito bem, você compreendeu.",
  ui_story_5004_50041101_3_dialog_content = "Se aproximará um pouco mais do divino com o poder do Celestita.",
  ui_story_5004_50041101_4_dialog_content = "Eu mostro o caminho, e você me dá a fruta.",
  ui_story_5004_50041101_5_dialog_content = "Não precisa mais satisfazer a ralé... Alcançará o verdadeiro auge da música.",
  ui_story_5004_50041101_6_dialog_content = "Saquei. Era exatamente o que eu queria!",
  ui_story_5004_50041101_7_dialog_content = "É estranho toda vez que vejo você murmurando. O que a voz na sua cabeça disse desta vez?",
  ui_story_5004_50041101_8_dialog_content = "Já entreguei a primeira parte do Movimento, visto que todos da lista participaram do concurso, como combinamos.",
  ui_story_5004_50041101_9_dialog_content = "A voz está reclamando sobre a segunda parte?",
  ui_story_5004_50041101_10_dialog_content = "Os Eclipsitas estão esmiuçando, mas é inútil mesmo que você consiga entender.",
  ui_story_5004_50041101_11_dialog_content = "Ainda precisará do poder de um Celestita para despertar.",
  ui_story_5004_50041101_12_dialog_content = "Isso não é da conta de vocês.",
  ui_story_5004_50041101_13_dialog_content = "Só para esclarecer, meu objetivo é completar o Movimento Divino, não compactuar com Eclipsitas.",
  ui_story_5004_50041101_14_dialog_content = "Isso só aconteceu porque você entregou a primeira parte e me prometeu a segunda.",
  ui_story_5004_50041101_15_dialog_content = "O que torna isso um interesse mútuo, não uma parceria permanente, entendeu?",
  ui_story_5004_50041101_15X_dialog_content = "A propósito, os Eclipsitas que enviou foram eliminados por PlayerName e Aurorians.",
  ui_story_5004_50041101_16_dialog_content = "Ratos inúteis.",
  ui_story_5004_50041101_17_dialog_content = "Auronian desprezível e indecente!",
  ui_story_5004_50041101_18_dialog_content = "Relaxa.",
  ui_story_5004_50041101_19_dialog_content = "Não quer que descubram e estraguem sua arapuca, certo?",
  ui_story_5004_50041101_20_dialog_content = "E seus planos ridículos? Como atrair turistas com o Monarca do Oceano e vender fotos em traje de banho para financiar seu investimento, hein?",
  ui_story_5004_50041101_21_dialog_content = "Essas tramoias absurdas para surpreender turistas. Aulas de ioga, hilário.",
  ui_story_5004_50041101_22_dialog_content = "Mas com certeza a maior parte do dinheiro ainda vai para o verdadeiro chefe, né?",
  ui_story_5004_50041101_23_dialog_content = "Como testa de ferro, você não passa de uma ferramenta.",
  ui_story_5004_50041101_24_dialog_content = "Me pergunto o que seus colegas Eclipsitas diriam ao saber que você trabalha para um Aurorian.",
  ui_story_5004_50041101_25_dialog_content = "Que atrevimento! Nós...",
  ui_story_5004_50041101_26_dialog_content = "Senhor Prinny!",
  ui_story_5004_50041101_27_dialog_content = "Isso ainda não acabou, você verá!",
  ui_story_5004_50041101_28_dialog_content = "Mostre a saída ao convidado, Mestre Thaddius.",
  ui_story_5004_50041101_29_dialog_content = "Por aqui, por favor.",
  ui_story_5004_50041101_30_dialog_content = "Vou contar sobre meu recente curso de ioga enquanto vamos para sua casa.",
  ui_story_5004_50041101_31_dialog_content = "Perfeição é um estado emocional. Elegância é um estilo de vida. Tolerância é uma atitude. Uma vida bela começa com a ioga.",
  ui_story_5004_50041101_32_dialog_content = "Ioga é a sua jornada do banal para o extraordinário.",
  ui_story_5004_50041101_33_dialog_content = "Ioga é a arte espiritual da transcendência.",
  ui_story_5004_50041101_34_dialog_content = "...",
  ui_story_5004_50041201_1_dialog_content = "Este é o local da competição?",
  ui_story_5004_50041201_2_dialog_content = "Posição do juiz, rede... Basicamente, corresponde à descrição no arquivo de Soroz.",
  ui_story_5004_50041201_2X1_dialog_content = "Ei, o que é aquilo ali?",
  ui_story_5004_50041201_2X2_dialog_content = "Não se preocupe com isso. É um simples dispositivo de controle de danos.",
  ui_story_5004_50041201_2X3_dialog_content = "É para evitar que você estrague os acessórios ao redor no calor do combate.",
  ui_story_5004_50041201_2X4_dialog_content = "(Combate? Não era um jogo de vôlei?)",
  ui_story_5004_50041201_2X5_dialog_content = "Ufa, terminei.",
  ui_story_5004_50041201_3_dialog_content = "Tudo bem, o juiz já está posicionado.",
  ui_story_5004_50041201_4_dialog_content = "Bem-vindos à primeira partida de vôlei do Monarca do Oceano, um teste de força e coragem!",
  ui_story_5004_50041201_5_dialog_content = "À minha direita está a equipe comandada por PlayerName.",
  ui_story_5004_50041201_6_dialog_content = "Ei, Fleur, você joga com PlayerName, né?",
  ui_story_5004_50041201_7_dialog_content = "Fleur também tá aqui?",
  ui_story_5004_50041201_8_dialog_content = "Faz tempo que não pratico nenhum esporte com Brock, e Bonacie já está me animando.",
  ui_story_5004_50041201_9_dialog_content = "Mas a multidão provavelmente vai ficar descontrolada com ele aqui...",
  ui_story_5004_50041201_10_dialog_content = "Fleur!",
  ui_story_5004_50041201_11_dialog_content = "Fleury!",
  ui_story_5004_50041201_12_dialog_content = "Também acho...",
  ui_story_5004_50041201_13_dialog_content = "Não sou muito bom com esportes...",
  ui_story_5004_50041201_14_dialog_content = "Não esquenta PlayerName. Jogo muito bem vôlei!",
  ui_story_5004_50041201_15_dialog_content = "É verdade, Vice mandava bem na educação física e prática de esportes na escola.",
  ui_story_5004_50041201_16_dialog_content = "Não é à toa que a chamavam de <color=#FFB400>Donzela de Ferro</color>.",
  ui_story_5004_50041201_17_dialog_content = "Pode confiar, PlayerName. A gente dá conta.",
  ui_story_5004_50041201_18_dialog_content = "(Por que as escolas de Lumópolis inventam apelidos estranhos?)",
  ui_story_5004_50041201_19_dialog_content = "É mesmo? Que ótimo. Mostre do que é capaz, Vice!",
  ui_story_5004_50041201_20_dialog_content = "Que sorte a minha estar na sua equipe.",
  ui_story_5004_50041201_21_dialog_content = "Ei, você é garota de ontem... Também se inscreveu para isso?",
  ui_story_5004_50041201_22_dialog_content = "Foi ela que destruiu o castelo de areia da Beryl!",
  ui_story_5004_50041201_23_dialog_content = "E daí? Não posso participar? Bonacie me convidou!",
  ui_story_5004_50041201_24_dialog_content = "Além disso, meu nome é Smokey, e já me desculpei pelo castelo de areia.",
  ui_story_5004_50041201_25_dialog_content = "Não vamos brigar. Estamos na mesma equipe. Precisamos trabalhar juntos e vencer.",
  ui_story_5004_50041201_26_dialog_content = "Essa é a garota malvada de quem você falou ontem? Ela não parece do tipo que joga limpo...",
  ui_story_5004_50041201_27_dialog_content = "Sim, mas <color=#FFB400>a outra</color> de quem falei é ainda pior de lidar.",
  ui_story_5004_50041201_28_dialog_content = "À minha esquerda está Genevieve e seus fãs fervorosos!",
  ui_story_5004_50041201_29_dialog_content = "Hunf...",
  ui_story_5004_50041201_30_dialog_content = "É ela!",
  ui_story_5004_50041201_31_dialog_content = "<anim type=Shake><size=45>Viva, viva, viva!</size></anim>",
  ui_story_5004_50041201_32_dialog_content = "Hehehe, tá vendo, Smokey?",
  ui_story_5004_50041201_33_dialog_content = "Uma verdadeira nobre é adorada pelo povão aonde for.",
  ui_story_5004_50041201_34_dialog_content = "Reconhecem minha condição superior devido ao meu caráter nobre e se submetem à minha autoridade!",
  ui_story_5004_50041201_35_dialog_content = "Algo que jamais entenderá, Smokey!",
  ui_story_5004_50041201_36_dialog_content = "Tá bom, tudo bem, tanto faz.",
  ui_story_5004_50041201_37_dialog_content = "Quem iria querer entender essa aporrinhação de qualquer forma.",
  ui_story_5004_50041201_38_dialog_content = "Ei, pessoal, não se reprimam. Vamos começar logo!",
  ui_story_5004_50041201_39_dialog_content = "Está provocando? Vou te mostrar...",
  ui_story_5004_50041201_40_dialog_content = "Espera, o jogo nem começou ainda!",
  ui_story_5004_50041201_41_dialog_content = "Tsc.",
  ui_story_5004_50041201_42_dialog_content = "Caramba, que reflexos incríveis!",
  ui_story_5004_50041201_43_dialog_content = "!!!",
  ui_story_5004_50041201_44_dialog_content = "(A bola vem na minha direção depois de Smokey se esquivar)",
  ui_story_5004_50041201_45_dialog_content = "(Embora seja um jogo de vôlei, foi nesse instante que realmente desejei ter poder de combate)",
  ui_story_5004_50041201_46_dialog_content = "(Essa pancada assassina é mais assustadora do que enfrentar Eclipsitas)",
  ui_story_5004_50041201_47_dialog_content = "(Fecho os olhos e relembro minha vida inteira)",
  ui_story_5004_50041201_48_dialog_content = "(Tomara que Vice consiga me tirar do mar a tempo)",
  ui_story_5004_50041201_49_dialog_content = "Imaginando que gosto tem a água do mar?",
  ui_story_5004_50041201_50_dialog_content = "PlayerName!",
  ui_story_5004_50041201_51_dialog_content = "Vice, você tá bem?",
  ui_story_5004_50041201_52_dialog_content = "Estou bem, embora isso quase tenha me tirado do jogo.",
  ui_story_5004_50041201_53_dialog_content = "Ei, o jogo ainda não tinha começado. Isso é contra as regras, Genevieve!",
  ui_story_5004_50041201_54_dialog_content = "PlayerName, você leu o manual que te dei, né?",
  ui_story_5004_50041201_55_dialog_content = "Quem tem tempo para ler um livro grosso cheio de anúncios?",
  ui_story_5004_50041201_56_dialog_content = "Então não me culpe.",
  ui_story_5004_50041201_57_dialog_content = "Manda ver! Mostre do que é capaz para os céus!",
  ui_story_5004_50041201_58_dialog_content = "(Que ingenuidade a minha pensar que seria o jogo de vôlei que eu conhecia)",
  ui_story_5004_50041201_59_dialog_content = "(Isso é um verdadeiro combate de praia)",
  ui_story_5004_50041202_1_dialog_content = "Ainda... não... acabei...",
  ui_story_5004_50041202_2_dialog_content = "Isso é tudo que consegue?",
  ui_story_5004_50041202_3_dialog_content = "Desculpe, PlayerName. Se soubesse, teria trazido Casulo Lunar...",
  ui_story_5004_50041202_4_dialog_content = "Tudo bem. Casulo Lunar só iria furar a bola de qualquer jeito. Ainda temos Brock e o resto. Poupem energia.",
  ui_story_5004_50041202_5_dialog_content = "Ei, pessoal, coloquem mais força nisso!",
  ui_story_5004_50041202_6_dialog_content = "Cala a boca!",
  ui_story_5004_50041202_7_dialog_content = "Ei, presta atenção na bola!",
  ui_story_5004_50041202_8_dialog_content = "Valeu, Brock!",
  ui_story_5004_50041202_9_dialog_content = "Reagrupar e passar a bola para Genevieve!",
  ui_story_5004_50041202_10_dialog_content = "<size=45>Isso!</size>",
  ui_story_5004_50041202_11_dialog_content = "Genevieve está me ignorando. Não me considera uma ameaça?",
  ui_story_5004_50041202_12_dialog_content = "quando a situação piora, é hora de trazer a <color=#FFB400>artilharia pesada</color>!",
  ui_story_5004_50041202_13_dialog_content = "Espera, o que você fez?",
  ui_story_5004_50041202_14_dialog_content = "Isso é um <color=#FFB400>braço mecânico</color>?",
  ui_story_5004_50041202_15_dialog_content = "Ahn, não, é simplesmente a <color=#FFB400>minha mão</color>.",
  ui_story_5004_50041202_16_dialog_content = "Chamo de Tormento RX100. Criei junto com Tiny One e me certifiquei de triplicar sua potência!",
  ui_story_5004_50041202_17_dialog_content = "Batizou de Tormento? Não é o nome do braço robótico da Jona?",
  ui_story_5004_50041202_18_dialog_content = "A única diferença é esse vermelho no punho. Como pode ser três vezes mais potente?",
  ui_story_5004_50041202_19_dialog_content = "Minha mão direita arde na chama da vitória!",
  ui_story_5004_50041202_20_dialog_content = "Deixa de brincadeira! É óbvio que esse braço não vai funcionar!",
  ui_story_5004_50041202_21_dialog_content = "Ninguém supera a precisão e força da minha criação!",
  ui_story_5004_50041202_22_dialog_content = "Óbvio, é mecânica!",
  ui_story_5004_50041202_23_dialog_content = "É tão poderosa que pode empurrar um alvo por três metros sem bola.",
  ui_story_5004_50041202_24_dialog_content = "Meu receio é que seja poderosa demais...",
  ui_story_5004_50041202_25_dialog_content = "Claro, já falei que é mecânica. Tire isso antes que sejamos desclassificados!",
  ui_story_5004_50041202_26_dialog_content = "Ainda aí? Brock, você não percebeu...",
  ui_story_5004_50041202_27_dialog_content = "Cuidado!",
  ui_story_5004_50041202_28_dialog_content = "Uma brecha!",
  ui_story_5004_50041202_29_dialog_content = "<color=#e8d9bb>Esmaga, esmaga!</color>",
  ui_story_5004_50041202_30_dialog_content = "Aiiii, ui...",
  ui_story_5004_50041202_31_dialog_content = "Já era... O céu... é tão lindo...",
  ui_story_5004_50041202_32_dialog_content = "Brock desabou na areia! Isso é mesmo um jogo de vôlei normal?!",
  ui_story_5004_50041202_33_dialog_content = "O primeiro jogo acabou. Hora de uma pausa rápida.",
  ui_story_5004_50041202_34_dialog_content = "Por favor, ouça nossos patrocinadores durante o intervalo.",
  ui_story_5004_50041202_X33_dialog_content = "3",
  ui_story_5004_50041202_X34_dialog_content = "2",
  ui_story_5004_50041202_X35_dialog_content = "1",
  ui_story_5004_50041202_35_dialog_content = "Queremos apresentar os melhores pacotes de temporada da Guilda Cloudrover.",
  ui_story_5004_50041202_36_dialog_content = "Toque no ícone para obter a oferta especial exclusiva da Bonacie, além de mais 10 Fulgores Estelares Especiais!",
  ui_story_5004_50041202_37_dialog_content = "E mais um tanque de arma d'água inflável, ideal para a praia!",
  ui_story_5004_50041202_38_dialog_content = "Se apresse, apenas 5.000 unidades... não, agora só restam 1.001!",
  ui_story_5004_50041202_39_dialog_content = "Obtenha um agora mesmo antes que acabem!",
  ui_story_5004_50041202_40_dialog_content = "Minha nossa, esgotou em apenas 10 segundos!",
  ui_story_5004_50041202_41_dialog_content = "Bem, fique ligado na Rede de Compras Bonacie. Até a próxima!",
  ui_story_5004_50041202_42_dialog_content = "Não é o momento de ficar assistindo a comerciais!",
  ui_story_5004_50041202_43_dialog_content = "Então, agora somos só eu e a Smokey?",
  ui_story_5004_50041202_44_dialog_content = "Ei, você, pare de enrolar e faça algo!",
  ui_story_5004_50041202_45_dialog_content = "O quê? Sério? Achei que podiam ser mais úteis do que isso.",
  ui_story_5004_50041202_46_dialog_content = "Vocês são um bando de fracassados!",
  ui_story_5004_50041202_47_dialog_content = "Mas bloquearam vários golpes!",
  ui_story_5004_50041202_48_dialog_content = "Se elas, você teria se dado mal!",
  ui_story_5004_50041202_49_dialog_content = "Vai mesmo desistir e desperdiçar o sacrifício que fizeram?",
  ui_story_5004_50041202_50_dialog_content = "Tudo bem, tá booom. Mas você também não estava só acompanhando esse tempo todo?",
  ui_story_5004_50041202_51_dialog_content = "Sendo assim, não quero ficar devendo a ninguém.",
  ui_story_5004_50041202_52_dialog_content = "Apenas se afaste e preste atenção. Lembre-se de comentar meus movimentos incríveis!",
  ui_story_5004_50041202_53_dialog_content = "Comentar? Tudo bem, posso fazer isso! O que for preciso para que você realmente jogue!",
  ui_story_5004_50041202_54_dialog_content = "Resolvido então!",
  ui_story_5004_50041202_55_dialog_content = "Ei...",
  ui_story_5004_50041202_56_dialog_content = "Genevieve!",
  ui_story_5004_50041202_57_dialog_content = "O que foi? Vai admitir a derrota?",
  ui_story_5004_50041202_58_dialog_content = "Me diz uma coisa, você se importa mesmo tanto assim em ser superada por alguém?",
  ui_story_5004_50041202_59_dialog_content = "Claro! Minha família e meu orgulho não suportariam que eu perdesse para ninguém, especialmente você!",
  ui_story_5004_50041202_60_dialog_content = "Você tirou minha glória. Tenho acompanhado seus passos todos esses anos.",
  ui_story_5004_50041202_61_dialog_content = "Só para chegar o dia que finalmente possa te derrotar e apreciar a dor e arrependimento em seu rosto!",
  ui_story_5004_50041202_62_dialog_content = "Bem, que pena.",
  ui_story_5004_50041202_63_dialog_content = "O quê?",
  ui_story_5004_50041202_64_dialog_content = "Porque também detesto perder!",
  ui_story_5004_50041202_65_dialog_content = "Então me mostre do que é capaz!",
  ui_story_5004_50041202_66_dialog_content = "Vejamos se realmente pode me derrotar!",
  ui_story_5004_50041202_67_dialog_content = "<anim type=Shake><size=45>SUPER PANCADA TORMENTA INFERNAL!</size></anim>",
  ui_story_5004_50041202_68_dialog_content = "!!!",
  ui_story_5004_50041202_69_dialog_content = "Caramba! A bola está envolta em fogo do inferno rasgando o ar direto pra cima de Genevieve!",
  ui_story_5004_50041202_70_dialog_content = "(Na verdade estou narrando cada jogada! É constrangedor...)",
  ui_story_5004_50041202_71_dialog_content = "Genevieve!",
  ui_story_5004_50041202_72_dialog_content = "Os fãs de Genevieve formaram um círculo para protegê-la. Será que dá certo?",
  ui_story_5004_50041202_73_dialog_content = "Como um meteorito, a bola acerta em cheio a multidão!",
  ui_story_5004_50041202_74_dialog_content = "A pobre Genevieve e seus fãs são arremessados para longe! Inclusive tem uma cratera profunda no campo!",
  ui_story_5004_50041202_75_dialog_content = "A vitória é da... Equipe PlayerName!",
  ui_story_5004_50041202_76_dialog_content = "Smokey aponta para o céu, fazendo sua pose característica! Que pancada incrível!",
  ui_story_5004_50041202_77_dialog_content = "Você é competente como comentarista. Conseguiu captar ao menos metade da minha grandeza em seu comentário.",
  ui_story_5004_50041202_78_dialog_content = "Valeu... mas esse não devia ser o trabalho de alguém que NÃO está jogando?",
  ui_story_5004_50041202_79_dialog_content = "Enfim, devo dizer que foi absolutamente incrível! Acertou todo mundo de uma só vez!",
  ui_story_5004_50041202_80_dialog_content = "(Ela é um monstro! Por que sinto pena da Genevieve assim de repente?)",
  ui_story_5004_50041301_1_dialog_content = "Ah... cansei.",
  ui_story_5004_50041301_2_dialog_content = "Embora não fiz muita coisa, ainda é cansativo fugir da bola...",
  ui_story_5004_50041301_3_dialog_content = "Não imaginei que seria tão intenso e é apenas o primeiro dia.",
  ui_story_5004_50041301_4_dialog_content = "Genevieve é poderosa, mas Smokey é outro nível..",
  ui_story_5004_50041301_5_dialog_content = "O que rola entre essas duas afinal?",
  ui_story_5004_50041301_6_dialog_content = "Beryl e Raphaela foram pescar depois. Pareciam ter se divertido bastante.",
  ui_story_5004_50041301_7_dialog_content = "Beryl parecia esgotada, mas ficaria bem com Raphaela por perto.",
  ui_story_5004_50041301_8_dialog_content = "Ah, preciso agradecer a Vice pela pancada que levou por mim.",
  ui_story_5004_50041301_9_dialog_content = "Ainda estaria em recuperação se não fosse por ela.",
  ui_story_5004_50041301_10_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5004_50041301_11_dialog_content = "Está acordado, PlayerName?",
  ui_story_5004_50041301_12_dialog_content = "Tô indo.",
  ui_story_5004_50041301_13_dialog_content = "O que foi, Carleen?",
  ui_story_5004_50041301_14_dialog_content = "Só conferindo se estava dormindo, PlayerName.",
  ui_story_5004_50041301_15_dialog_content = "Não é sempre que venho à praia. Não queria ficar socada no quarto a noite toda.",
  ui_story_5004_50041301_16_dialog_content = "Quer dar um passeio comigo?",
  ui_story_5004_50041301_17_dialog_content = "Claro, adoraria!",
  ui_story_5004_50041301_19_dialog_content = "Então vamos nessa!",
  ui_story_5004_50041301_20_dialog_content = "OK.",
  ui_story_5004_50041301_21_dialog_content = "Isso parece meio estranho.",
  ui_story_5004_50041301_22_dialog_content = "PlayerName.",
  ui_story_5004_50041301_23_dialog_content = "O que? Estou aqui!",
  ui_story_5004_50041301_24_dialog_content = "Sobre Aviduz e Schummer... Sempre quis demonstrar minha gratidão formalmente.",
  ui_story_5004_50041301_25_dialog_content = "Tudo bem, não precisa.",
  ui_story_5004_50041301_26_dialog_content = "Você e a Vice também me ajudaram bastante.",
  ui_story_5004_50041301_27_dialog_content = "Sim. Relembrando isso numa praia tão linda...",
  ui_story_5004_50041301_28_dialog_content = "Quase parece um sonho, você não acha?",
  ui_story_5004_50041301_29_dialog_content = "Nem sei a certo se já não estou sonhando.",
  ui_story_5004_50041301_30_dialog_content = "Quando te conheci, não pude acreditar que você ficou mais de uma década sozinho...",
  ui_story_5004_50041301_31_dialog_content = "Você foi o primeiro Celestita que conheci... Acho incrível conhecer alguém que viu o Rastro de Luz.",
  ui_story_5004_50041301_32_dialog_content = "Você provou várias vezes que é um ótimo líder.",
  ui_story_5004_50041301_33_dialog_content = "Talvez você não consiga enfrentar Eclipsitas diretamente, mas nunca recuou.",
  ui_story_5004_50041301_34_dialog_content = "...",
  ui_story_5004_50041301_35_dialog_content = "Até se arriscou pelos outros.",
  ui_story_5004_50041301_36_dialog_content = "Sua dedicação e altruísmo para salvar os outros, até colocando sua vida em perigo, é testamento do seu caráter extraordinário.",
  ui_story_5004_50041301_37_dialog_content = "A coragem que demonstrou é mais respeitável do que esses nobres que apenas se importam consigo mesmos numa crise.",
  ui_story_5004_50041301_38_dialog_content = "...",
  ui_story_5004_50041301_39_dialog_content = "Está ouvindo, PlayerName?",
  ui_story_5004_50041301_40_dialog_content = "Ah, falei demais, né?",
  ui_story_5004_50041301_41_dialog_content = "Ouvi e assimilei tudo que você disse. É legal conversar com você nesta brisa.",
  ui_story_5004_50041301_42_dialog_content = "E toda a paisagem...",
  ui_story_5004_50041301_43_dialog_content = "O mar, o céu estrelado...",
  ui_story_5004_50041301_44_dialog_content = "E...",
  ui_story_5004_50041301_45_dialog_content = "...",
  ui_story_5004_50041301_46_dialog_content = "Tudo é muito bonito.",
  ui_story_5004_50041301_47_dialog_content = "...",
  ui_story_5004_50041301_48_dialog_content = "...",
  ui_story_5004_50041301_49_dialog_content = "(Sinto uma sutil mudança de humor...)",
  ui_story_5004_50041301_50_dialog_content = "É verdade! Não se vê isso em Lumópolis.",
  ui_story_5004_50041301_51_dialog_content = "O vasto céu noturno cria uma sensação de esplendor junto com as ondas calmas acariciando a areia.",
  ui_story_5004_50041301_52_dialog_content = "(Ainda bem que a Carleen não percebeu...)",
  ui_story_5004_50041301_53_dialog_content = "Os peixes deste mar adorável devem ser saborosos, não acha?",
  ui_story_5004_50041301_54_dialog_content = "Devemos pescar um para descobrir?",
  ui_story_5004_50041301_55_dialog_content = "Ótima ideia, mas não sei cozinhar.",
  ui_story_5004_50041301_56_dialog_content = "Bem, podemos levar o peixe para o hotel e pedir ao chef esquisitão para grelhar.",
  ui_story_5004_50041301_57_dialog_content = "Ou levar para Lumópolis. Conheço alguns restaurantes sossegados e saborosos.",
  ui_story_5004_50041301_58_dialog_content = "Legal! Combinado!",
  ui_story_5004_50041301_59_dialog_content = "Mas talvez seja melhor não fazer isso agora. Já é tarde e pode ser perigoso entrar na água...",
  ui_story_5004_50041301_60_dialog_content = "E você deve estar cansada do jogo de vólei de hoje, Carleen.",
  ui_story_5004_50041301_61_dialog_content = "É verdade. Fica para próxima.",
  ui_story_5004_50041301_62_dialog_content = "Ahn...?",
  ui_story_5004_50041301_63_dialog_content = "Qual o problema, PlayerName?",
  ui_story_5004_50041301_64_dialog_content = "Acho que aquela estátua acabou de brilhar.",
  ui_story_5004_50041301_65_dialog_content = "Não vi nada. Talvez seja o cansaço.",
  ui_story_5004_50041301_66_dialog_content = "Ou talvez ainda não esqueceu a Pancada Tormenta Infernal da Smokey?",
  ui_story_5004_50041301_67_dialog_content = "Você lembra do nome?",
  ui_story_5004_50041301_68_dialog_content = "Enfim, posso apenas estar vendo coisas.",
  ui_story_5004_50041301_69_dialog_content = "Vamos voltar.",
  ui_story_5004_50041301_70_dialog_content = "O descendente de Celestitas... Poder do cristal... além de que \"isso\" ainda funciona...",
  ui_story_5004_50041301_71_dialog_content = "Um bando de Aurorians idiotas oferecendo Lúmina de bom grado...",
  ui_story_5004_50041301_72_dialog_content = "Ah, uma coisinha...",
  ui_story_5004_50041301_73_dialog_content = "Beryl.",
  ui_story_5004_50041301_74_dialog_content = "É a minha vez de jogar.",
  ui_story_5004_50041501_1_dialog_content = "<color=#e8d9bb>Alguns dias atrás.</color>",
  ui_story_5004_50041501_2_dialog_content = "Droga!",
  ui_story_5004_50041501_3_dialog_content = "<color=#e8d9bb>Smokey rasgou a carta com raiva e jogou de lado.</color>",
  ui_story_5004_50041501_4_dialog_content = "Aquele moleque me enganou?",
  ui_story_5004_50041501_5_dialog_content = "Não me bata. Pagarei o que você quiser!",
  ui_story_5004_50041501_6_dialog_content = "Não estava tentando chantagear uma garota agora pouco?",
  ui_story_5004_50041501_7_dialog_content = "E agora? Vamos lá, vejamos aquela sua arrogância petulante novamente!",
  ui_story_5004_50041501_8_dialog_content = "Você acha que manda aqui?",
  ui_story_5004_50041501_9_dialog_content = "<size=45>Achou que era brincadeira</size> quando eu disse para não assediar nenhuma mulher?",
  ui_story_5004_50041501_10_dialog_content = "Eu... eu não sou daqui! Por favor, tenha piedade e me poupe. Não causarei mais problemas!",
  ui_story_5004_50041501_11_dialog_content = "Não é daqui? Tá bom, essa foi boa.",
  ui_story_5004_50041501_12_dialog_content = "Você tem 30 segundos para me dizer de onde vem, o que veio fazer aqui e quem te mandou.",
  ui_story_5004_50041501_13_dialog_content = "Se disser o que quero ouvir, deixo você ir.",
  ui_story_5004_50041501_14_dialog_content = "Do contrário...",
  ui_story_5004_50041501_15_dialog_content = "Quebrarei um dedo a cada 30 segundos. Entendeu?",
  ui_story_5004_50041501_16_dialog_content = "O primeiro dedo começa em 30, 29...",
  ui_story_5004_50041501_17_dialog_content = "Não, me deixa ir! Só faço entregas!",
  ui_story_5004_50041501_18_dialog_content = "Não sou uma má pessoa! Não pode me culpar por aquela garota quase nua!",
  ui_story_5004_50041501_19_dialog_content = "Só estou trazendo uma mensagem. Ninguém me mandou!",
  ui_story_5004_50041501_20_dialog_content = "10, 9, 8...",
  ui_story_5004_50041501_21_dialog_content = "Já contei tudo! O que mais quer que eu diga?",
  ui_story_5004_50041501_22_dialog_content = "Estala, quebra.",
  ui_story_5004_50041501_23_dialog_content = "<size=45><anim type=Shake>Aiii! Minha mão!</anim></size>",
  ui_story_5004_50041501_24_dialog_content = "Sua insana! Foram dois dedos! Qual é o seu problema?!",
  ui_story_5004_50041501_25_dialog_content = "Sua insana! Maluca! Aiii...",
  ui_story_5004_50041501_26_dialog_content = "Um dedo pelo tempo esgotado e o outro por mentir.",
  ui_story_5004_50041501_27_dialog_content = "É verdade... só me mandaram fazer entregas, droga...",
  ui_story_5004_50041501_28_dialog_content = "Me dá isso.",
  ui_story_5004_50041501_29_dialog_content = "Parou!",
  ui_story_5004_50041501_30_dialog_content = "Tem certeza? É hora do terceiro dedo... 5, 4...",
  ui_story_5004_50041501_31_dialog_content = "Não posso! Eles me matariam!",
  ui_story_5004_50041501_32_dialog_content = "ZERO.",
  ui_story_5004_50041501_33_dialog_content = "<size=45><anim type=Shake>Arghhh!</anim></size> Unf...",
  ui_story_5004_50041501_34_dialog_content = "E acha que eu não?",
  ui_story_5004_50041501_35_dialog_content = "Você decide se morre agora ou depois.",
  ui_story_5004_50041501_36_dialog_content = "Tá bom, tudo bem, me larga!",
  ui_story_5004_50041501_37_dialog_content = "Pega, ai está, sua insana!",
  ui_story_5004_50041501_38_dialog_content = "Só uma carta? O que está escrito?",
  ui_story_5004_50041501_39_dialog_content = "Aconselho que me devolva. É para alguém importante. Vai ser pior para nós se ficar com ela!",
  ui_story_5004_50041501_40_dialog_content = "Tarde demais.",
  ui_story_5004_50041501_41_dialog_content = "Agora quero saber do que se trata.",
  ui_story_5004_50041501_42_dialog_content = "O que é essa Costa Celestial?",
  ui_story_5004_50041501_43_dialog_content = "É uma mapa do tesouro?",
  ui_story_5004_50041501_44_dialog_content = "Você leu?! É o nosso fim!",
  ui_story_5004_50041501_45_dialog_content = "<size=45>Sou eu quem faz as perguntas!</size>",
  ui_story_5004_50041501_46_dialog_content = "Também não faço ideia. Só sei que são perigosos!",
  ui_story_5004_50041501_47_dialog_content = "Parece que planejam algum tipo de ritual para conjurar a perdição do mundo!",
  ui_story_5004_50041501_48_dialog_content = "Me devolve, não quero me ferrar!",
  ui_story_5004_50041501_49_dialog_content = "Hum, não bati na sua cabeça, certo?",
  ui_story_5004_50041501_50_dialog_content = "Por que está falando tanta bobagem agora?",
  ui_story_5004_50041501_51_dialog_content = "Quanto mais você fala, aumenta meu interesse.",
  ui_story_5004_50041501_52_dialog_content = "Decidi ver por conta própria!",
  ui_story_5004_50041501_53_dialog_content = "<color=#e8d9bb>Assim como a carta descrevia...</color>",
  ui_story_5004_50041501_54_dialog_content = "<color=#e8d9bb>Procuro por três paredes de lamentação</color>",
  ui_story_5004_50041501_55_dialog_content = "<color=#e8d9bb>Busco renascer das cinzas</color>",
  ui_story_5004_50041501_56_dialog_content = "<color=#e8d9bb>Chove sangue ao amanhecer</color>",
  ui_story_5004_50041501_57_dialog_content = "<color=#e8d9bb>Pintando o poente com lágrimas uivantes</color>",
  ui_story_5004_50041501_58_dialog_content = "<color=#e8d9bb>Até a hora do julgamento, o fim dos dias</color>",
  ui_story_5004_50041501_59_dialog_content = "<color=#e8d9bb>Quando o Monarca despertará</color>",
  ui_story_5004_50041501_60_dialog_content = "Que bobagem é essa? Um enigma?",
  ui_story_5004_50041501_61_dialog_content = "Não diga que vim até aqui por nada...",
  ui_story_5004_50041501_62_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5004_50041501_63_dialog_content = "Pode entrar.",
  ui_story_5004_50041501_64_dialog_content = "Olá. Srta. Smokey Manticore de Umbraton, suponho?",
  ui_story_5004_50041501_65_dialog_content = "Você me conhece?",
  ui_story_5004_50041501_66_dialog_content = "Claro. Sei quem é você, entendo porque está aqui e que a carta em suas mãos não lhe pertence.",
  ui_story_5004_50041501_67_dialog_content = "Diz logo o que você quer.",
  ui_story_5004_50041501_68_dialog_content = "Ha ha ha!",
  ui_story_5004_50041501_69_dialog_content = "...?",
  ui_story_5004_50041501_70_dialog_content = "Desculpe, mas isso foi engraçado, hein?",
  ui_story_5004_50041501_71_dialog_content = "Por que iria querer algo? Só vim convidar você para ser anfitriã do Monarca do Oceano.",
  ui_story_5004_50041501_72_dialog_content = "Só isso?",
  ui_story_5004_50041501_73_dialog_content = "Só isso.",
  ui_story_5004_50041501_74_dialog_content = "Você é da True Order e não confio em vocês.",
  ui_story_5004_50041501_75_dialog_content = "Mesmo sendo da True Order, ainda posso ser anfitriã, né?",
  ui_story_5004_50041501_76_dialog_content = "Além do mais, o materialismo é uma necessidade para perseguir A Verdade, e esse serviço paga bem.",
  ui_story_5004_50041501_77_dialog_content = "Então, gostaria de participar? Talvez o prêmio do vencedor inclua aquilo que procura.",
  ui_story_5004_50041501_78_dialog_content = "Mesmo se perder...",
  ui_story_5004_50041501_79_dialog_content = "Pode parar. Não vou perder e nem me importam as consequências da derrota.",
  ui_story_5004_50041501_80_dialog_content = "Aquela pessoa com a mensagem é da sua laia?",
  ui_story_5004_50041501_81_dialog_content = "Como posso saber?",
  ui_story_5004_50041501_82_dialog_content = "Já que estou aqui você pode abrir o jogo.",
  ui_story_5004_50041501_83_dialog_content = "Quero ver o que está tentando esconder de mim.",
  ui_story_5004_50041601_1_dialog_content = "Que a condição da Beryl se deve à instabilidade da Lúmina?",
  ui_story_5004_50041601_2_dialog_content = "Isso, falei com Beretta há alguns dias e ela encontrou casos parecidos.",
  ui_story_5004_50041601_3_dialog_content = "Também tem o arquivo sobre os Gautier...",
  ui_story_5004_50041601_4_dialog_content = "Mas está bem protegido e só pode ser acessado pelo Senhor da Cidade e alguns outros.",
  ui_story_5004_50041601_5_dialog_content = "A Beryl é uma Gautier?",
  ui_story_5004_50041601_6_dialog_content = "Isso mesmo! Ela falou da família enquanto conversávamos à noite e mencionou alguns outros familiares...",
  ui_story_5004_50041601_7_dialog_content = "Pyrrhus alguma coisa... não lembro agora.",
  ui_story_5004_50041601_8_dialog_content = "Tudo bem. Pelo visto, vocês se deram muito bem.",
  ui_story_5004_50041601_9_dialog_content = "É óbvio. Nos garotas costumamos falar sobre tudo! E Beryl é mais tagarela do que você imagina!",
  ui_story_5004_50041601_10_dialog_content = "Entendo. Bem, cuide bem dela.",
  ui_story_5004_50041601_11_dialog_content = "Pode deixar! Vou falar com Carleen e ver o que podemos fazer. Aviso você se rolar alguma coisa!",
  ui_story_5004_50041601_12_dialog_content = "Vou me encontrar com B agora! Nos vemos no jogo!",
  ui_story_5004_50041601_13_dialog_content = "Certo, tome cuidado.",
  ui_story_5004_50041601_14_dialog_content = "Argh!",
  ui_story_5004_50041601_15_dialog_content = "Tudo bem?",
  ui_story_5004_50041601_16_dialog_content = "Estou bem. Desculpe!",
  ui_story_5004_50041601_17_dialog_content = "Smokey?",
  ui_story_5004_50041601_18_dialog_content = "Você é PlayerName, certo? Quero me apresentar formalmente.",
  ui_story_5004_50041601_19_dialog_content = "Sou Smokey, de Umbraton.",
  ui_story_5004_50041601_20_dialog_content = "...",
  ui_story_5004_50041601_21_dialog_content = "...",
  ui_story_5004_50041601_22_dialog_content = "É só isso?",
  ui_story_5004_50041601_23_dialog_content = "Sim.",
  ui_story_5004_50041601_24_dialog_content = "Então, Smokey, o que traz aqui?",
  ui_story_5004_50041601_25_dialog_content = "Já que estamos na mesma equipe, achei melhor vir te conhecer.",
  ui_story_5004_50041601_26_dialog_content = "Considerando nossa última partida, teremos problemas se contarmos apenas comigo.",
  ui_story_5004_50041601_27_dialog_content = "(Tem certeza?)",
  ui_story_5004_50041601_28_dialog_content = "Então, achei melhor começar a me entrosar com a equipe.",
  ui_story_5004_50041601_29_dialog_content = "Bem, vamos nessa. Até mais.",
  ui_story_5004_50041601_30_dialog_content = "Espera.",
  ui_story_5004_50041601_31_dialog_content = "Sim?",
  ui_story_5004_50041601_32_dialog_content = "Não me leve a mal, mas o que está rolando entre você e a Genevieve?",
  ui_story_5004_50041601_33_dialog_content = "Sabia que ia me perguntar isso.",
  ui_story_5004_50041601_34_dialog_content = "Mas duvido que se satisfaça com a minha resposta.",
  ui_story_5004_50041601_35_dialog_content = "A gente nasceu em Petyaburg. Sou uma Manticora e ela é uma Vronsky.",
  ui_story_5004_50041601_36_dialog_content = "Como posso explicar... As duas famílias são rivais, embora a gente se dava muito bem quando crianças.",
  ui_story_5004_50041601_37_dialog_content = "Ela era uma gracinha, não desgrudava de mim naquela época, bem melhor do que ela é hoje.",
  ui_story_5004_50041601_38_dialog_content = "Creio que porque eu ainda era jovem, rebelde e adorava me aventurar.",
  ui_story_5004_50041601_39_dialog_content = "Durante um dos testes da Genevieve, acabei me destacando mais do que ela.",
  ui_story_5004_50041601_X39_dialog_content = "Isso chamou a atenção dos juizes e ela perdeu a chance de se tornar uma nobre de Lumópolis.",
  ui_story_5004_50041601_40_dialog_content = "O que trouxe desonra para ela e sua família.",
  ui_story_5004_50041601_41_dialog_content = "Só estava um pouco empolgada demais. Nunca imaginei que as consequências fossem tão drásticas!",
  ui_story_5004_50041601_42_dialog_content = "Por isso sai de casa. Os nobres só causam problemas.",
  ui_story_5004_50041601_43_dialog_content = "Entendo...",
  ui_story_5004_50041601_44_dialog_content = "Preciso ir. Vamos jogar melhor esta tarde.",
  ui_story_5004_50041701_1_dialog_content = "Nossa...",
  ui_story_5004_50041701_2_dialog_content = "Nervoso, PlayerName?",
  ui_story_5004_50041701_3_dialog_content = "Um pouco...",
  ui_story_5004_50041701_4_dialog_content = "Relaxa. Comandante Hiiro me ensinou que <color=#FFB400>se pode o que se quer</color>.",
  ui_story_5004_50041701_5_dialog_content = "Creio que está querendo dizer que <color=#FFB400>querer é poder</color>.",
  ui_story_5004_50041701_6_dialog_content = "Isso ai. Me pergunto se isso significa que a Comandate Hiiro vacilou alguma vez na Rediesel Wrench...",
  ui_story_5004_50041701_7_dialog_content = "(Hiiro faria você escrever isso 100 vezes se ouvisse tal coisa!)",
  ui_story_5004_50041701_8_dialog_content = "Estou trazendo o Casulo Lunar, então pode deixar o trabalho pesado comigo.",
  ui_story_5004_50041701_9_dialog_content = "Vou disparar mísseis de fora do campo para apoiar vocês!",
  ui_story_5004_50041701_10_dialog_content = "Nem pensar! Pode ser um combate, mas ainda precisamos seguir as regras básicas.",
  ui_story_5004_50041701_11_dialog_content = "Reserve os mísseis para os Eclipsitas, a Raphaela.",
  ui_story_5004_50041701_12_dialog_content = "Você é um Anjo de Lumópolis, afinal.",
  ui_story_5004_50041701_13_dialog_content = "É mesmo. Também preciso reservar para proteger a Beryl.",
  ui_story_5004_50041701_14_dialog_content = "Só vou ficar torcendo por você e a Beryl!",
  ui_story_5004_50041701_15_dialog_content = "Ei Vice, acho que um arco não é o adequado para a posição em que vai jogar.",
  ui_story_5004_50041701_16_dialog_content = "Tem razão, por isso pedi a Beryl para incluir lâminas de cristal ao arco!",
  ui_story_5004_50041701_17_dialog_content = "Tentamos, mas não conseguimos nada adequado até esta manhã...",
  ui_story_5004_50041701_18_dialog_content = "Seria ótimo se fosse útil...",
  ui_story_5004_50041701_19_dialog_content = "Parece bastante resistente e afiado. Pelo visto, Beryl se dedicou com afinco nele.",
  ui_story_5004_50041701_20_dialog_content = "(Beryl é demais...)",
  ui_story_5004_50041701_21_dialog_content = "Valeu. Vamos nessa rumo à vitória!",
  ui_story_5004_50041701_22_dialog_content = "Isso! Sempre confiante e animada, Vice!",
  ui_story_5004_50041701_23_dialog_content = "(Mas tem certeza de que quer usar lâminas quando na verdade é uma arqueira?)",
  ui_story_5004_50041701_24_dialog_content = "Talvez não devia se tornar numa guerra, já que é apenas um jogo de xadrez.",
  ui_story_5004_50041701_25_dialog_content = "Seria ótimo, mas nem a Smokey e muito menos a Genevieve desistem facilmente.",
  ui_story_5004_50041701_26_dialog_content = "Então, precisamos nos preparar para qualquer coisa.",
  ui_story_5004_50041701_27_dialog_content = "Aham, vejo que não falta ninguém.",
  ui_story_5004_50041701_28_dialog_content = "Ei, segura a onda um pouco.",
  ui_story_5004_50041701_29_dialog_content = "Dizem que a origem do aclamado jogo de xadrez foi aqui.",
  ui_story_5004_50041701_30_dialog_content = "Certa vez, um monarca sábio e bondoso queria que seus súditos fossem inteligentes e espertos.",
  ui_story_5004_50041701_31_dialog_content = "Então inventou o jogo para aperfeiçoar seu senso crítico e raciocínio tático.",
  ui_story_5004_50041701_32_dialog_content = "O resultado foi um exército formidável que era temido até pelos Eclipsitas e protegia o reino de qualquer ameaça.",
  ui_story_5004_50041701_33_dialog_content = "Mas isso é coisa do passado.",
  ui_story_5004_50041701_34_dialog_content = "Em memória daquele monarca, daremos início à segunda disputa, um jogo de xadrez com pessoas reais!",
  ui_story_5004_50041701_35_dialog_content = "A partir de agora, começa o jogo de xadrez da inteligência e determinação!",
  ui_story_5004_50041701_36_dialog_content = "PlayerName!",
  ui_story_5004_50041701_37_dialog_content = "Aqui!",
  ui_story_5004_50041701_38_dialog_content = "Fique atento e assuma o comando. Faremos o melhor para alcançar a vitória.",
  ui_story_5004_50041701_39_dialog_content = "(Foco... eu consigo. Afinal, já joguei algumas partidas de xadrez com Barton)",
  ui_story_5004_50041701_40_dialog_content = "(Só preciso relembrar daquelas jogadas...)",
  ui_story_5004_50041701_41_dialog_content = "Vencemos porque <color=#FFB400>os generais abriram o caminho para nós</color>.",
  ui_story_5004_50041701_42_dialog_content = "Saquei!",
  ui_story_5004_50041701_43_dialog_content = "Você estaria orgulhoso Barton... sou o general e devo abrir o caminho!",
  ui_story_5004_50041701_44_dialog_content = "Minha vez!",
  ui_story_5004_50041701_45_dialog_content = "Rei se move uma posição!",
  ui_story_5004_50041701_46_dialog_content = "...",
  ui_story_5004_50041701_47_dialog_content = "Ah, PlayerName, eu não sei jogar xadrez...",
  ui_story_5004_50041701_48_dialog_content = "Mas não creio que deva avançar, a menos que queira ir de cavalinho.",
  ui_story_5004_50041701_49_dialog_content = "Hehe!",
  ui_story_5004_50041701_50_dialog_content = "Sei quem você é que seu povo costuma ter comandantes talentosos, Celestita.",
  ui_story_5004_50041701_51_dialog_content = "Mas acho que não entendeu as sutilezas do jogo de xadrez!",
  ui_story_5004_50041701_52_dialog_content = "Para equivaler aos seus Aurorians, contratei especificamente as <color=#FFB400>guerreiras</color> mais poderosas!",
  ui_story_5004_50041701_53_dialog_content = "Nossa, ela fala demais. Achei que tínhamos combinado em ficar na surdina.",
  ui_story_5004_50041701_54_dialog_content = "Ei chefia, essa é uma violação de contrato conforme descrito na Seção III, Cláusula 9.",
  ui_story_5004_50041701_55_dialog_content = "É um custo adicional de 135% conforme o acordo.",
  ui_story_5004_50041701_56_dialog_content = "Cala a boca, pagarei o que você merece! Ao ataque!",
  ui_story_5004_50041701_57_dialog_content = "PlayerName, fique comigo. Vou ajudar você a avançar.",
  ui_story_5004_50041701_58_dialog_content = "Tá bom, valeu!",
  ui_story_5004_50041701_59_dialog_content = "Toma essa!",
  ui_story_5004_50041701_60_dialog_content = "Caramba, sua técnica com a lâmina é quase tão hábil quanto a da Comandante Hiiro!",
  ui_story_5004_50041701_61_dialog_content = "E o estilo de luta... Você é...?",
  ui_story_5004_50041701_62_dialog_content = "Bem, creio que já posso revelar minha identidade.",
  ui_story_5004_50041701_63_dialog_content = "Sr. Taki?!",
  ui_story_5004_50041701_64_dialog_content = "Taki?",
  ui_story_5004_50041701_65_dialog_content = "O que está fazendo aqui?",
  ui_story_5004_50041701_66_dialog_content = "Desculpe, mas a Trabalhos Estranhos aceita qualquer serviço remunerado, desde que não seja imoral!",
  ui_story_5004_50041701_67_dialog_content = "E não vou facilitar só por que é um jogo!",
  ui_story_5004_50041701_68_dialog_content = "Sugiro que você se renda, PlayerName. Não quero ferir alguém desarmado!",
  ui_story_5004_50041701_69_dialog_content = "Sr. Taki, se você for descoberto vai prejudicar meus negócios!",
  ui_story_5004_50041701_70_dialog_content = "Ai está a brecha!",
  ui_story_5004_50041701_71_dialog_content = "Ai!",
  ui_story_5004_50041701_72_dialog_content = "Pega leve, Carleen. O coco está prestes a estourar.",
  ui_story_5004_50041701_72X1_dialog_content = "O quê? São capacetes, não cocos de verdade!",
  ui_story_5004_50041701_72X2_dialog_content = "Ah, é mesmo... Droga, isso parecia realmente um coco.",
  ui_story_5004_50041701_73_dialog_content = "Sabia que era você, Jomu.",
  ui_story_5004_50041701_74_dialog_content = "Tenho minhas razões... quer dizer, eu posso explicar! Aceitei o serviço <color=#FFB400>por você</color>, chefia!",
  ui_story_5004_50041701_75_dialog_content = "Ahn? Por mim?",
  ui_story_5004_50041701_76_dialog_content = "Isso! Se conseguir o bônus da Genevieve, posso ampliar meu negócio.",
  ui_story_5004_50041701_77_dialog_content = "Talvez no futuro você até possa comprar de mim coisas tipo <color=#FFB400>Lumocristal</color> com Noitium.",
  ui_story_5004_50041701_78_dialog_content = "Oferecerei preços especiais e uma <color=#FFB400>linda caixinha</color> de edição limitada junto.",
  ui_story_5004_50041701_79_dialog_content = "PlayerName, os outros usando <color=#FFFFFF>capacetes</color> também parecem suspeitos!",
  ui_story_5004_50041701_80_dialog_content = "É só arrancá-los!",
  ui_story_5004_50041701_81_dialog_content = "Isso mesmo! Vocês conseguem, Vice e Carleen!",
  ui_story_5004_50041701_82_dialog_content = "Acabou o diesel da minha serra! Tchau!",
  ui_story_5004_50041701_83_dialog_content = "Desisto. Até mais!",
  ui_story_5004_50041701_84_dialog_content = "Piu!",
  ui_story_5004_50041701_85_dialog_content = "Tsc, eu sabia, um bando de pessoas nada confiáveis.",
  ui_story_5004_50041701_86_dialog_content = "Ahh, parece que a competição chegou a um impasse, né?",
  ui_story_5004_50041701_87_dialog_content = "Temos desertores de um lado, mas o outro está prestes a lançar um xeque-mate.",
  ui_story_5004_50041701_88_dialog_content = "Ei, me mova a seguir!",
  ui_story_5004_50041701_89_dialog_content = "Promoção ou xeque-mate, vou pegar Genevieve desde que me aproxime dela.",
  ui_story_5004_50041701_90_dialog_content = "Acho que não. Precisamos que Carleen volte para defender Vice e reagrupar!",
  ui_story_5004_50041701_91_dialog_content = "O tempo está acabando. O adversário está está desaminando, devemos aproveitar a chance! Não dá tempo pra salvar sua namorada.",
  ui_story_5004_50041701_92_dialog_content = "O quê? Ela não é...",
  ui_story_5004_50041701_93_dialog_content = "Me ouça e venceremos! Depressa!",
  ui_story_5004_50041701_94_dialog_content = "OK.",
  ui_story_5004_50041701_95_dialog_content = "Genevieve!",
  ui_story_5004_50041701_96_dialog_content = "Pode vir, Smokey!",
  ui_story_5004_50041701_97_dialog_content = "Ha!",
  ui_story_5004_50041701_98_dialog_content = "Começando com o movimento mais poderoso?!",
  ui_story_5004_50041701_99_dialog_content = "Hehe!",
  ui_story_5004_50041701_100_dialog_content = "São equivalentes! Como é possível? Genevieve tem habilidades de luta tão boas assim?",
  ui_story_5004_50041701_101_dialog_content = "Da última vez eu vacilei. Não se engane achando que vai me derrotar sempre.",
  ui_story_5004_50041701_102_dialog_content = "Você melhorou, mas jamais pense que vai me superar.",
  ui_story_5004_50041701_103_dialog_content = "Isso precisa acabar. Elas tem poderes equivalentes e vão acabar destruindo o local!",
  ui_story_5004_50041701_104_dialog_content = "Parece que terei que interferir, né?",
  ui_story_5004_50041701_105_dialog_content = "Vamos animar as coisas com algumas regras novas!",
  ui_story_5004_50041701_106_dialog_content = "Jogo alternativo!",
  ui_story_5004_50041701_107_dialog_content = "Há um pedaço de Cristal Rei que escondi em algum lugar no campo antes do jogo.",
  ui_story_5004_50041701_108_dialog_content = "A regra é clara. Vence o lado do primeiro rei que o encontrar.",
  ui_story_5004_50041701_109_dialog_content = "Acho que não há outra alternativa... Adiante! Meus fãs!",
  ui_story_5004_50041701_110_dialog_content = "Atacar! Atacar!",
  ui_story_5004_50041701_111_dialog_content = "Por Lady Genevieve!",
  ui_story_5004_50041701_112_dialog_content = "Estava imaginando quando iriam aparecer.",
  ui_story_5004_50041701_113_dialog_content = "Espera ai, qual é o problema com as pistolas d'água? E por que os fãs estão participando do jogo?",
  ui_story_5004_50041701_114_dialog_content = "Você devia ler o manual. Te enviei um novo, certo?",
  ui_story_5004_50041701_115_dialog_content = "O novo manual tem o dobro da grossura do antigo!",
  ui_story_5004_50041701_116_dialog_content = "Bem, a partida anterior foi incrível, vários patrocinadores novos se inscreveram.",
  ui_story_5004_50041701_117_dialog_content = "Já que Genevieve resistiu por bastante tempo, o jogo terminou empatado.",
  ui_story_5004_50041701_118_dialog_content = "Agora estamos no jogo alternativo, onde só é permitido usar pistolas d'água!",
  ui_story_5004_50041701_119_dialog_content = "Enfim, PlayerName, você não irá longe se depender dos outros para ler o Manual de de Batalha...",
  ui_story_5004_50041701_120_dialog_content = "Não posso acreditar que deixou de ser uma competição séria para se tornar um joguinho de verão!",
  ui_story_5004_50041701_121_dialog_content = "E nem sequer trouxemos pistolas d'água...",
  ui_story_5004_50041701_122_dialog_content = "Ei. o que é isso nas suas mãos?",
  ui_story_5004_50041701_123_dialog_content = "Proteja-se e contra-ataque, Vice!",
  ui_story_5004_50041701_124_dialog_content = "Entendi! Proteja-se também, PlayerName!",
  ui_story_5004_50041701_125_dialog_content = "Não tenho armas!",
  ui_story_5004_50041701_126_dialog_content = "Pega, PlayerName!",
  ui_story_5004_50041701_127_dialog_content = "Valeu, Beryl!",
  ui_story_5004_50041701_128_dialog_content = "Boa tentativa!",
  ui_story_5004_50041701_129_dialog_content = "Argh!",
  ui_story_5004_50041701_130_dialog_content = "Pensa em alguma coisa, Smokey!",
  ui_story_5004_50041701_131_dialog_content = "Acho que chegou a hora de mostrar meu arsenal!",
  ui_story_5004_50041701_132_dialog_content = "Onde conseguiu essas <color=#FFB400>super pistolas d'água</color>?!",
  ui_story_5004_50041701_133_dialog_content = "Não pense que isso facilitará sua vitória!",
  ui_story_5004_50041701_134_dialog_content = "Droga! Protejam Lady Genevieve a qualquer custo!",
  ui_story_5004_50041701_135_dialog_content = "Não consigo continuar, Capitã...",
  ui_story_5004_50041701_136_dialog_content = "Argh!",
  ui_story_5004_50041701_136X1_dialog_content = "Como ousa acertar meus fãs!",
  ui_story_5004_50041701_136X2_dialog_content = "Não terei piedade de você!",
  ui_story_5004_50041701_136X3_dialog_content = "Aiii, não consigo enxergar!",
  ui_story_5004_50041701_136X4_dialog_content = "Recue, Vice, eu te dou cobertura.",
  ui_story_5004_50041701_136X5_dialog_content = "Vou te mostrar o poder da minha Caçadora de Rosas!",
  ui_story_5004_50041701_136X6_dialog_content = "Ei!",
  ui_story_5004_50041701_136X7_dialog_content = "Aiii, também não consigo enxergar.",
  ui_story_5004_50041701_136X8_dialog_content = "Você consegue, Carleen. Não estamos embaixo do mar.",
  ui_story_5004_50041701_136X9_dialog_content = "Vocês não usam Lumináticas de água? Como podem ser derrotadas tão facilmente por  pistolas d'água?",
  ui_story_5004_50041701_136X10_dialog_content = "Hahaha! Renda-se, a menos que queira ser encharcada!",
  ui_story_5004_50041701_136X11_dialog_content = "Você é irritante demais!",
  ui_story_5004_50041701_136X12_dialog_content = "Smokey? Sabia que meus fãs não conseguiriam te segurar por muito tempo.",
  ui_story_5004_50041701_136X13_dialog_content = "Pessoal, mirem na Smokey enquanto eu cuido desses dois!",
  ui_story_5004_50041701_138_dialog_content = "Sim, minha senhora!",
  ui_story_5004_50041701_139_dialog_content = "Vai, vai, vai!",
  ui_story_5004_50041701_140_dialog_content = "Tsc, não consigo mirar com tanta água!",
  ui_story_5004_50041701_141_dialog_content = "Conseguiram neutralizar Smokey! Faça alguma coisa, Brock!",
  ui_story_5004_50041701_142_dialog_content = "O que posso fazer? Você nem leu as regras, porque eu deveria?",
  ui_story_5004_50041701_143_dialog_content = "Estou totalmente despreparado. Quer que eu saia socando todo mundo?",
  ui_story_5004_50041701_144_dialog_content = "Brock, PlayerName! Vejam o que achei no meu bolso?",
  ui_story_5004_50041701_145_dialog_content = "Uma <color=#FFB400>barraca</color> impermeável! Querem abrigo?",
  ui_story_5004_50041701_146_dialog_content = "Ninguém quer se enfiar numa barraca com você!",
  ui_story_5004_50041701_147_dialog_content = "Mas não é relaxante ouvir o som da água espirrando na barraca?",
  ui_story_5004_50041701_148_dialog_content = "Também tenho uma <color=#FFB400>cadeira dobrável</color>. Quer sentar?",
  ui_story_5004_50041701_149_dialog_content = "Não!",
  ui_story_5004_50041701_150_dialog_content = "Ei, pessoal não é hora de ficar acampando!",
  ui_story_5004_50041701_151_dialog_content = "Você é o Brock, certo?",
  ui_story_5004_50041701_152_dialog_content = "Sim. O que você quer?",
  ui_story_5004_50041701_153_dialog_content = "Vou criar uma brecha e você lança PlayerName pelo meio para desenterrar a peça!",
  ui_story_5004_50041701_154_dialog_content = "COMO É QUE É?",
  ui_story_5004_50041701_155_dialog_content = "Por que eu faria isso?",
  ui_story_5004_50041701_156_dialog_content = "Você não consegue nem fazer isso? Então entra naquela barraca besta e se esconde!",
  ui_story_5004_50041701_157_dialog_content = "Você... Tudo bem, isso pode doer um pouco, PlayerName!",
  ui_story_5004_50041701_158_dialog_content = "Caramba, deve ter outra alternativa!",
  ui_story_5004_50041701_159_dialog_content = "3... 2...",
  ui_story_5004_50041701_160_dialog_content = "Me abaixa e vamos pensar melhor! Brock!",
  ui_story_5004_50041701_161_dialog_content = "1!",
  ui_story_5004_50041701_162_dialog_content = "É melhor você ter boa pontaria!",
  ui_story_5004_50041701_163_dialog_content = "...",
  ui_story_5004_50041701_164_dialog_content = "...",
  ui_story_5004_50041701_165_dialog_content = "PlayerName...",
  ui_story_5004_50041701_166_dialog_content = "Acorda!",
  ui_story_5004_50041701_167_dialog_content = "Mãmãe?",
  ui_story_5004_50041701_168_dialog_content = "Acorda, PlayerName.",
  ui_story_5004_50041701_169_dialog_content = "Brock?!",
  ui_story_5004_50041701_170_dialog_content = "Vencemos. Brock lançou você através do escudo d'água dos fãs. Você bateu a cabeça no chão e fez um buraco bem onde estava a peça, então... você achou e vencemos.",
  ui_story_5004_50041701_171_dialog_content = "Você desmaiou na hora, mas os fãs da Genevieve ficaram frustrados e atiraram em você antes que Genevieve conseguisse fazê-los parar.",
  ui_story_5004_50041701_172_dialog_content = "Desculpe, você estava quase se afogando e só Brock sabia fazer reanimação cardiorrespiratória.",
  ui_story_5004_50041701_173_dialog_content = "Tudo bem. Posso descansar um pouco?",
  ui_story_5004_50041901_1_dialog_content = "...",
  ui_story_5004_50041901_2_dialog_content = "Genevieve.",
  ui_story_5004_50041901_3_dialog_content = "A responsabilidade de restaurar o nome dos Vronsky recai sobre seus ombros.",
  ui_story_5004_50041901_4_dialog_content = "...",
  ui_story_5004_50041901_5_dialog_content = "Você deve se submeter a um treinamento rigoroso, embora seja uma criança.",
  ui_story_5004_50041901_6_dialog_content = "É pelo seu próprio bem.",
  ui_story_5004_50041901_7_dialog_content = "Sim, pai, mãe, eu entendo.",
  ui_story_5004_50041901_8_dialog_content = "Esta é sua mentora de Luminática e etiqueta. Ela era uma nobre importante em Lumópolis.",
  ui_story_5004_50041901_9_dialog_content = "Você deve acompanhar sua mentora e estudar bastante pela Família Vronsky.",
  ui_story_5004_50041901_10_dialog_content = "Sim, entendi.",
  ui_story_5004_50041901_11_dialog_content = "Você precisa superar aquela garota Manticora.",
  ui_story_5004_50041901_12_dialog_content = "Genevieve? Genevieve?",
  ui_story_5004_50041901_13_dialog_content = "Me perdoe, madame.",
  ui_story_5004_50041901_14_dialog_content = "Não é do seu feitio se distrair.",
  ui_story_5004_50041901_15_dialog_content = "Fiquei acordada até tarde na noite passada terminando a tarefa que me passou.",
  ui_story_5004_50041901_16_dialog_content = "A tarefa era para a semana toda. Não precisava fazer tudo de uma vez.",
  ui_story_5004_50041901_17_dialog_content = "...",
  ui_story_5004_50041901_18_dialog_content = "O que deseja ser quando crescer, Genevieve?",
  ui_story_5004_50041901_19_dialog_content = "Obter honra e glória para a família?",
  ui_story_5004_50041901_20_dialog_content = "Perguntei o que você gostaria de fazer.",
  ui_story_5004_50041901_21_dialog_content = "Não sei. Não tenho certeza. Talvez nunca tenha pensado nisso.",
  ui_story_5004_50041901_22_dialog_content = "Tudo bem. Vamos esquecer o assunto.",
  ui_story_5004_50041901_23_dialog_content = "Você foi ver aquela garota Manticora na semana passada, certo, Genevieve?",
  ui_story_5004_50041901_24_dialog_content = "Como descobriu?",
  ui_story_5004_50041901_25_dialog_content = "Tudo bem. Não vou contar pra ninguém.",
  ui_story_5004_50041901_26_dialog_content = "Eu agradeço.",
  ui_story_5004_50041901_27_dialog_content = "Mas por que você...",
  ui_story_5004_50041901_28_dialog_content = "Esquece, não devo perguntar essas coisas.",
  ui_story_5004_50041901_29_dialog_content = "...",
  ui_story_5004_50041901_30_dialog_content = "Mas Genevieve, talvez você não deva ficar obcecada em obter glória para sua família.",
  ui_story_5004_50041901_31_dialog_content = "Por que não?",
  ui_story_5004_50041901_32_dialog_content = "Sabe por que eu ERA uma nobre importante?",
  ui_story_5004_50041901_33_dialog_content = "Obrigado por tudo que ensinou a ela nesses anos.",
  ui_story_5004_50041901_34_dialog_content = "Genevieve é muito talentosa e esforçada.",
  ui_story_5004_50041901_35_dialog_content = "Ela se tornou mais competente com a magia de ritual do que muitos nobres.",
  ui_story_5004_50041901_36_dialog_content = "E por isso, não há mais nada que possa ensinar a ela.",
  ui_story_5004_50041901_37_dialog_content = "Para onde você vai, madame?",
  ui_story_5004_50041901_38_dialog_content = "Como você diria, eu não faço ideia. Talvez ir em busca de algo ou alguém.",
  ui_story_5004_50041901_39_dialog_content = "Vai saber, é uma jornada que pode valer a pena.",
  ui_story_5004_50041901_40_dialog_content = "Adeus, Genevieve.",
  ui_story_5004_50041901_41_dialog_content = "O que, os Eclipsitas estão se aproximando?",
  ui_story_5004_50041901_42_dialog_content = "Não temos condições de defender Petyaburg. Precisamos pedir ajuda a Lumópolis.",
  ui_story_5004_50041901_43_dialog_content = "Os Salar de Lumópolis concordaram em ajudar, mas com uma condição...",
  ui_story_5004_50041901_44_dialog_content = "Querem examinar a magia de ritual da nossa filha e adotá-la como sua linhagem familiar, se adequada.",
  ui_story_5004_50041901_45_dialog_content = "Pode ser algo bom ter uma conexão sólida com uma família tão poderosa. Isso só beneficiaria os Vronskys.",
  ui_story_5004_50041901_46_dialog_content = "Genevieve.",
  ui_story_5004_50041901_47_dialog_content = "Eu entendo, pai.",
  ui_story_5004_50041901_48_dialog_content = "Você é muito poderosa, Genevieve.",
  ui_story_5004_50041901_49_dialog_content = "Você pode ir ao encontro do Ancião após o teste.",
  ui_story_5004_50041901_50_dialog_content = "Eu agradeço.",
  ui_story_5004_50041901_51_dialog_content = "Ei!",
  ui_story_5004_50041901_52_dialog_content = "Smokey? O que faz aqui?",
  ui_story_5004_50041901_53_dialog_content = "Fiquei sabendo que vai ter algum tipo de teste, então eu vim!",
  ui_story_5004_50041901_54_dialog_content = "Então, só preciso acertar o alvo usando Luminática, certo?",
  ui_story_5004_50041901_55_dialog_content = "Nossa, que...",
  ui_story_5004_50041901_56_dialog_content = "Poder incrível! Como isso é possível numa garota tão jovem?",
  ui_story_5004_50041901_57_dialog_content = "Qual é o seu nome? A que família pertence?",
  ui_story_5004_50041901_58_dialog_content = "Vou ganhar um prêmio? Não quero o habitual, tá sabendo.",
  ui_story_5004_50041901_59_dialog_content = "Prestem atenção, sou Smokey dos Manticora!",
  ui_story_5004_50041901_60_dialog_content = "Smokey dos Manticora...",
  ui_story_5004_50041901_61_dialog_content = "Há mais algum evento ou é apenas este?",
  ui_story_5004_50041901_62_dialog_content = "Por favor espere, o ancião gostaria de falar com você.",
  ui_story_5004_50041901_63_dialog_content = "Não posso esperar, ainda preciso comprar roupas.",
  ui_story_5004_50041901_64_dialog_content = "Você vem comigo, Genev?",
  ui_story_5004_50041901_65_dialog_content = "Mas por que...",
  ui_story_5004_50041901_66_dialog_content = "Ouça, Genevieve...",
  ui_story_5004_50041901_67_dialog_content = "Você perdeu a oportunidade da sua vida.",
  ui_story_5004_50041901_68_dialog_content = "Tudo bem, os Salar ainda estão dispostos a defender Petyaburg.",
  ui_story_5004_50041901_69_dialog_content = "Mas perdemos a chance de uma aliança.",
  ui_story_5004_50041901_70_dialog_content = "Você já pode ir.",
  ui_story_5004_50041901_71_dialog_content = "Sinto muito, pai.",
  ui_story_5004_50041901_72_dialog_content = "(Por que você tinha que aparecer, Smokey?)",
  ui_story_5004_50041901_73_dialog_content = "(Você só queria competir? Para me vencer? Ou...)",
  ui_story_5004_50041901_74_dialog_content = "Genevieve!",
  ui_story_5004_50041901_75_dialog_content = "O que foi, mãe?",
  ui_story_5004_50041901_76_dialog_content = "Ficou sabendo?",
  ui_story_5004_50041901_77_dialog_content = "Os Salar fizeram um acordo com os Manticora...",
  ui_story_5004_50041901_78_dialog_content = "Tó sabendo. É uma proposta de casamento.",
  ui_story_5004_50041901_79_dialog_content = "Mas a tal garota Smokey saiu sem deixar rastro!",
  ui_story_5004_50041901_80_dialog_content = "O quê?",
  ui_story_5004_50041901_81_dialog_content = "Smokey fugiu?",
  ui_story_5004_50041901_82_dialog_content = "Droga, não devíamos ter dado uma chance a aqueles caipiras de Petyaburg!",
  ui_story_5004_50041901_83_dialog_content = "Que desperdício de tempo. A única vantagem é que não precisamos mais ir para a periferia.",
  ui_story_5004_50041901_84_dialog_content = "Ouçam! Segundo o ancião, Petyaburg não precisa mais da proteção de Lumópolis! Podem dar meia volta e partir!",
  ui_story_5004_50041901_85_dialog_content = "E assim, a já desafortunada Petyaburg decaiu ainda mais.",
  ui_story_5004_50041901_86_dialog_content = "Minha mãe faleceu após um acidente e meu pai adoeceu.",
  ui_story_5004_50041901_87_dialog_content = "Genevieve...",
  ui_story_5004_50041901_88_dialog_content = "Estou aqui, pai.",
  ui_story_5004_50041901_89_dialog_content = "A família que você jurou defender está chegando ao fim...",
  ui_story_5004_50041901_90_dialog_content = "Está chateada ou aliviada? Já planejou o que fará a seguir?",
  ui_story_5004_50041901_91_dialog_content = "Não sei, pai... Tudo aconteceu tão depressa que ainda não entendi direito.",
  ui_story_5004_50041901_92_dialog_content = "Pobre criança...",
  ui_story_5004_50041901_93_dialog_content = "...",
  ui_story_5004_50041901_94_dialog_content = "Não imaginei que também perderia você, Anna.",
  ui_story_5004_50041901_95_dialog_content = "Relincho...",
  ui_story_5004_50041901_96_dialog_content = "Essa égua é sua, mocinha?",
  ui_story_5004_50041901_97_dialog_content = "Sim.",
  ui_story_5004_50041901_98_dialog_content = "Posso salvá-la, mas você deve...",
  ui_story_5004_50041901_99_dialog_content = "Eu farei qualquer coisa! Preciso da Anna! Preciso dela para encontrar alguém!",
  ui_story_5004_50041901_100_dialog_content = "Smokey...",
  ui_story_5004_50041901_100X1_dialog_content = "Ora, se não é a Genevieve?",
  ui_story_5004_50041901_100X2_dialog_content = "Já sabe quem sou, então vá direto ao assunto. Não tenho tempo para conversa fiada.",
  ui_story_5004_50041901_100X3_dialog_content = "Ah, mas isso vai te interessar. É sobre Smokey.",
  ui_story_5004_50041901_100X4_dialog_content = "!!",
  ui_story_5004_50041901_100X5_dialog_content = "Você conhece Smokey?",
  ui_story_5004_50041901_100X6_dialog_content = "É claro. Até sei que ela está na Costa Celestial...",
  ui_story_5004_50041901_100X7_dialog_content = "Ei, não saia, ainda não terminei!",
  ui_story_5004_50041901_102_dialog_content = "Senhorita Genevieve.",
  ui_story_5004_50041901_103_dialog_content = "Senhorita Genevieve!",
  ui_story_5004_50041901_104_dialog_content = "Sim.",
  ui_story_5004_50041901_105_dialog_content = "Já preparamos tudo conforme suas instruções.",
  ui_story_5004_50041901_106_dialog_content = "Certo, será um confronto individual.",
  ui_story_5004_50041901_107_dialog_content = "Vou derrotar... não, vencerei vocês com meu canto!",
  ui_story_5004_50042001_1_dialog_content = "Que palco incrível. É uma criação do Fleur?",
  ui_story_5004_50042001_2_dialog_content = "Considerando a decoração tipo Rediesel Wrench, provavelmente.",
  ui_story_5004_50042001_3_dialog_content = "Ele é tão versátil.",
  ui_story_5004_50042001_4_dialog_content = "Não vai participar, PlayerName?",
  ui_story_5004_50042001_5_dialog_content = "Vou ficar de fora dessa. Cantar não é o meu forte.",
  ui_story_5004_50042001_6_dialog_content = "E não... curto... multidões.",
  ui_story_5004_50042001_7_dialog_content = "Eu também não. Vim assistir a Beryl.",
  ui_story_5004_50042001_8_dialog_content = "Sim, Raphaela e eu vamos torcer para valer por você!",
  ui_story_5004_50042001_9_dialog_content = "Deixa a torcida comigo! Vou mandar mísseis pra todo lado!",
  ui_story_5004_50042001_10_dialog_content = "Não, por favor!",
  ui_story_5004_50042001_11_dialog_content = "Tudo bem, você cuida disso então!",
  ui_story_5004_50042001_12_dialog_content = "Prepare-se para curtir nosso show e e torcer por nós!",
  ui_story_5004_50042001_13_dialog_content = "Ai vamos nós, a última competição do Monarca do Oceano, um concurso de inteligência e beleza. AO VIVO da praia!",
  ui_story_5004_50042001_14_dialog_content = "Com o aumento de patrocinadores, podemos convidar dois Astros importantes como jurados!",
  ui_story_5004_50042001_15_dialog_content = "O anônimo Sr. M de Lumópolis!",
  ui_story_5004_50042001_16_dialog_content = "Aham.",
  ui_story_5004_50042001_17_dialog_content = "E o anônimo Sr. Y de Umbraton!",
  ui_story_5004_50042001_18_dialog_content = "E ai pessoal.",
  ui_story_5004_50042001_19_dialog_content = "Bonacie convidou dois jurados. Ei, por que me parecem familiares?",
  ui_story_5004_50042001_20_dialog_content = "Os jurados e a plateia ao vivo escolherão o vencedor!",
  ui_story_5004_50042001_21_dialog_content = "O primeiro concorrente...",
  ui_story_5004_50042001_22_dialog_content = "é um vocalista de heavy metal mascarado do inferno...",
  ui_story_5004_50042001_23_dialog_content = "Meu nome é Magrela Sorrateiro, um cantor misterioso de Umbraton!",
  ui_story_5004_50042001_24_dialog_content = "Não é o Seleucid? O nome e o elmo praticamente revelam a identidade!",
  ui_story_5004_50042001_25_dialog_content = "Agora, vou rugir das profundezas da minha alma!",
  ui_story_5004_50042001_26_dialog_content = "E apresentar o show de heavy metal mais pesado de todos os tempos!",
  ui_story_5004_50042001_27_dialog_content = "Sai do palco!",
  ui_story_5004_50042001_28_dialog_content = "Sai, cai fora!",
  ui_story_5004_50042001_29_dialog_content = "Com vocês, trajes de banho AO VIVO!",
  ui_story_5004_50042001_30_dialog_content = "Por que não estão usando trajes de banho?",
  ui_story_5004_50042001_31_dialog_content = "Propaganda enganosa! Fraude!",
  ui_story_5004_50042001_32_dialog_content = "Vim ver garotas em trajes de banho! Quero minha grana de volta!",
  ui_story_5004_50042001_33_dialog_content = "Que constrangedor... Ainda bem que não usei meu nome de verdade.",
  ui_story_5004_50042001_34_dialog_content = "Bem, acho que nos veremos de novo algum dia!",
  ui_story_5004_50042001_35_dialog_content = "Já acabou? Tão cedo...",
  ui_story_5004_50042001_36_dialog_content = "Que pena, aquele cara com máscara de gato parece cantar bem...",
  ui_story_5004_50042001_37_dialog_content = "Não se deixe enganar pela aparência, Beryl.",
  ui_story_5004_50042001_38_dialog_content = "Mas fez uma boa apresentação, grande Seleucid.",
  ui_story_5004_50042001_39_dialog_content = "Ele baixou tanto a expectativa que a pontuação das meninas certamente será mais alta!",
  ui_story_5004_50042001_40_dialog_content = "Na sequência é... Fleur e Brock?",
  ui_story_5004_50042001_41_dialog_content = "<color=#e8d9bb>Brock se curva para a plateia, vira e estende o braço...</color>",
  ui_story_5004_50042001_42_dialog_content = "Ahhhh!",
  ui_story_5004_50042001_43_dialog_content = "Ahhhh!",
  ui_story_5004_50042001_44_dialog_content = "Você viu isso? Fleur sorriu pra mim!",
  ui_story_5004_50042001_45_dialog_content = "Seu olhar atingiu meu coração, Fleury! Está ardendo de amor!",
  ui_story_5004_50042001_46_dialog_content = "Quá, quá!",
  ui_story_5004_50042001_47_dialog_content = "E ai vem as gaivotas! Não deviam estar pegando peixes?",
  ui_story_5004_50042001_48_dialog_content = "Vamos mesmo fazer isso?",
  ui_story_5004_50042001_49_dialog_content = "Claro, meu querido amigo!",
  ui_story_5004_50042001_50_dialog_content = "Por que Brock está puxando uma barra de aço?!",
  ui_story_5004_50042001_51_dialog_content = "Espera ai. Ele não vai tentar aquele truque de mágica, né?",
  ui_story_5004_50042001_52_dialog_content = "Será que o mais estúpido da Rediesel Wrench consegue puxá-la?",
  ui_story_5004_50042001_53_dialog_content = "Boa!",
  ui_story_5004_50042001_54_dialog_content = "<color=#e8d9bb>A barra de aço rasga a cortina e perfura a caixa, até a ponta sair do outro lado</color>.",
  ui_story_5004_50042001_55_dialog_content = "Fleur!",
  ui_story_5004_50042001_56_dialog_content = "A caixa está oscilando...",
  ui_story_5004_50042001_57_dialog_content = "Fleur está bem? Não me parece nada bem...",
  ui_story_5004_50042001_58_dialog_content = "Relaxa, vou cuidar dele.",
  ui_story_5004_50042001_59_dialog_content = "Ninguém vai morrer, certo?",
  ui_story_5004_50042001_60_dialog_content = "(Brock está rezando baixinho?)",
  ui_story_5004_50042001_61_dialog_content = "A caixa parou de se mexer... Raphaela!",
  ui_story_5004_50042001_62_dialog_content = "Certo, se prepare para atirar!",
  ui_story_5004_50042001_63_dialog_content = "Espere aí!",
  ui_story_5004_50042001_64_dialog_content = "Yu-huuu!",
  ui_story_5004_50042001_65_dialog_content = "Caramba, isso é inacreditável!",
  ui_story_5004_50042001_66_dialog_content = "Maravilha...",
  ui_story_5004_50042001_67_dialog_content = "Não, é desperdício de energia. Eu já ia atirar!",
  ui_story_5004_50042001_68_dialog_content = "Atirar? Com seus mísseis? Como isso é auxílio médico?",
  ui_story_5004_50042001_69_dialog_content = "Mas todos parecem estar gostando da apresentação e aplaudindo.",
  ui_story_5004_50042001_70_dialog_content = "Acho que por isso Fleur ainda tá vivo.",
  ui_story_5004_50042001_71_dialog_content = "Espera, tenho certeza de que afirmei que só é permitido cantar no concurso, não?",
  ui_story_5004_50042001_72_dialog_content = "Não é bom violar as regras, Brock e Fleur. Especialmente quando vocês as conhecem, não?",
  ui_story_5004_50042001_73_dialog_content = "Haha, desculpa. Só queremos levar alegria pro público e deixar todo mundo mais empolgado.",
  ui_story_5004_50042001_74_dialog_content = "Mas eu não sei cantar, então pensei em fazer isso.",
  ui_story_5004_50042001_75_dialog_content = "Quem é essa mulher pra dizer o que o Fleur deve fazer!",
  ui_story_5004_50042001_76_dialog_content = "Fleur! A gente te ama!",
  ui_story_5004_50042001_77_dialog_content = "(Não é ruim isso virar um show de talentos.)",
  ui_story_5004_50042001_78_dialog_content = "(Mas é uma pena o Seleucid ter desistido cedo.)",
  ui_story_5004_50042001_79_dialog_content = "(Porém, com a sua máscara de gato, ele combina mais com shows de cantores mascarados.)",
  ui_story_5004_50042001_80_dialog_content = "Regras são regras. Por meio deste, eu desqualifico o Fleur.",
  ui_story_5004_50042001_81_dialog_content = "Por que só pode cantar?",
  ui_story_5004_50042001_82_dialog_content = "Você está sempre convidado pra se apresentar nos nossos salões, Fleur!",
  ui_story_5004_50042001_83_dialog_content = "Au, au!",
  ui_story_5004_50042001_84_dialog_content = "Miau!",
  ui_story_5004_50042001_85_dialog_content = "E aí vêm os animais! A característica especial do Fleur é tão assustadora...",
  ui_story_5004_50042001_86_dialog_content = "Candidato Número Oito!",
  ui_story_5004_50042001_87_dialog_content = "Genevieve Vronsky!",
  ui_story_5004_50042001_88_dialog_content = "Hum, esse é o nível de competidor que estou enfrentando.",
  ui_story_5004_50042001_89_dialog_content = "Vou aproveitar a chance para impressionar os jurados e o público, e conseguir a maior nota!",
  ui_story_5004_50042001_90_dialog_content = "(Mais competidores bizarros...)",
  ui_story_5004_50042001_91_dialog_content = "(Já é a vez da Vice?)",
  ui_story_5004_50042001_92_dialog_content = "Agora é a Genevieve, PlayerName.",
  ui_story_5004_50042001_93_dialog_content = "É, ela é provavelmente a nossa maior concorrente.",
  ui_story_5004_50042001_94_dialog_content = "Caindo de uma tempestade♪",
  ui_story_5004_50042001_95_dialog_content = "...!!",
  ui_story_5004_50042001_96_dialog_content = "Foi um julgamento impiedoso ou uma salvação libertadora♪",
  ui_story_5004_50042001_97_dialog_content = "Desaparecendo no horizonte remoto♪",
  ui_story_5004_50042001_98_dialog_content = "É a sua figura inescrutável♪",
  ui_story_5004_50042001_99_dialog_content = "Anseios copiosos com o vendaval e a chuva♪",
  ui_story_5004_50042001_100_dialog_content = "Desafiando a vulgaridade♪",
  ui_story_5004_50042001_101_dialog_content = "Abriu o caminho à frente com paixão e impulso♪",
  ui_story_5004_50042001_102_dialog_content = "Fechando os olhos para a suposta guerra♪",
  ui_story_5004_50042001_103_dialog_content = "Isso... foi impressionante.",
  ui_story_5004_50042001_104_dialog_content = "...",
  ui_story_5004_50042001_105_dialog_content = "Ohhhh, Genevieve!",
  ui_story_5004_50042001_106_dialog_content = "Que apresentação emocionante. Todos puderam senti-la.",
  ui_story_5004_50042001_107_dialog_content = "A voz da Genevieve vai direto pro meu coração. Espero que ela faça um show em Umbraton um dia.",
  ui_story_5004_50042001_108_dialog_content = "Temos os resultados. A nota final de Genevieve é 9,6!",
  ui_story_5004_50042001_109_dialog_content = "Parabéns, essa foi uma nota muito alta, não?",
  ui_story_5004_50042001_110_dialog_content = "Obrigado pela apresentação, Genevieve.",
  ui_story_5004_50042001_111_dialog_content = "Então, você viu aquilo, Smokey?",
  ui_story_5004_50042001_112_dialog_content = "Impressionante...",
  ui_story_5004_50042001_113_dialog_content = "Ela cantou com muita emoção.",
  ui_story_5004_50042001_114_dialog_content = "(A voz da Genevieve é mesmo de outro mundo, ela com certeza conseguiu novos fãs.)",
  ui_story_5004_50042001_115_dialog_content = "(Agora estou preocupado com a Vice...)",
  ui_story_5004_50042001_116_dialog_content = "Agora, teremos o trio de garotas, Beijo da Manticora!",
  ui_story_5004_50042001_117_dialog_content = "É a vez da Vice!",
  ui_story_5004_50042001_118_dialog_content = "Finalmente! Tô ficando nervoso.",
  ui_story_5004_50042001_119_dialog_content = "Eu também!",
  ui_story_5004_50042001_120_dialog_content = "♪—",
  ui_story_5004_50042001_121_dialog_content = "♪ ♩ ♫ ♬",
  ui_story_5004_50042001_122_dialog_content = "Quem sabe onde a garota vai parar hoje♪",
  ui_story_5004_50042001_123_dialog_content = "Vagando pela costa sob a luz do farol pela noite♪",
  ui_story_5004_50042001_124_dialog_content = "Oh!",
  ui_story_5004_50042001_125_dialog_content = "Viva, viva, viva!",
  ui_story_5004_50042001_126_dialog_content = "(Uau, até os fãs da Genevieve estão torcendo e batendo palma feito loucos.)",
  ui_story_5004_50042001_127_dialog_content = "O aroma das marés se move pela praia sob as estrelas♪",
  ui_story_5004_50042001_128_dialog_content = "Acolhendo e nutrindo as flores numa determinação silenciosa♪",
  ui_story_5004_50042001_129_dialog_content = "Resolvendo superar a água que sobe para a vitória final♪",
  ui_story_5004_50042001_130_dialog_content = "Carleen! Pequena Vice! Pequena Smokey! Vocês são demais!",
  ui_story_5004_50042001_131_dialog_content = "Pega na minha mão e acena pra elas comigo, Beryl!",
  ui_story_5004_50042001_132_dialog_content = "Claro!",
  ui_story_5004_50042001_133_dialog_content = "Capture o brilho com orgulho inquebrável♪",
  ui_story_5004_50042001_134_dialog_content = "Sinta o rugido do coração prestes a explodir♪",
  ui_story_5004_50042001_135_dialog_content = "Batendo intensamente♪",
  ui_story_5004_50042001_136_dialog_content = "Com olhos brilhantes e impulso desenfreado em direção ao verdadeiro destino♪",
  ui_story_5004_50042001_137_dialog_content = "Sempre em frente♪",
  ui_story_5004_50042001_138_dialog_content = "Até o topo do mundo♪",
  ui_story_5004_50042001_139_dialog_content = "<color=#e8d9bb>Com o microfone em uma das mãos, Smokey faz uma pistola com a outra e um gesto de atirar para Genevieve, terminando a música com uma piscadinha.</color>",
  ui_story_5004_50042001_140_dialog_content = "<color=#e8d9bb>O Beijo da Manticora termina com perfeição</color>",
  ui_story_5004_50042001_141_dialog_content = "...",
  ui_story_5004_50042001_142_dialog_content = "(Humm, quando ela chegou aqui?)",
  ui_story_5004_50042001_143_dialog_content = "Nada mal, embora fosse um dueto antes.",
  ui_story_5004_50042001_144_dialog_content = "O quê?",
  ui_story_5004_50042001_145_dialog_content = "(Ela se foi. Ela tava provocando? O que ela quis dizer?)",
  ui_story_5004_50042001_146_dialog_content = "Beijo da Manticora! Beijo da Manticora! Beijo da Manticora!",
  ui_story_5004_50042001_147_dialog_content = "Demais, Beijo da Manticora!",
  ui_story_5004_50042001_148_dialog_content = "Todos amaram a apresentação. Até a Beryl parece emocionada.",
  ui_story_5004_50042001_149_dialog_content = "Você gravou tudo?",
  ui_story_5004_50042001_150_dialog_content = "Sim, Meu L... Senhor!",
  ui_story_5004_50042001_151_dialog_content = "Esse é um grupo divertido.",
  ui_story_5004_50042001_154_dialog_content = "Beijo da Manticora...",
  ui_story_5004_50042001_155_dialog_content = "Consegue um 10 perfeito!",
  ui_story_5004_50042201_1_dialog_content = "Saúde!",
  ui_story_5004_50042201_2_dialog_content = "Ha!",
  ui_story_5004_50042201_3_dialog_content = "Que grande ideia é essa com todo esse suco!",
  ui_story_5004_50042201_4_dialog_content = "Mas você não toma suco?",
  ui_story_5004_50042201_5_dialog_content = "Graças a você, não!",
  ui_story_5004_50042201_6_dialog_content = "Hahaha!",
  ui_story_5004_50042201_7_dialog_content = "Carleen, Vice e Smokey, vocês foram fantásticas!",
  ui_story_5004_50042201_8_dialog_content = "Vocês se moviam no palco como superestrelas!",
  ui_story_5004_50042201_9_dialog_content = "A Beryl se emocionou e até chorou, né?",
  ui_story_5004_50042201_10_dialog_content = "Ah... Sim, foi uma apresentação muito comovente.",
  ui_story_5004_50042201_11_dialog_content = "Suas vozes e movimentos foram cativantes.",
  ui_story_5004_50042201_12_dialog_content = "Um show perfeito, como Beryl acabou de dizer!",
  ui_story_5004_50042201_13_dialog_content = "Qual será o prêmio misterioso?",
  ui_story_5004_50042201_14_dialog_content = "Falando nisso, eu também estou curioso.",
  ui_story_5004_50042201_15_dialog_content = "Eu poderia perguntar pra Bonacie, mas ela sorriria misteriosamente e diria para esperar até amanhã.",
  ui_story_5004_50042201_16_dialog_content = "É, quero muito ver o que é.",
  ui_story_5004_50042201_17_dialog_content = "Espero que seja algum tipo de xarope incrível. Assim, poderemos atrair mais clientes!",
  ui_story_5004_50042201_18_dialog_content = "Talvez eu devesse abrir lojas de raspadinha em Lumópolis!",
  ui_story_5004_50042201_19_dialog_content = "Acho que a Raphaela poderá te perseguir como ambulante sem licença.",
  ui_story_5004_50042201_20_dialog_content = "Hihi, pra Vice, eu darei um minuto de vantagem!",
  ui_story_5004_50042201_21_dialog_content = "Ei, parabéns a todas vocês!",
  ui_story_5004_50042201_22_dialog_content = "Obrigado, Genevieve? Você veio aqui só pra nos dar os parabéns?",
  ui_story_5004_50042201_23_dialog_content = "Claro, sou uma nobre. Hunf.",
  ui_story_5004_50042201_24_dialog_content = "O que você acha que eu sou, uma menininha chorando pela derrota?",
  ui_story_5004_50042201_25_dialog_content = "Você não chora? Você cresceu bastante, Genev. Ela era uma chorona.",
  ui_story_5004_50042201_26_dialog_content = "O quê? Deveria te matar agora!",
  ui_story_5004_50042201_27_dialog_content = "Ok, ok. Vem, senta pra beber com a gente. Vamos deixar isso pra lá?",
  ui_story_5004_50042201_28_dialog_content = "Smokey pega Genevieve pelo braço e a arrasta para o assento ao lado.",
  ui_story_5004_50042201_29X1_dialog_content = "Experimenta esse!",
  ui_story_5004_50042201_29X2_dialog_content = "Tsc, que chatice.",
  ui_story_5004_50042201_29X3_dialog_content = "Esse é...?",
  ui_story_5004_50042201_29X4_dialog_content = "É, não parece aquele daquela safra da taverna de Petyaburg, onde a gente costumava ir?",
  ui_story_5004_50042201_29X5_dialog_content = "No geral, acho que sim. Faz tanto tempo que eu nem me lembro mais.",
  ui_story_5004_50042201_29X6_dialog_content = "Por que esse nome, Beijo da Manticora?",
  ui_story_5004_50042201_29X7_dialog_content = "Como essa bebida, você deveria saber por quê. Não acho que se esqueceria disso.",
  ui_story_5004_50042201_29X8_dialog_content = "...",
  ui_story_5004_50042201_30_dialog_content = "(Que complicadas essas duas.)",
  ui_story_5004_50042201_31_dialog_content = "Gostaria de ver o truque do Fleur de novo.",
  ui_story_5004_50042201_32_dialog_content = "Ainda não entendi como ele fez isso.",
  ui_story_5004_50042201_33_dialog_content = "Claro, eu faria pra todo mundo de novo com prazer.",
  ui_story_5004_50042201_34_dialog_content = "Que tal um lugar mais reservado dessa vez?",
  ui_story_5004_50042201_35_dialog_content = "Tivemos que brigar não só com as pessoas, mas com os gatos e os cachorros só pra sair de lá.",
  ui_story_5004_50042201_36_dialog_content = "E eu te agradeço por isso. Deixa eu tratar das suas feridas mais tarde.",
  ui_story_5004_50042201_37_dialog_content = "O robô também está quase pronto, preciso da sua ajuda.",
  ui_story_5004_50042201_38_dialog_content = "Tudo bem, mas não me interrompa enquanto bebo agora.",
  ui_story_5004_50042201_39_dialog_content = "O robô está quase pronto?",
  ui_story_5004_50042201_40_dialog_content = "O departamento de pesquisa em Illumina precisa de vários meses pra construir um!",
  ui_story_5004_50042201_41_dialog_content = "Tudo graças à Srta. Bonacie. Tive acesso a vários equipamentos e arquivos trabalhando pra ela.",
  ui_story_5004_50042201_42_dialog_content = "A minha criação perfeita, o robô de batalha Nº 1 da Rediesel Wrench...",
  ui_story_5004_50042201_43_dialog_content = "Ficará pronto hoje à noite!",
  ui_story_5004_50042201_44_dialog_content = "(É a primeira vez que vejo Fleur sério assim.)",
  ui_story_5004_50042201_45_dialog_content = "(Fleur deve gostar mesmo de máquinas e robôs.)",
  ui_story_5004_50042201_46_dialog_content = "O que foi isso...?",
  ui_story_5004_50042201_47_dialog_content = "Oh...",
  ui_story_5004_50042201_48_dialog_content = "Você está suando, Beryl!",
  ui_story_5004_50042201_49_dialog_content = "Você pode me levar de volta pro quarto, Raphaela?",
  ui_story_5004_50042201_50_dialog_content = "Beryl não está se sentindo bem, PlayerName. Precisamos ir.",
  ui_story_5004_50042201_51_dialog_content = "Beryl ainda não se recuperou? Ela se esforçou muito da última vez, mas isso já faz vários dias.",
  ui_story_5004_50042201_52_dialog_content = "A sua condição não parece ter melhorado.",
  ui_story_5004_50042201_53_dialog_content = "Talvez seja mais complicado do que pensávamos. Ah, Raphaela falou com você sobre o arquivo no Pyrrhus?",
  ui_story_5004_50042201_54_dialog_content = "Sim, eu enviei um pedido para dar acesso total à Beretta.",
  ui_story_5004_50042201_55_dialog_content = "Se houver alguma informação útil, só podemos contar com eles.",
  ui_story_5004_50042301_1_dialog_content = "Para o ritual ter sucesso...",
  ui_story_5004_50042301_2_dialog_content = "O Celestita precisa retirar o selo do Movimento e tocá-lo.",
  ui_story_5004_50042301_3_dialog_content = "A gloria do Monarca brilhará mais uma vez sobre essa praia e punirá os pomposos Aurorians.",
  ui_story_5004_50042301_4_dialog_content = "Entendido! Por favor, não se preocupe, eu não pouparei esforços.",
  ui_story_5004_50042301_5_dialog_content = "Aqui estou.",
  ui_story_5004_50042301_6_dialog_content = "Você não sabe bater, Bonacie?",
  ui_story_5004_50042301_7_dialog_content = "Pare de perder tempo. O que você quer comigo?",
  ui_story_5004_50042301_8_dialog_content = "O Movimento está prestes a ser desenterrado, e o selo...",
  ui_story_5004_50042301_9_dialog_content = "Eu sei, eu sei, o Celestita precisa removê-lo, certo?",
  ui_story_5004_50042301_10_dialog_content = "Eu farei PlayerName fazer isso.",
  ui_story_5004_50042301_11_dialog_content = "Você não quer saber o que estamos planejando?",
  ui_story_5004_50042301_12_dialog_content = "Não. Só quero pôr minhas mãos no Movimento.",
  ui_story_5004_50042301_13_dialog_content = "E de qualquer forma, qualquer Aurorian daquele grupo poderia acabar com você sem nem suar.",
  ui_story_5004_50042301_14_dialog_content = "Se vocês estão mesmo conspirando, espero que eles pelo menos deixem seus cadáveres intactos.",
  ui_story_5004_50042301_15_dialog_content = "Mas esses esquemas pra ganhar dinheiro são totalmente ridículos, não?",
  ui_story_5004_50042301_16_dialog_content = "Você ainda é o mesmo Aurorian irritante de sempre!",
  ui_story_5004_50042301_17_dialog_content = "Vou te pegar...",
  ui_story_5004_50042301_18_dialog_content = "Por favor, se acalme, Senhor Prinny!",
  ui_story_5004_50042301_19_dialog_content = "O que você está fazendo aqui? Já está na hora de você divulgar as aulas de ioga, não?",
  ui_story_5004_50042301_20_dialog_content = "Deixa pra lá, eu ainda tenho que ver PlayerName. Vocês podem brincar uns com os outros.",
  ui_story_5004_50042301_21_dialog_content = "Espera, só um minuto, Bonacie!",
  ui_story_5004_50042301_22_dialog_content = "Quero que você ouça os novos slogans que escrevi!",
  ui_story_5004_50042301_23_dialog_content = "...",
  ui_story_5004_50042301_24_dialog_content = "Eu deveria manipular o Aurorian, mas eu que fiquei zangado.",
  ui_story_5004_50042301_25_dialog_content = "Sem falar nos lacaios inúteis que priorizam as lições falsas!",
  ui_story_5004_50042301_26_dialog_content = "Ah...",
  ui_story_5004_50042301_35_dialog_content = "Aqui, deite na cama, Beryl!",
  ui_story_5004_50042301_36_dialog_content = "Humm, sua temperatura está alta e você está suando muito... Você deve estar se sentindo muito mal.",
  ui_story_5004_50042301_37_dialog_content = "Eu... eu aguento...",
  ui_story_5004_50042301_38_dialog_content = "Deixa eu pegar uma toalha pra secar seu suor!",
  ui_story_5004_50042301_39_dialog_content = "Tá tudo bem, mas...",
  ui_story_5004_50042301_40_dialog_content = "Você pode se deitar comigo um pouco?",
  ui_story_5004_50042301_41_dialog_content = "Sem problemas!",
  ui_story_5004_50042301_42_dialog_content = "Pobre Beryl, sinto o calor saindo de você. Uma toalha molhada ou uma bolsa de gelo te esfriariam um pouco, tem certeza de que não precisa de uma?",
  ui_story_5004_50042301_43_dialog_content = "Fique... Por favor? Isso deve dar...",
  ui_story_5004_50042301_44_dialog_content = "Amanhã depois da cerimônia, vamos pedir ao PlayerName pra nos levar à Lumópolis com o Soroz.",
  ui_story_5004_50042301_45_dialog_content = "As instalações lá têm uma capacidade melhor pra monitorar o seu estado.",
  ui_story_5004_50042301_46_dialog_content = "E você vai ver que Lumópolis é cheia de pessoas interessantes, Beryl. Eu também posso te apresentar aos outros anjos.",
  ui_story_5004_50042301_47_dialog_content = "Todos eles vão gostar muito de você!",
  ui_story_5004_50042301_48_dialog_content = "Ah, e tem um anjo chamado Uriel. Ela costumava ser desanimada como você, Beryl!",
  ui_story_5004_50042301_49_dialog_content = "Mas como você, ela é muito confiável.",
  ui_story_5004_50042301_50_dialog_content = "Você acha que eu sou confiável?",
  ui_story_5004_50042301_51_dialog_content = "Totalmente! E a cidade tem muitas lojas chiques e vários tipos de restaurantes.",
  ui_story_5004_50042301_52_dialog_content = "Posso te levar pra fazer compras nos meus lugares favoritos!",
  ui_story_5004_50042301_53_dialog_content = "Se você gostar de fazer pão, podemos visitar a padaria onde eu sempre vou!",
  ui_story_5004_50042301_54_dialog_content = "O dono é muito legal e me ensinou a fazer vários doces.",
  ui_story_5004_50042301_55_dialog_content = "Ah, e a Sala de Concertos de Lumópolis! Eles trazem ótimos artistas pra tocar lá, mas os ingressos são difíceis de conseguir...",
  ui_story_5004_50042301_56_dialog_content = "Hum...",
  ui_story_5004_50042301_57_dialog_content = "Sim, Beryl?",
  ui_story_5004_50042301_58_dialog_content = "Eu tenho algo que não sei se deveria te contar...",
  ui_story_5004_50042301_59_dialog_content = "Me conta, me conta!",
  ui_story_5004_50042301_60_dialog_content = "Tenho muito medo...",
  ui_story_5004_50042301_61_dialog_content = "... de não... poder sair daqui.",
  ui_story_5004_50042301_62_dialog_content = "O quê? Como assim?",
  ui_story_5004_50042301_63_dialog_content = "Tenho pesadelos, todas as noites...",
  ui_story_5004_50042301_64_dialog_content = "... Tenho sempre o mesmo sonho, e só foi piorando...",
  ui_story_5004_50042301_65_dialog_content = "Começou comigo só ouvindo uma voz fraca...",
  ui_story_5004_50042301_66_dialog_content = "Ela continuava a falar comigo... me fez lembrar de muitas coisas que eu tinha esquecido...",
  ui_story_5004_50042301_67_dialog_content = "(Do passado da Beryl? Poderá ser sobre os Gautiers e os Pyrrhus?)",
  ui_story_5004_50042301_68_dialog_content = "Ela disse muitas coisas das quais eu não me lembro, e outras de que não quero me lembrar... Tenho medo.",
  ui_story_5004_50042301_69_dialog_content = "A voz acabava repetindo pra mim...",
  ui_story_5004_50042301_70_dialog_content = "Que meu corpo irá ceder e perder o controle, e minha mente cair em uma espiral infinita depois de matar todo mundo.",
  ui_story_5004_50042301_71_dialog_content = "!!",
  ui_story_5004_50042301_72_dialog_content = "Eu me esforcei muito pra tirar esses sonhos da minha cabeça, mas eles não vão embora...",
  ui_story_5004_50042301_73_dialog_content = "E eu posso sentir meu corpo se deteriorando...",
  ui_story_5004_50042301_74_dialog_content = "Ah, Beryl...",
  ui_story_5004_50042301_75_dialog_content = "Você não deveria acreditar em sonhos como esse!",
  ui_story_5004_50042301_76_dialog_content = "Ah...",
  ui_story_5004_50042301_77_dialog_content = "Sonhos são só sonhos. Eles não significam nada.",
  ui_story_5004_50042301_78_dialog_content = "Você não está se sentindo bem, provavelmente por ter feito coisas pra todo mundo nos últimos dois dias, e talvez por causa de tanta emoção.",
  ui_story_5004_50042301_79_dialog_content = "Quanto aos sonhos, vou ver com o PlayerName, talvez as habilidades psíquicas possam ajudar a te esclarecer.",
  ui_story_5004_50042301_80_dialog_content = "Só descansa enquanto eu vou!",
  ui_story_5004_50042301_81_dialog_content = "Me escuta e relaxa. Vamos voltar pra Lumópolis amanhã!",
  ui_story_5004_50042301_82_dialog_content = "OK.",
  ui_story_5004_50042301_83_dialog_content = "Eu já volto, tá bom?",
  ui_story_5004_50042301_84_dialog_content = "Essa foi por pouco...",
  ui_story_5004_50042301_85_dialog_content = "Não posso deixar você voltar tão cedo.",
  ui_story_5004_50042301_86_dialog_content = "O quê? Tem certeza?",
  ui_story_5004_50042301_87_dialog_content = "Sim. Ela quase esbarrou em mim.",
  ui_story_5004_50042301_88_dialog_content = "Se isso for verdade, devo avisar a Rainha.",
  ui_story_5004_50042301_89_dialog_content = "Eu acabei de entregar informações vitais, então quanto ao meu bônus desse mês...",
  ui_story_5004_50042301_90_dialog_content = "Você deve sair agora.",
  ui_story_5004_50042301_91_dialog_content = "Inútil!",
  ui_story_5004_50042301_92_dialog_content = "Por favor, fique calmo.",
  ui_story_5004_50042301_93_dialog_content = "Você sabe o que eu passei pra juntar tudo isso? Agora, por causa de toda a sua incompetência...",
  ui_story_5004_50042301_94_dialog_content = "Eles estão escapando!",
  ui_story_5004_50042301_95_dialog_content = "Sentimos muito!",
  ui_story_5004_50042301_96_dialog_content = "Peões inúteis. Acho que vou ter que fazer isso eu mesmo.",
  ui_story_5004_50042301_97_dialog_content = "Uma pena que essa parte seja a que mais estimo...",
  ui_story_5004_50042301_98_dialog_content = "Hi...",
  ui_story_5004_50042401_1_dialog_content = "Venha comigo um instante, PlayerName!",
  ui_story_5004_50042401_2_dialog_content = "Para de me puxar. Estou discutindo como expandir o negócio da raspadinha com a Vice!",
  ui_story_5004_50042401_3_dialog_content = "Podemos melhorá-lo com o dinheiro que ganharmos amanhã, daí para coisas maiores e melhores!",
  ui_story_5004_50042401_4_dialog_content = "Pare de pensar nessas coisas agora. A pequena Beryl está mal!",
  ui_story_5004_50042401_5_dialog_content = "O que houve com a Beryl?",
  ui_story_5004_50042401_6_dialog_content = "Acho que temos que levá-la de volta imediatamente pra Lumópolis para receber tratamento.",
  ui_story_5004_50042401_7_dialog_content = "É verdade, devemos mesmo voltar, PlayerName.",
  ui_story_5004_50042401_8_dialog_content = "Não se esqueça que viemos pra cá para alegrar a Beryl.",
  ui_story_5004_50042401_9_dialog_content = "Mas se na verdade isso tá fazendo ela piorar, devemos ir embora!",
  ui_story_5004_50042401_10_dialog_content = "Você tem razão. Vamos ver como ela tá agora.",
  ui_story_5004_50042401_11_dialog_content = "Ai, isso machuca! Não enxergo nada, só escuridão...",
  ui_story_5004_50042401_12_dialog_content = "Desculpa! Você tá bem, Bonacie?",
  ui_story_5004_50042401_13_dialog_content = "Ah, devemos partir pra Lumópolis por causa de assuntos urgentes, deixe os prêmios pra próxima!",
  ui_story_5004_50042401_14_dialog_content = "O quê? O que você quer dizer com isso?",
  ui_story_5004_50042401_15_dialog_content = "Santo movimento, por que agora?",
  ui_story_5004_50042401_16_dialog_content = "Tudo bem, estou com todos aqui...",
  ui_story_5004_50042401_17_dialog_content = "Pequena Beryl...?",
  ui_story_5004_50042401_18_dialog_content = "Cadê a Beryl? Pra onde ela foi?",
  ui_story_5004_50042401_19_dialog_content = "Para de me sacudir. Eu não a peguei.",
  ui_story_5004_50042401_20_dialog_content = "Eu falei pra ela ficar quietinha e descansar!",
  ui_story_5004_50042401_21_dialog_content = "Rápido, pensa em alguma coisa. É perigoso pra ela ficar correndo doente por aí!",
  ui_story_5004_50042401_22_dialog_content = "PlayerName! PlayerName!",
  ui_story_5004_50042401_23_dialog_content = "Use as suas habilidades psíquicas e ajude a Raphaela, PlayerName!",
  ui_story_5004_50042401_24_dialog_content = "Tá bom, tá bom... Mas eu não posso fazer isso com você me sacudindo.",
  ui_story_5004_50042401_25_dialog_content = "Se acalma e larga o PlayerName, Raphaela.",
  ui_story_5004_50042401_26_dialog_content = "Nossa...",
  ui_story_5004_50042401_27_dialog_content = "Não está no hotel.",
  ui_story_5004_50042401_28_dialog_content = "Mas eu ainda consigo seguir o seu rastro.",
  ui_story_5004_50042401_29_dialog_content = "Ela parece estar indo em direção ao penhasco onde a estátua de pedra está.",
  ui_story_5004_50042401_30_dialog_content = "Faça todo mundo procurar pela Beryl também, PlayerName.",
  ui_story_5004_50042401_31_dialog_content = "Todo mundo? Isso é mesmo necessário?",
  ui_story_5004_50042401_32_dialog_content = "As férias devem ter te deixado burro, PlayerName.",
  ui_story_5004_50042401_33_dialog_content = "O hotel é mais seguro, por causa de todas as medidas de segurança.",
  ui_story_5004_50042401_34_dialog_content = "Mas você não se lembra das hordas de Eclipsitas que encontramos no caminho até lá?",
  ui_story_5004_50042401_35_dialog_content = "E se por acaso a Beryl encontrar algo parecido?",
  ui_story_5004_50042401_36_dialog_content = "É verdade...",
  ui_story_5004_50042401_37_dialog_content = "Certo, vamos fazer todos ajudarem!",
  ui_story_5004_50042401_38_dialog_content = "Obrigado a todos por terem vindo... até Genevieve está aqui.",
  ui_story_5004_50042401_39_dialog_content = "Somos amigos agora, e os amigos devem se ajudar.",
  ui_story_5004_50042401_40_dialog_content = "Na verdade, ela é gentil, apesar de sua personalidade agressiva.",
  ui_story_5004_50042401_41_dialog_content = "O quê? Eu vim porque não quero perder a chance de te fazer passar vergonha.",
  ui_story_5004_50042401_42_dialog_content = "Espero que vocês dois possam resolver as suas diferenças. Enquanto isso, temos que achar a Beryl!",
  ui_story_5004_50042401_43_dialog_content = "Tem certeza de que é por aqui, PlayerName? A floresta parece assustadora.",
  ui_story_5004_50042401_44_dialog_content = "Sim, Beryl foi por aqui.",
  ui_story_5004_50042401_45_dialog_content = "Mas parece que estamos andando em círculos, e é completamente diferente durante o dia.",
  ui_story_5004_50042401_46_dialog_content = "(A passagem parece mesmo não ter fim, e quem sabe quais criaturas estão fazendo esses barulhos assustadores...)",
  ui_story_5004_50042401_47_dialog_content = "Espera, eu ouvi alguma coisa.",
  ui_story_5004_50042401_48_dialog_content = "Ei!",
  ui_story_5004_50042401_49_dialog_content = "Nossa!",
  ui_story_5004_50042401_50_dialog_content = "Bonacie? O que você tá fazendo aqui?",
  ui_story_5004_50042401_51_dialog_content = "Você não disse que tava indo embora? Tô tentando levar o <color=#FFB400>grande prêmio</color> pra você assim que der.",
  ui_story_5004_50042401_52_dialog_content = "O que todos vocês estão fazendo aqui?",
  ui_story_5004_50042401_53_dialog_content = "Estão atrás de uma última aventura antes de voltar?",
  ui_story_5004_50042401_54_dialog_content = "Posso ir com vocês?",
  ui_story_5004_50042401_55_dialog_content = "Não, não é uma aventura!",
  ui_story_5004_50042401_56_dialog_content = "Beryl sumiu. Queremos voltar, porque o seu estado está piorando.",
  ui_story_5004_50042401_57_dialog_content = "Raphaela tá preocupada com isso, ou com a chance dela encontrar Eclipsitas.",
  ui_story_5004_50042401_58_dialog_content = "Já que é a Beryl, como membro da True Order eu devo insistir em me juntar a vocês.",
  ui_story_5004_50042401_59_dialog_content = "Mas esse é um lugar muito perigoso. Há mais mal aqui do que só Eclipsitas!",
  ui_story_5004_50042401_60_dialog_content = "Não é uma aventura, então para com os avisos!",
  ui_story_5004_50042401_61_dialog_content = "Eu posso sentir a Beryl no topo do penhasco... e ela está parada.",
  ui_story_5004_50042401_62_dialog_content = "Mas ainda não conseguimos sair da floresta...",
  ui_story_5004_50042401_63_dialog_content = "Já que é pela Beryl, eu irei guiá-los para fora daqui. Me sigam.",
  ui_story_5004_50042401_64_dialog_content = "Beryl!",
  ui_story_5004_50042401_65_dialog_content = "Nem mais um passo...!",
  ui_story_5004_50042401_66_dialog_content = "Pare de ir pra frente, é perigoso aí!",
  ui_story_5004_50042401_67_dialog_content = "Eu sei que é, então nem mais um passo...",
  ui_story_5004_50042401_68_dialog_content = "Calma, Beryl. Nos conte por que você quis vir aqui.",
  ui_story_5004_50042401_69_dialog_content = "Eu... também não tenho certeza...",
  ui_story_5004_50042401_70_dialog_content = "Depois que a Raphaela foi embora, eu caí na cama, completamente esgotada...",
  ui_story_5004_50042401_71_dialog_content = "Mas percebi que não conseguia me mexer...",
  ui_story_5004_50042401_72_dialog_content = "Então, um braço escuro enrolou-se no meu pescoço e cobriu os meus olhos.",
  ui_story_5004_50042401_73_dialog_content = "Riu terrivelmente nos meus ouvidos e eu desmaiei...",
  ui_story_5004_50042401_74_dialog_content = "É a mesma voz que você ouviu nos seus sonhos?",
  ui_story_5004_50042401_75_dialog_content = "Sim...",
  ui_story_5004_50042401_76_dialog_content = "Não sei o que estou fazendo aqui...",
  ui_story_5004_50042401_77_dialog_content = "Ou o que vai ser de mim...",
  ui_story_5004_50042401_78_dialog_content = "Se a voz diz a verdade... que eu vou matar todos vocês...",
  ui_story_5004_50042401_79_dialog_content = "Mas são só pesadelos!",
  ui_story_5004_50042401_80_dialog_content = "Mesmo assim, eles me trouxeram aqui!",
  ui_story_5004_50042401_81_dialog_content = "Não quero que mais ninguém morra pelas minhas mãos!",
  ui_story_5004_50042401_82_dialog_content = "Para com essa conversa louca!",
  ui_story_5004_50042401_83_dialog_content = "...",
  ui_story_5004_50042401_84_dialog_content = "Você vai ficar bem! Você não é uma das Guerreiras da Praia agora?",
  ui_story_5004_50042401_85_dialog_content = "(Como isso vai ajudar?)",
  ui_story_5004_50042401_86_dialog_content = "Raphaela...",
  ui_story_5004_50042401_87_dialog_content = "A gente não prometeu ir juntas pra Lumópolis?",
  ui_story_5004_50042401_88_dialog_content = "Espere...",
  ui_story_5004_50042401_89_dialog_content = "Volte. É perigoso aí.",
  ui_story_5004_50042401_90_dialog_content = "Os cristais estão piscando sem parar... Eu não gosto disso.",
  ui_story_5004_50042401_91_dialog_content = "Cuidado, os cristais vão explodir!",
  ui_story_5004_50042401_92_dialog_content = "Cuidado, PlayerName!",
  ui_story_5004_50042401_93_dialog_content = "Pequena Beryl!",
  ui_story_5004_50042401_95_dialog_content = "...!",
  ui_story_5004_50042401_96_dialog_content = "Beryl!",
  ui_story_5004_50042401_97_dialog_content = "Raphaela?",
  ui_story_5004_50042401_98_dialog_content = "Segura a minha mão!",
  ui_story_5004_50042401_99_dialog_content = "Tá bom...!",
  ui_story_5004_50042401_100_dialog_content = "Desculpa... Isso tudo é minha culpa...",
  ui_story_5004_50042401_101_dialog_content = "Mesmo para um Anjo da Guarda como você, Raphaela... Você não sobreviveria a uma queda dessa altura.",
  ui_story_5004_50042401_102_dialog_content = "Quero ver Lumópolis... com você...",
  ui_story_5004_50042401_103_dialog_content = "<size=45>O QUE VOCÊ DISSE?</size>",
  ui_story_5004_50042401_104_dialog_content = "Ver Lumópolis... com você?",
  ui_story_5004_50042401_105_dialog_content = "<size=45>NÃO, ANTES DISSO!</size>",
  ui_story_5004_50042401_106_dialog_content = "Mesmo para um Anjo da Guarda como você...?",
  ui_story_5004_50042401_107_dialog_content = "Disparar todos os mísseis... Grrr... Pilar da Bênção pronto... Potência máxima!",
  ui_story_5004_50042401_108_dialog_content = "<size=45>ANJOS PODEM VOAR, BERYL!</size>",
  ui_story_5004_50042401_109_dialog_content = "Aguenta firme, Beryl! Estamos quase sem energia!",
  ui_story_5004_50042401_110_dialog_content = "Me solte, Raphaela! Ele não consegue segurar nós duas. Nós vamos...",
  ui_story_5004_50042401_111_dialog_content = "Para!",
  ui_story_5004_50042401_112_dialog_content = "Eu nunca, nunca vou te soltar!",
  ui_story_5004_50042401_113_dialog_content = "<color=#e8d9bb>Clac, clac!</color>",
  ui_story_5004_50042401_114_dialog_content = "(Quase no limite?)",
  ui_story_5004_50042401_115_dialog_content = "<size=50><color=#e8d9bb>BUM!</color></size>",
  ui_story_5004_50042401_116_dialog_content = "Acorda, Raphaela, acorda...",
  ui_story_5004_50042401_117_dialog_content = "Beryl...",
  ui_story_5004_50042401_118_dialog_content = "Você tá bem, Beryl?",
  ui_story_5004_50042401_119_dialog_content = "Estou bem...",
  ui_story_5004_50042401_120_dialog_content = "Obrigada...",
  ui_story_5004_50042401_121_dialog_content = "Fico feliz em ver que você tá bem. Você se saiu bem.",
  ui_story_5004_50042401_123_dialog_content = "Agora vamos esperar até PlayerName vir nos buscar.",
  ui_story_5004_50042401_124_dialog_content = "Hã, Raphaela, isso são...?",
  ui_story_5004_50042401_125_dialog_content = "Grrrr!",
  ui_story_5004_50042401_126_dialog_content = "Gah... Gah...!",
  ui_story_5004_50042401_127_dialog_content = "Eclipsitas... e são muitos.",
  ui_story_5004_50042401_128_dialog_content = "Você ainda consegue lutar, Beryl?",
  ui_story_5004_50042401_129_dialog_content = "Sim!",
  ui_story_5004_50042401_130_dialog_content = "(Melhor você chegar logo, PlayerName...)",
  ui_story_5004_50042501_1_dialog_content = "Nos leve até o fundo, Bonacie!",
  ui_story_5004_50042501_2_dialog_content = "Deixa comigo. Por aqui, e fiquem perto se não quiserem que os monstros peguem vocês, certo?",
  ui_story_5004_50042501_2X1_dialog_content = "Precisamos conseguir o Movimento o mais rápido possível para Bonacie.",
  ui_story_5004_50042501_2X2_dialog_content = "Então, a faremos levar o Celestita para tirar o selo, e ao tocá-lo, despertaremos o Monarca Desolado.",
  ui_story_5004_50042501_2X3_dialog_content = "Senhor Prinny, passamos por todas as dificuldades para receber o Monarca do Oceano e drenar a energia dos Aurorians.",
  ui_story_5004_50042501_2X4_dialog_content = "E agora precisamos enganar o Celestita para remover o selo, e então fazer Bonacie tocar a melodia...",
  ui_story_5004_50042501_2X5_dialog_content = "Tem certeza de que isso despertará o tal Monarca? O que ganhamos com isso?",
  ui_story_5004_50042501_2X6_dialog_content = "Essa é uma ordem de um dos Oito Espectros. Ouvi dizer que o Monarca é um Eclipsita incrivelmente poderoso.",
  ui_story_5004_50042501_2X7_dialog_content = "Se for despertado, com certeza poderemos nos livrar desses Aurorians irritantes!",
  ui_story_5004_50042501_2X8_dialog_content = "Espero que sim. Está muito escuro... Ei, por que você parou de repente?",
  ui_story_5004_50042501_2X9_dialog_content = "Ouço sons de batalha. Vamos nos esconder!",
  ui_story_5004_50042501_3_dialog_content = "Ficaremos bem escondidos aqui.",
  ui_story_5004_50042501_4_dialog_content = "Não esperava encontrar uma caverna, mas tá escuro...",
  ui_story_5004_50042501_5_dialog_content = "Grrrr!",
  ui_story_5004_50042501_6_dialog_content = "Argh, esses Eclipsitas chatos não têm fim?",
  ui_story_5004_50042501_7_dialog_content = "Como você está, Beryl?",
  ui_story_5004_50042501_8_dialog_content = "Arf, arf... Eu tô bem... Ainda posso lutar...",
  ui_story_5004_50042501_10_dialog_content = "Gah!",
  ui_story_5004_50042501_11_dialog_content = "*Rugido*",
  ui_story_5004_50042501_12_dialog_content = "Droga, eles bloquearam nosso caminho de volta!",
  ui_story_5004_50042501_13_dialog_content = "Escória irritante!",
  ui_story_5004_50042501_14_dialog_content = "Raphaela, Beryl!",
  ui_story_5004_50042501_15_dialog_content = "Vocês estão bem?",
  ui_story_5004_50042501_16_dialog_content = "Você é devagar demais, PlayerName!",
  ui_story_5004_50042501_17_dialog_content = "Como você pode deixar damas esperando tanto assim?",
  ui_story_5004_50042501_18_dialog_content = "Desculpa. Por que não descontamos nos Eclipsitas?",
  ui_story_5004_50042601_1_dialog_content = "Ufa, quase acabou.",
  ui_story_5004_50042601_2_dialog_content = "Raphaela, Beryl, vocês estão feridas?",
  ui_story_5004_50042601_3_dialog_content = "Estamos bem. A pequena Beryl não vai se machucar enquanto eu estiver por perto!",
  ui_story_5004_50042601_4_dialog_content = "É... a Raphaela tava me protegendo...",
  ui_story_5004_50042601_5_dialog_content = "Já que tá tudo bem, vamos voltar pro hotel.",
  ui_story_5004_50042601_6_dialog_content = "Raphaela, eu e outros Aurorians na Colossus vamos ajudar a resolver os pesadelos da Beryl.",
  ui_story_5004_50042601_7_dialog_content = "Isso mesmo. Genevieve sabe de tudo, ela com certeza vai ajudar.",
  ui_story_5004_50042601_8_dialog_content = "Ei, por que eu? Eu só tô aqui pra ajudar na luta.",
  ui_story_5004_50042601_9_dialog_content = "Então tá. Eu conheço um especialista em minerais muito bom. Vou perguntar pra ele.",
  ui_story_5004_50042601_10_dialog_content = "Então, vamos voltar e partir pra Lumópolis.",
  ui_story_5004_50042601_11_dialog_content = "Você poderia nos guiar de volta, Bonacie?",
  ui_story_5004_50042601_12_dialog_content = "Bonacie?",
  ui_story_5004_50042601_13_dialog_content = "Espera um minuto. Acho que encontrei um botão.",
  ui_story_5004_50042601_14_dialog_content = "Hehe.",
  ui_story_5004_50042601_15_dialog_content = "É tão brilhante... O que é esse lugar?",
  ui_story_5004_50042601_16_dialog_content = "(Por que tudo parece tão familiar? Estou vendo coisas?)",
  ui_story_5004_50042601_17_dialog_content = "Ah, não, PlayerName. Nosso caminho de volta está bloqueado!",
  ui_story_5004_50042601_18_dialog_content = "O quê?",
  ui_story_5004_50042601_19_dialog_content = "Não, não consigo movê-lo.",
  ui_story_5004_50042601_20_dialog_content = "Local... Trancado... <size=35>Por favor, reinicie...</size> <size=33>o sistema...</size>",
  ui_story_5004_50042601_21_dialog_content = "...?",
  ui_story_5004_50042601_22_dialog_content = "Todo mundo, vamos ver se conseguimos abrir a porta!",
  ui_story_5004_50042601_23_dialog_content = "Ela não se move, e todos os nossos ataques não estão adiantando.",
  ui_story_5004_50042601_24_dialog_content = "Você não acha que isso parece com o interior da Colossus, PlayerName?",
  ui_story_5004_50042601_25_dialog_content = "É, parece, mas como isso é possível? Ei, cadê a Bonacie?",
  ui_story_5004_50042601_26_dialog_content = "Onde pode estar, onde pode estar...",
  ui_story_5004_50042601_27_dialog_content = "Meu precioso, meu amor, meu tudo...",
  ui_story_5004_50042601_28_dialog_content = "Onde aqueles Eclipsitas estúpidos o esconderam?",
  ui_story_5004_50042601_29_dialog_content = "Isso, <size=45>bingo!</size>",
  ui_story_5004_50042601_29X1_dialog_content = "Ei, o que vocês dois estão fazendo aqui?",
  ui_story_5004_50042601_29X2_dialog_content = "Shhh, não deixe os aurorianos ouvirem isso!",
  ui_story_5004_50042601_29X3_dialog_content = "Vamos pegar o Movimento e dar pra você.",
  ui_story_5004_50042601_29X4_dialog_content = "Então, você quer dizer que o Movimento tá dentro dessa... coisa?",
  ui_story_5004_50042601_29X5_dialog_content = "Sim. Lembre-se, você deve fazer o Celestita...",
  ui_story_5004_50042601_29X6_dialog_content = "Fazer o Celestita remover o selo, não? Eu sei.",
  ui_story_5004_50042601_29X7_dialog_content = "Agora que eu consegui a outra metade, vocês dois podem descansar, não?",
  ui_story_5004_50042601_29X8_dialog_content = "Cuidado, Senhor Prinny!",
  ui_story_5004_50042601_29X9_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5004_50042601_29X10_dialog_content = "Então arrastou os corpos prum canto escuro... Sim, perfeito!",
  ui_story_5004_50042601_30_dialog_content = "<size=45>PlayerName! Você ainda tá aí?</size>",
  ui_story_5004_50042601_31_dialog_content = "Estamos trancados, onde mais poderíamos estar? Aonde você foi?",
  ui_story_5004_50042601_32_dialog_content = "Encontrei uma <color=#FFB400>coisa interessante</color>, venham ver!",
  ui_story_5004_50042601_33_dialog_content = "O que foi?",
  ui_story_5004_50042601_34_dialog_content = "Parece uma <color=#FFB400>criação Celestita</color>?",
  ui_story_5004_50042601_35_dialog_content = "Sabia que você iria reconhecê-la, não?",
  ui_story_5004_50042601_36_dialog_content = "Essa é uma criação Celestita, e estamos num lugar que parece o interior de uma Colossus... Quer dizer que estamos numa Colossus?",
  ui_story_5004_50042601_37_dialog_content = "Como vou saber? Sou só um músico e anfitrião, não?",
  ui_story_5004_50042601_38_dialog_content = "Descendente... por quem eu tenho esperado...",
  ui_story_5004_50042601_39_dialog_content = "(Aí está de novo.)",
  ui_story_5004_50042601_40_dialog_content = "Que tal usar as suas habilidades psíquicas, PlayerName?",
  ui_story_5004_50042601_41_dialog_content = "Estou com um mau pressentimento, PlayerName.",
  ui_story_5004_50042601_42_dialog_content = "Mas estamos presos. O que mais podemos fazer?",
  ui_story_5004_50042601_43_dialog_content = "Certo, tome cuidado.",
  ui_story_5004_50042601_44_dialog_content = "O descendente... por quem eu tenho esperado...",
  ui_story_5004_50042601_45_dialog_content = "Se você de bom grado pegar o <color=#FFB400>Movimento</color>... você não deve...",
  ui_story_5004_50042601_46_dialog_content = "Invocá-lo...",
  ui_story_5004_50042601_47_dialog_content = "Não deixe... destruir a terra...",
  ui_story_5004_50042601_48_dialog_content = "Ei, a porta tá aberta agora!",
  ui_story_5004_50042701_49_dialog_content = "Obrigado por achar o mecanismo. Eu cansei de chutar essa porta idiota.",
  ui_story_5004_50042701_50_dialog_content = "O que você tirou da caixa, Bonacie?",
  ui_story_5004_50042701_51_dialog_content = "Isso é algum tipo de Movimento na sua mão?",
  ui_story_5004_50042701_52_dialog_content = "Você o reconhece, PlayerName? Esse é um pedaço do Movimento Divino que eu estava procurando.",
  ui_story_5004_50042701_53_dialog_content = "(Então a voz que eu ouvi se referia a isso.)",
  ui_story_5004_50042701_54_dialog_content = "Como você sabe que está aqui? E de onde vêm os Eclipsitas?",
  ui_story_5004_50042701_55_dialog_content = "Eles estavam obviamente protegendo o Movimento.",
  ui_story_5004_50042701_56_dialog_content = "Ah, Celestita. Muito astuto, não?",
  ui_story_5004_50042701_57_dialog_content = "Você está certo, eu fiz um pequeno acordo com os Eclipsitas.",
  ui_story_5004_50042701_58_dialog_content = "Você fez um acordo com os Eclipsitas?",
  ui_story_5004_50042701_59_dialog_content = "E daí? Não é uma parceria e eu não cometi nenhum ato maligno por eles, não?",
  ui_story_5004_50042701_60_dialog_content = "Eles me dão o Movimento que eu quero, e eu garanto que o Monarca do Oceano seja um sucesso.",
  ui_story_5004_50042701_61_dialog_content = "O Monarca do Oceano? Então isso é parte de um plano Eclipsita?",
  ui_story_5004_50042701_62_dialog_content = "Eu não me importo com isso. A voz na minha cabeça e o Movimento são bem mais importantes, não?",
  ui_story_5004_50042701_63_dialog_content = "Você é algum tipo de músico maluco? Ah, espera, sim, você é!",
  ui_story_5004_50042701_64_dialog_content = "Agora que você está com ele, o que vai fazer? Ainda vai se juntar aos Eclipsitas?",
  ui_story_5004_50042701_65_dialog_content = "Eu te disse que não era uma parceria, não? Simplesmente benefícios mútuos! Eu planejava dá-lo a você, PlayerName!",
  ui_story_5004_50042701_66_dialog_content = "Me dar? Depois de tudo que você passou pra conseguir?",
  ui_story_5004_50042701_67_dialog_content = "Bem, é o <color=#FFB400>grande prêmio</color> do Monarca do Oceano, afinal de contas.",
  ui_story_5004_50042701_68_dialog_content = "Eu escondi coisas de você, então estamos quites, não? Mas eu tenho que tocá-lo antes de te dar.",
  ui_story_5004_50042701_69_dialog_content = "Parece que você tá dando a primeira mordida no fruto do trabalho de todo mundo.",
  ui_story_5004_50042701_70_dialog_content = "Bom, somos todos amigos, não? Dá uma olhada...",
  ui_story_5004_50042701_71_dialog_content = "O que, outra combinação perfeita?",
  ui_story_5004_50042701_72_dialog_content = "Claro. Você precisa juntar os dois pra dar um inteiro. É sempre assim, não?",
  ui_story_5004_50042701_73_dialog_content = "Hum...",
  ui_story_5004_50042701_74_dialog_content = "É só isso? Só um clarão?",
  ui_story_5004_50042701_75_dialog_content = "O que está acontecendo?",
  ui_story_5004_50042701_76_dialog_content = "Posso sentir algum tipo de energia nele, mas está sendo suprimida.",
  ui_story_5004_50042701_77_dialog_content = "(Ainda não tá funcionando? Acho que eu devo tentar o que <color=#FFB400>aquele rato</color> falou...)",
  ui_story_5004_50042701_78_dialog_content = "Tenta você, PlayerName. Faça alguma coisa, use as suas habilidades psíquicas talvez, não?",
  ui_story_5004_50042701_79_option_content = "Sem chance.",
  ui_story_5004_50042701_80_dialog_content = "Não quero tocar nada que foi negociado com os Eclipsitas!",
  ui_story_5004_50042701_81_dialog_content = "Tá bom, tá bom. Eu juro que nunca mais vou fazer acordo com os Eclipsitas!",
  ui_story_5004_50042701_82_option_content = "Se me derem...",
  ui_story_5004_50042701_83_dialog_content = "Mesmo assim, não!",
  ui_story_5004_50042701_84_dialog_content = "Meu instinto me diz que isso é algo perigoso!",
  ui_story_5004_50042701_85_dialog_content = "Quão perigoso pode ser? Todos estão aqui, não? Vamos lá, por favor!",
  ui_story_5004_50042701_86_option_content = "Você... Tá bom, vou tentar.",
  ui_story_5004_50042701_87_dialog_content = "Mas ouvi uma voz me dizendo pra não quebrar nenhum selo.",
  ui_story_5004_50042701_88_dialog_content = "Você deve ter ouvido errado, não? Vamos lá, por favor?",
  ui_story_5004_50042701_89_dialog_content = "Você jura que nunca mais vai fazer acordo com os Eclipsitas?",
  ui_story_5004_50042701_90_dialog_content = "Tá bom, tá bom. Eu juro, nunca mais!",
  ui_story_5004_50042701_91_dialog_content = "...",
  ui_story_5004_50042701_92_option_content = "Ativar telepatia",
  ui_story_5004_50042701_93_dialog_content = "Funcionou?",
  ui_story_5004_50042701_94_dialog_content = "Maravilha.",
  ui_story_5004_50042701_95_dialog_content = "Obrigado, PlayerName...",
  ui_story_5004_50042701_96_dialog_content = "O que está fazendo, Bonacie?!",
  ui_story_5004_50042701_97_dialog_content = "Ah, como é maravilhoso! Posso sentir o seu chamado, agora que está sem o selo...",
  ui_story_5004_50042701_98_dialog_content = "Sinto muito, PlayerName...",
  ui_story_5004_50042701_99_dialog_content = "A razão de eu estar aqui, a razão da minha existência é somente para tocar a Melodia Divina!",
  ui_story_5004_50042701_100_dialog_content = "O que é essa energia ameaçadora que estou sentindo?",
  ui_story_5004_50042701_101_dialog_content = "Bonacie!",
  ui_story_5004_50042701_102_dialog_content = "Hahaha!",
  ui_story_5004_50042701_103_dialog_content = "Que belo ritmo! Simplesmente além da perfeição, não?",
  ui_story_5004_50042701_104_dialog_content = "Não... não tenho forças...",
  ui_story_5004_50042701_105_dialog_content = "Não ouça a música!",
  ui_story_5004_50042701_106_dialog_content = "Pare, Bonacie!",
  ui_story_5004_50042701_107_dialog_content = "Coletar o Movimento do Vazio é a maior honra que a voz me concedeu.",
  ui_story_5004_50042701_108_dialog_content = "É absurdo me pedir para parar, não?",
  ui_story_5004_50042701_112_dialog_content = "A energia tá vindo da Bonacie? Não, está saindo do Movimento na frente dela!",
  ui_story_5004_50042701_113_dialog_content = "Ei, olha pra cá!",
  ui_story_5004_50042701_114_dialog_content = "É um castelo saindo do mar?",
  ui_story_5004_50042701_115_dialog_content = "O castelo... Mas como isso é possível...",
  ui_story_5004_50042701_116_dialog_content = "Ouça, PlayerName, é um ritmo impactante, não?",
  ui_story_5004_50042701_117_dialog_content = "Vocês, Celestitas... claro que sua raça iria guardar essa linda música pra vocês mesmos, não? Não há motivo para dividi-la com o resto do mundo!",
  ui_story_5004_50042701_118_dialog_content = "Muito bem, não? Estou começando a apreciar mais vocês Celestitas!",
  ui_story_5004_50042701_119_dialog_content = "Essa é a voz da Verdade, o som da divindade.",
  ui_story_5004_50042701_120_dialog_content = "Eles estão ecoando na minha mente, PlayerName!",
  ui_story_5004_50042701_121_dialog_content = "Para com isso, Beryl. PlayerName! Algo está brilhando sobre a Bonacie!",
  ui_story_5004_50042701_122_dialog_content = "É um meteorito, e está vindo bem na nossa direção!",
  ui_story_5004_50042701_123_dialog_content = "De onde esse meteorito veio?",
  ui_story_5004_50042701_124_dialog_content = "Cuidado, vai cair bem aqui!",
  ui_story_5004_50042701_125_dialog_content = "Domínio do Cristal!",
  ui_story_5004_50042701_126_dialog_content = "Argh!",
  ui_story_5004_50042701_127_dialog_content = "Tudo bem?",
  ui_story_5004_50042701_128_dialog_content = "Sim, só fui derrubado pela onda, só isso. Ainda bem que temos a Beryl...",
  ui_story_5004_50042701_129_dialog_content = "Outro meteorito maior está vindo!",
  ui_story_5004_50042701_130_dialog_content = "Eu vou dar tudo de mim.",
  ui_story_5004_50042701_131_dialog_content = "(Não, um meteorito desse tamanho é mais do que podemos lidar!)",
  ui_story_5004_50042701_132_dialog_content = "Será esse o fim...",
  ui_story_5004_50042701_133_dialog_content = "Não desista tão cedo, PlayerName.",
  ui_story_5004_50042701_134_dialog_content = "Essa voz!",
  ui_story_5004_50042701_135_dialog_content = "Sim, é o seu fiel amigo mecânico e seu colega Brock!",
  ui_story_5004_50042701_136_dialog_content = "Relaxa e curte o poder do Aço Rediesel MkV Zero, PlayerName!",
  ui_story_5004_50042701_137_dialog_content = "Ahhhhh!",
  ui_story_5004_50042701_138_dialog_content = "Pare de gritar! Você tá cem vezes mais louco que o normal!",
  ui_story_5004_50042701_139_dialog_content = "Puxe mais pra cima. Ainda vai funcionar até mais alto!",
  ui_story_5004_50042701_140_dialog_content = "Puxar o que mais pra cima? Esquece, vou puxar todos!",
  ui_story_5004_50042701_141_dialog_content = "Isso aí! Ilumine a minha vida!",
  ui_story_5004_50042701_142_dialog_content = "Ei, o que significa a luz estar piscando?",
  ui_story_5004_50042701_143_dialog_content = "Esse é o aviso de sobrecarga!",
  ui_story_5004_50042701_144_dialog_content = "Então, o que vai acontecer?",
  ui_story_5004_50042701_145_dialog_content = "Vai explodir em 30 segundos!",
  ui_story_5004_50042701_146_dialog_content = "Bem, Aço Rediesel MkV Zero, queime comigo até o final!",
  ui_story_5004_50042701_147_dialog_content = "Tire o meteorito da sua rota!",
  ui_story_5004_50042701_148_dialog_content = "Você não precisa empurrá-lo de volta!",
  ui_story_5004_50042701_149_dialog_content = "Fleur!",
  ui_story_5004_50042701_150_dialog_content = "Sim!",
  ui_story_5004_50042701_151_dialog_content = [[
Maldito meteorito...
Caia <size=45>fora daqui!</size>]],
  ui_story_5004_50042701_152_dialog_content = "(As faíscas do propulsor são ofuscantes!)",
  ui_story_5004_50042701_153_dialog_content = "Sucesso, PlayerName! O meteorito saiu da rota!",
  ui_story_5004_50042701_154_dialog_content = "Tem certeza de que não tem problema? Pelo que eu sei, o robô tá prestes a sobrecarregar e se desmantelar!",
  ui_story_5004_50042701_157_dialog_content = "Não fica aí parado, PlayerName! Saia da praia!",
  ui_story_5004_50042701_158_dialog_content = "As ondas estão vindo!",
  ui_story_5004_50042701_159_dialog_content = "Ainda tô protegido, graças à Bonacie!",
  ui_story_5004_50042701_160_dialog_content = "Segura a minha mão, PlayerName!",
  ui_story_5004_50042701_161_dialog_content = "Não consigo... É tarde demais!",
  ui_story_5004_50042701_162_dialog_content = "Você tá bem, PlayerName?",
  ui_story_5004_50042701_163_dialog_content = "Esse é o que tem tecnologia Celestita que você falou?",
  ui_story_5004_50042701_164_dialog_content = "Sim. Está integrado com a tecnologia Celestita, e é o robô mais poderoso!",
  ui_story_5004_50042701_165_dialog_content = "Porém, infelizmente as peças com tecnologia Celestita sofreram danos graves ao bater no meteorito.",
  ui_story_5004_50042701_166_dialog_content = "Você quer dizer os propulsores inconcebíveis, certo?",
  ui_story_5004_50042701_167_dialog_content = "Seja você de Illumina ou de Lumópolis, todo mundo tem que agradecer muito ao Brock hoje!",
  ui_story_5004_50042701_168_dialog_content = "Lembre-se de votar em mim na próxima eleição pra chefe da Rediesel Wrench, ouviu!",
  ui_story_5004_50042701_169_dialog_content = "É o mesmo Brock de sempre... Ei, cadê a Bonacie?",
  ui_story_5004_50042701_170_dialog_content = "Que bom! Me sinto ótimo!",
  ui_story_5004_50042701_171_dialog_content = "Uou, de onde você veio?",
  ui_story_5004_50042701_172_dialog_content = "Eu estive por perto, até segui vocês quando a onda enorme bateu, vocês nem perceberam, né?",
  ui_story_5004_50042701_173_dialog_content = "Aqui está, o Movimento.",
  ui_story_5004_50042701_174_dialog_content = "Essa foi fácil. Espera, o que você tá escondendo aí agora?",
  ui_story_5004_50042701_175_dialog_content = "Nada, já que meu objetivo era tocá-lo, só isso.",
  ui_story_5004_50042701_176_dialog_content = "Só uma vez e está gravado pra sempre na minha alma, então não preciso ficar com ele.",
  ui_story_5004_50042701_177_dialog_content = "Sem falar que é propriedade Celestita, então é seu direito ficar com ele.",
  ui_story_5004_50042701_178_dialog_content = "Não se preocupe, não vou tocá-lo de novo, então só me perdoe, não?",
  ui_story_5004_50042701_179_dialog_content = "(E você pensa que vai se safar assim?)",
  ui_story_5004_50042701_180_dialog_content = "Essa coisa perigosa precisa ser guardada em algum lugar seguro.",
  ui_story_5004_50042701_181_dialog_content = "Deixá-la por aí só vai atrair outra pessoa para explorá-la.",
  ui_story_5004_50042701_182_dialog_content = "Você tem razão. Vou levar, mas isso não quer dizer que você vai sair impune!",
  ui_story_5004_50042701_183_dialog_content = "Você vai elaborar o seu acordo com os Eclipsitas!",
  ui_story_5004_50042801_E1_dialog_content = "Então isso é tudo, eu juro!",
  ui_story_5004_50042801_E2_dialog_content = "Então você os ajudou com o Monarca do Oceano, só pra pôr as mãos no Movimento?",
  ui_story_5004_50042801_E3_dialog_content = "Isso mesmo! Exatamente!",
  ui_story_5004_50042801_E4_dialog_content = "Tá bom...",
  ui_story_5004_50042801_E5_dialog_content = "Você acordou finalmente, meu senhor...",
  ui_story_5004_50042801_E6_dialog_content = "O que é isso? Deseja conhecer os guerreiros que o acordaram?",
  ui_story_5004_50042801_E7_dialog_content = "Espere, vocês ouviram isso? Está surgindo e desaparecendo gradualmente dos meus ouvidos.",
  ui_story_5004_50042801_E8_dialog_content = "Ok, ok. Hehe, creio que eles querem muito te conhecer...",
  ui_story_5004_50042801_E9_dialog_content = "Mas, você ainda não recuperou todas as suas forças, então deixe eu te ajudar.",
  ui_story_5004_50042801_E10_dialog_content = "Ouvir o quê? Minha mente ainda tá tomada pela melodia... Mas sinto o Fluxo Escuro se adensando!",
  ui_story_5004_50042801_E11_dialog_content = "De onde ele vem? Eu não o sentia há um segundo!",
  ui_story_5004_50042801_E12_dialog_content = "<color=#e8d9bb>“A música toca, terminando a busca. O Monarca desperta, apenas para incinerar as estrelas, trazendo ruína e fúria a todos.”</color>",
  ui_story_5004_50042801_E13_dialog_content = "...",
  ui_story_5004_50042801_184_dialog_content = "Aahhhhhh!",
  ui_story_5004_50042801_185_dialog_content = "Eles são Eclipsitas que fugiram da batalha?",
  ui_story_5004_50042801_186_dialog_content = "Não, eles são...!",
  ui_story_5004_50042802_1_dialog_content = "Poderosos... Muito mais do que aqueles Eclipsitas comuns.",
  ui_story_5004_50042802_2_dialog_content = "De onde eles vieram? Nunca vi algo como eles antes.",
  ui_story_5004_50042802_3_dialog_content = "Felizmente, eles foram derrotados. Não vão poder fazer mal agora.",
  ui_story_5004_50042802_4_dialog_content = "Não, eles podem ser clones.",
  ui_story_5004_50042802_5_dialog_content = "Eu senti outra força bem mais forte controlando-os durante a batalha.",
  ui_story_5004_50042802_6_dialog_content = "E a fonte desse poder está naquele castelo.",
  ui_story_5004_50042802_7_dialog_content = "(Eu estava tão distraído, quase esqueci totalmente daquele castelo superexótico.)",
  ui_story_5004_50042802_8_dialog_content = "(Mas agora, posso sentir facilmente cada vez mais Fluxo Escuro terrível saindo dele.)",
  ui_story_5004_50042802_9_dialog_content = "Tsc. Aqueles Eclipsitas fizeram isso? Que traiçoeiros...",
  ui_story_5004_50042802_10_dialog_content = "Por isso peguei o Movimento tão fácil. Estão usando PlayerName e meus poderes para invocar aquela monstruosidade!",
  ui_story_5004_50042802_11_dialog_content = "Vejo que o Monarca do Oceano não é só um golpe. Aquele rato maldito planejou tudo isso!",
  ui_story_5004_50042802_12_dialog_content = "Da próxima vez, vou simplesmente acabar com eles e pegar o Movimento!",
  ui_story_5004_50042802_13_dialog_content = "Golpe? Pra que os Eclipsitas precisam de dinheiro?!",
  ui_story_5004_50042802_14_dialog_content = "Eles disseram que iriam tirar até o último centavo dos Aurorians e deixá-los pobres. Assim, eles terão que trabalhar e não terão dinheiro pra reagir...",
  ui_story_5004_50042802_15_dialog_content = "Minha atenção estava voltada somente para o Movimento e para mais nada.",
  ui_story_5004_50042802_16_dialog_content = "Deveríamos averiguar o castelo e os inimigos dentro dele, PlayerName.",
  ui_story_5004_50042802_17_dialog_content = "Carleen tem razão. Se não fizermos isso, todos na praia podem estar em perigo, ou talvez até pior.",
  ui_story_5004_50042802_18_dialog_content = "Estamos aqui agora, não podemos deixar os Eclipsitas nos afugentar.",
  ui_story_5004_50042802_19_dialog_content = "São só alguns Eclipsitas bons pra recompensas.",
  ui_story_5004_50042802_20_dialog_content = "Sim, gostaria de ir também... Estou muito curiosa pra ver o que há no castelo...",
  ui_story_5004_50042802_21_dialog_content = "Se a Beryl vai, eu também vou.",
  ui_story_5004_50042802_22_dialog_content = "Por que você tá olhando pra mim? Como Chefe da Segurança, é minha função garantir a segurança da praia!",
  ui_story_5004_50042802_23_dialog_content = "O Aço Rediesel Mark V-Zero vai levar todo mundo!",
  ui_story_5004_50042802_24_dialog_content = "Bom, acho que vou contribuir e consertar o robô usando peças especiais e uma fonte de energia do meu estoque.",
  ui_story_5004_50042802_25_dialog_content = "Então, vamos dar uma surra neles por se atreverem a me explorar!",
  ui_story_5004_50042802_26_dialog_content = "Certo, vamos nessa então!",
  ui_story_5004_50042901_1_dialog_content = "O MkV aguenta, Fleur?",
  ui_story_5004_50042901_2_dialog_content = "É o Aço Rediesel MkV Zero!",
  ui_story_5004_50042901_3_dialog_content = "Ele usa a tecnologia de propulsão da Colossus e é carregado com a fonte de energia da Srta. Bonacie!",
  ui_story_5004_50042901_4_dialog_content = "Acho que ela tá mesmo decidida a acertar as contas com os Eclipsitas que a usaram.",
  ui_story_5004_50042901_5_dialog_content = "Tecnologia da Colossus, você disse? Vai perder energia como Soroz?",
  ui_story_5004_50042901_6_dialog_content = "Cuidado, Fleur. Não voe muito alto!",
  ui_story_5004_50042901_7_dialog_content = "Hã, por quê?",
  ui_story_5004_50042901_8_dialog_content = "Ahn???",
  ui_story_5004_50042901_9_dialog_content = "O que houve? As leituras estão oscilando entre dois extremos!",
  ui_story_5004_50042901_10_dialog_content = "O que foi, Fleur?",
  ui_story_5004_50042901_11_dialog_content = "Nada. Os aparelhos só estão um pouco avariados...",
  ui_story_5004_50042901_12_dialog_content = "Só os aparelhos?",
  ui_story_5004_50042901_13_dialog_content = "Vamos cair! Sabia que essa lata velha não era confiável!",
  ui_story_5004_50042901_14_dialog_content = "Meu Aço Rediesel MkV Zero nunca vai cair!",
  ui_story_5004_50042901_15_dialog_content = "Tá caindo! Rápido, faça alguma coisa!",
  ui_story_5004_50042901_16_dialog_content = "Vamos planar até o castelo! Segurem-se todos!",
  ui_story_5004_50042901_17_dialog_content = "Planar o caramba! Estamos caindo...",
  ui_story_5004_50042901_18_dialog_content = "Calma, tenha fé na tecnologia da Rediesel Wrench!",
  ui_story_5004_50042901_19_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5004_50042901_20_dialog_content = "PlayerName.",
  ui_story_5004_50042901_21_dialog_content = "Acorda, PlayerName.",
  ui_story_5004_50042901_22_dialog_content = "Ah, minha cabeça...",
  ui_story_5004_50042901_23_dialog_content = "Vice?",
  ui_story_5004_50042901_24_dialog_content = "Você finalmente acordou. Você tava todo frio.",
  ui_story_5004_50042901_25_dialog_content = "Onde estamos? Batemos no castelo?",
  ui_story_5004_50042901_26_dialog_content = "Não temos ideia, mas esse lugar parece... muito estranho. O Fluxo Escuro aqui é sufocante.",
  ui_story_5004_50042901_27_dialog_content = "E olha todas as imagens flutuando. Parecem estar vivas.",
  ui_story_5004_50042901_28_dialog_content = "Tá vendo aquele olho no quadro?",
  ui_story_5004_50042901_29_dialog_content = "Ele nos seguiu e tá me dando calafrios.",
  ui_story_5004_50042901_30_dialog_content = "Beryl, aquele quadro ali, tá fazendo malabarismo com limões?",
  ui_story_5004_50042901_31_dialog_content = "Parece que sim...",
  ui_story_5004_50042901_32_dialog_content = "Olha ali, PlayerName!",
  ui_story_5004_50042901_33_dialog_content = "É o Soroz! Como assim ele tá aqui?",
  ui_story_5004_50042901_34_dialog_content = "Preciso ir dar uma olhada.",
  ui_story_5004_50042901_35_dialog_content = "Mas que... Como essa placa surgiu sob os meus pés?",
  ui_story_5004_50042901_36_dialog_content = "É você, Soroz?",
  ui_story_5004_50042901_37_dialog_content = "Droga, não consigo me aproximar dele, não importa quão rápido eu ande.",
  ui_story_5004_50042901_38_dialog_content = "Vai devagar, PlayerName.",
  ui_story_5004_50042901_39_dialog_content = "É perigoso andar tão rápido aqui.",
  ui_story_5004_50042901_40_dialog_content = "Tá bom. Vocês descobriram alguma coisa?",
  ui_story_5004_50042901_41_dialog_content = "Deixa eu pensar... Batemos no castelo e desmaiamos.",
  ui_story_5004_50042901_42_dialog_content = "E acordamos aqui, que definitivamente não é o interior do castelo, mas deve ser uma dimensão de bolso.",
  ui_story_5004_50042901_43_dialog_content = "Tsc. Pensei que iríamos só lutar uma vez e voltar.",
  ui_story_5004_50042901_44_dialog_content = "Agora estamos presos e sem saída.",
  ui_story_5004_50042901_45_dialog_content = "Não acho que tenha outras partes do Movimento aqui.",
  ui_story_5004_50042901_46_dialog_content = "...",
  ui_story_5004_50042901_47_dialog_content = "Como você tá, Beryl? Aqui, se apoie em mim.",
  ui_story_5004_50042901_48_dialog_content = "Tô bem, valeu...",
  ui_story_5004_50042901_49_dialog_content = "Eu preciso confessar uma coisa...",
  ui_story_5004_50042901_50_dialog_content = "Lembra do castelo de areia que eu construí?",
  ui_story_5004_50042901_51_dialog_content = "Sim, ele se parecia muito com este!",
  ui_story_5004_50042901_52_dialog_content = "Você pensou em alguma coisa, Beryl?",
  ui_story_5004_50042901_53_dialog_content = "Não tenho certeza... Mas essa estrutura sempre esteve na minha mente.",
  ui_story_5004_50042901_54_dialog_content = "Então, tô achando que a voz na minha cabeça e este lugar estão conectados.",
  ui_story_5004_50042901_55_dialog_content = "Cuidado, pessoal... Não há só o Fluxo Escuro aqui... Tem uma força que me é muito familiar...",
  ui_story_5004_50042901_56_dialog_content = "Não se preocupe, Beryl, não vamos deixar ninguém te machucar.",
  ui_story_5004_50042901_57_dialog_content = "A gente acerta a minha conta como seu guarda-costas depois. Vou até te dar um desconto!",
  ui_story_5004_50042901_58_dialog_content = "Você só se preocupa com dinheiro? Você não tá agindo como uma nobre, Genev!",
  ui_story_5004_50042901_59_dialog_content = "Fiquem quietas! Tô tentando descontrair o ambiente aqui!",
  ui_story_5004_50042901_60_dialog_content = "Precisamos nos unir pra derrotar os Eclipsitas. Isso é uma coisa que alguém solitário como você não entenderia.",
  ui_story_5004_50042901_61_dialog_content = "Isso mesmo, derrotar os Eclipsitas é o motivo de estarmos todos aqui.",
  ui_story_5004_50042901_62_dialog_content = "Claro, estamos presos em alguma ilusão estranha agora, mas isso não é motivo pra desistir!",
  ui_story_5004_50042901_63_dialog_content = "Direita!",
  ui_story_5004_50042901_64_dialog_content = "Vamos explorar em volta... mesmo não conseguindo enxergar nada.",
  ui_story_5004_50042901_65_dialog_content = "Vamos escolher uma direção e seguir por ela.",
  ui_story_5004_50042901_66_dialog_content = "Tudo bem. Tomem cuidado.",
  ui_story_5004_50042901_67_dialog_content = "Não consigo distinguir o que tem em volta.",
  ui_story_5004_50042901_68_dialog_content = "Não é só o Soroz, mas até mesmo as imagens ao redor parecem de alguma maneira familiares.",
  ui_story_5004_50042901_69_dialog_content = "Essa é a torre de Lumópolis...",
  ui_story_5004_50042901_70_dialog_content = "Aquela mulher no quadro...!",
  ui_story_5004_50042901_71_dialog_content = "Criaturas vis, como ousam me confundir usando a imagem da minha mãe!",
  ui_story_5004_50042901_72_dialog_content = "Fica fria, Carleen. Não cai nos truques deles.",
  ui_story_5004_50042901_73_dialog_content = "Esse lugar consegue ler as nossas mentes?",
  ui_story_5004_50042901_74_dialog_content = "A menininha naquele quadro...",
  ui_story_5004_50042901_75_dialog_content = "(Por que desejo tocá-lo?)",
  ui_story_5004_50042901_76_option_content = "Tocar a imagem",
  ui_story_5004_50042901_77_dialog_content = "...!",
  ui_story_5004_50042901_78_dialog_content = "(Que fumaça intensa, e ouço um choro familiar... Não foi isso que vi quando toquei a Beryl?)",
  ui_story_5004_50042901_79_dialog_content = "Sinto muito...",
  ui_story_5004_50042901_80_dialog_content = "Pai, mãe... sinto muito...",
  ui_story_5004_50042901_81_dialog_content = "PlayerName, PlayerName?",
  ui_story_5004_50042901_82_dialog_content = "Vice...",
  ui_story_5004_50042901_83_dialog_content = "Por que você tá chorando? O que você sentiu?",
  ui_story_5004_50042901_84_dialog_content = "(Isso era memória da Beryl? Por que eu vi isso do nada?)",
  ui_story_5004_50042901_85_dialog_content = "(Qual é a conexão entre a Beryl e essa imagem? Seus pais...)",
  ui_story_5004_50042901_86_dialog_content = "(Não, pode ser outro truque dos Eclipsitas. Devo ficar quieto até saber mais.)",
  ui_story_5004_50042901_87_dialog_content = "Eu tô bem, apenas vendo algumas ilusões... Provavelmente é uma artimanha dos Eclipsitas.",
  ui_story_5004_50042901_88_dialog_content = "Fale pra todos tomarem cuidado com as imagens. Elas podem enganar a sua mente.",
  ui_story_5004_50042901_89_dialog_content = "O que diabos são essas... Por quê?",
  ui_story_5004_50042901_90_dialog_content = "Por que vocês estão se movendo sorrateiramente aí?",
  ui_story_5004_50042901_91_dialog_content = "As duas imagens ao seu lado somos nós crianças. O que estão fazendo?",
  ui_story_5004_50042901_92_dialog_content = "Nem mais um passo!",
  ui_story_5004_50042901_93_dialog_content = "Ei! Por que você a queimou? Nem consegui vê-la.",
  ui_story_5004_50042901_94_dialog_content = "É porque eu não quero que você veja!",
  ui_story_5004_50042901_95_dialog_content = "Aaarrgh!",
  ui_story_5004_50042901_96_dialog_content = "Cuidado, Eclipsitas!",
  ui_story_5004_50042901_97_dialog_content = "Gah! Gah!",
  ui_story_5004_50042901_98_dialog_content = "Eles saíram de dentro das imagens! Preparem-se para lutar!",
  ui_story_5004_50043001_1_dialog_content = "Peguei todos eles. É impressão minha, ou eles são mais fortes que aqueles da praia?",
  ui_story_5004_50043001_2_dialog_content = "Sim, são bem mais fortes.",
  ui_story_5004_50043001_3_dialog_content = "E são só clones. O Fluxo Escuro não diminuiu nem um pouco.",
  ui_story_5004_50043001_4_dialog_content = "Não conseguimos nem achar os inimigos de verdade agora. Isso vai ser difícil.",
  ui_story_5004_50043001_5_dialog_content = "Essa é a primeira vez que me deparo com... uma ilusão tão estranha.",
  ui_story_5004_50043001_6_dialog_content = "Me empresta o broche do seu chapéu, Genevieve.",
  ui_story_5004_50043001_7_dialog_content = "Pra quê? Não vá quebrá-lo!",
  ui_story_5004_50043001_8_dialog_content = "Iiáaa!",
  ui_story_5004_50043001_9_dialog_content = "Por que você o jogou?",
  ui_story_5004_50043001_10_dialog_content = "Ai! Como assim ele acertou meu rosto de cima?",
  ui_story_5004_50043001_11_dialog_content = "Até as direções estão trocadas!",
  ui_story_5004_50043001_12_dialog_content = "Que tal jogar o seu Casulo Lunar, Carleen?",
  ui_story_5004_50043001_13_dialog_content = "É melhor você atirar uma flecha em vez disso.",
  ui_story_5004_50043001_14_dialog_content = "Ah, certo...",
  ui_story_5004_50043001_15_dialog_content = "Espera! E se acertar o meu rosto de novo?",
  ui_story_5004_50043001_16_dialog_content = "Não tem problema, eu tô aqui! Vou fazer um míssil seguir a flecha!",
  ui_story_5004_50043001_17_dialog_content = "Não, só me deixa em paz e arranja outra ideia!",
  ui_story_5004_50043001_18_dialog_content = "Que tal falar com aquela imagem de boca ali?",
  ui_story_5004_50043001_19_dialog_content = "Esquece, parece nojenta.",
  ui_story_5004_50043001_20_dialog_content = "Parece que é de outro mundo.",
  ui_story_5004_50043001_21_dialog_content = "Então...",
  ui_story_5004_50043001_22_dialog_content = "Que tal aquela?",
  ui_story_5004_50043001_23_dialog_content = "A mesma menininha? Ela tá apontando pra porta atrás dela.",
  ui_story_5004_50043001_24_dialog_content = "Ela quer que a gente entre nela?",
  ui_story_5004_50043001_25_dialog_content = "Bom, o que mais podemos fazer? Ela não parece hostil.",
  ui_story_5004_50043001_26_dialog_content = "Mas é tão pequena. Como vamos entrar?",
  ui_story_5004_50043001_27_option_content = "Colocar um dedo",
  ui_story_5004_50043001_28_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5004_50043001_29_dialog_content = "Acho que eu apertei alguma coisa. Ei, o que tá acontecendo?",
  ui_story_5004_50043001_30_dialog_content = "O chão está sumindo! Nós vamos cair!",
  ui_story_5004_50043001_31_dialog_content = "...!",
  ui_story_5004_50043001_32_dialog_content = "Ela desmaiou. O que faremos agora? Não acredito que o pó poderia criar monstros tão horríveis...",
  ui_story_5004_50043001_33_dialog_content = "Temos amostras suficientes. Vamos largá-la aqui.",
  ui_story_5004_50043001_34_dialog_content = "Estou curioso pra ver a reação dela quando acordar e enxergar todos esses cadáveres.",
  ui_story_5004_50043001_35_dialog_content = "Esse é o preço que se paga pela traição.",
  ui_story_5004_50043001_36_dialog_content = "Você é tão impiedoso quanto os Eclipsitas.",
  ui_story_5004_50043001_37_dialog_content = "Argh!",
  ui_story_5004_50043001_38_dialog_content = "Isso dói...",
  ui_story_5004_50043001_39_dialog_content = "Sai, por favor!",
  ui_story_5004_50043001_40_dialog_content = "Não consigo respirar...",
  ui_story_5004_50043001_41_dialog_content = "Eu quase morri lá. É uma droga eu ter que ficar no fundo, só porque eu o toquei primeiro!",
  ui_story_5004_50043001_42_dialog_content = "Obrigado por ter nos salvado, PlayerName.",
  ui_story_5004_50043001_43_dialog_content = "Diga, se esse é um dos jogos de Gronru, devemos estar no Nível Dois agora.",
  ui_story_5004_50043001_44_dialog_content = "Quer dizer que vamos ver novos inimigos?",
  ui_story_5004_50043001_45_dialog_content = "Bem-vindos, convidados de muito longe!",
  ui_story_5004_50043001_46_dialog_content = "Vai começar!",
  ui_story_5004_50043001_47_dialog_content = "Bem-vindos ao meu castelo e jardim, a Fortaleza do Vazio dos Sonhos.",
  ui_story_5004_50043001_48_dialog_content = "Fortaleza do Vazio dos Sonhos? Você é a dona?",
  ui_story_5004_50043001_49_dialog_content = "Vocês podem pensar em mim como a senhora desse lugar. Afinal, eu vivo aqui com todos esses brinquedos há mais de dez anos.",
  ui_story_5004_50043001_50_dialog_content = "Ah! Me refiro às peças de boas-vindas que vocês encontraram. Elas não trataram vocês mal, trataram?",
  ui_story_5004_50043001_51_dialog_content = "A voz...!",
  ui_story_5004_50043001_52_dialog_content = "É a voz dos meus sonhos!",
  ui_story_5004_50043001_53_dialog_content = "Então, os Eclipsitas que parecem peças de xadrez são criações suas? Por que você tem esse aspecto?",
  ui_story_5004_50043001_54_dialog_content = "Calma lá. Vejo que o Celestita é mesmo tão curioso quanto dizem.",
  ui_story_5004_50043001_55_dialog_content = "Não tivemos nenhum visitante Aurorian faz anos, então espero que me mantenham entretida e não morram tão facilmente.",
  ui_story_5004_50043001_56_dialog_content = "Deixa eu procurar no diário dos meus primeiros anos aqui. Talvez haja uma resposta nele pra você.",
  ui_story_5004_50043001_57_dialog_content = "Ei, sumiu... Aonde foi aquele primeiro diário? Você o roubou?",
  ui_story_5004_50043001_58_dialog_content = "Ah não, sem ele eu não posso dar aos convidados meu chá da tarde especial!",
  ui_story_5004_50043001_59_dialog_content = "Talvez eu deva abrir as suas cabeças e ver se o meu diário está aí dentro?",
  ui_story_5004_50043001_60_dialog_content = "Acho que ela não tá batendo bem, PlayerName.",
  ui_story_5004_50043001_61_dialog_content = "Ei, para com essa farsa. Você é a chefe daquele rato trapaceiro, não é?",
  ui_story_5004_50043001_62_dialog_content = "Não vamos agir ainda. Não sabemos o suficiente sobre esse lugar. Devemos tentar conversar primeiro.",
  ui_story_5004_50043001_63_option_content = "Quem é você?",
  ui_story_5004_50043001_64_dialog_content = "Eu sou... hã... Deixa eu pensar, o que estava escrito no segundo diário...?",
  ui_story_5004_50043001_65_dialog_content = "Sou uma grande acadêmica e uma algoz impiedosa!",
  ui_story_5004_50043001_66_dialog_content = "Uau, estou muito impressionado!",
  ui_story_5004_50043001_67_dialog_content = "(Ela ainda tá vendendo essa ideia...)",
  ui_story_5004_50043001_68_option_content = "O que é a Fortaleza do Vazio dos Sonhos?",
  ui_story_5004_50043001_69_dialog_content = "É onde estamos agora! Deixe-me ver... É um jogo de xadrez de pura angústia mental e loucura.",
  ui_story_5004_50043001_70_dialog_content = "É o que está escrito no meu sexto diário.",
  ui_story_5004_50043001_71_dialog_content = "Também é onde o Monarca dorme e onde eu prometi acordá-lo.",
  ui_story_5004_50043001_72_dialog_content = "(Dado o Fluxo Escuro, há um Eclipsita muito forte por aqui. Poderá ser o Monarca a que ela se refere?)",
  ui_story_5004_50043001_73_option_content = "Por que ele emergiria do fundo do mar?",
  ui_story_5004_50043001_74_dialog_content = "Boa pergunta.",
  ui_story_5004_50043001_75_dialog_content = "“Era uma cidade magnífica antes de ser banida pelos malvados Celestitas.”",
  ui_story_5004_50043001_76_dialog_content = "“A raça diabólica tomou seus desertos quando foram massacrados.”",
  ui_story_5004_50043001_77_dialog_content = "Ei, tem muita coisa nesse livro “Como cozinhar Celestitas”!",
  ui_story_5004_50043001_78_dialog_content = "De quais lanches você gosta, Celestita? Posso te cozinhar no que você quiser!",
  ui_story_5004_50043001_79_dialog_content = "(Banidos pelos Celestitas? Ela se aproveitou da obsessão da Bonacie com o Movimento e arquitetou a trama?)",
  ui_story_5004_50043001_80_dialog_content = "Cansei dos devaneios dela, PlayerName.",
  ui_story_5004_50043001_81_option_content = "Espere, espere...",
  ui_story_5004_50043001_82_dialog_content = "Eu tenho mais alguns livros e diários. Vamos conversar mais um pouco.",
  ui_story_5004_50043001_83_option_content = "Ela enlouqueceu de vez...",
  ui_story_5004_50043001_84_dialog_content = "Vamos atacar antes que ela nos deixe confusos, PlayerName.",
  ui_story_5004_50043001_85_dialog_content = "O quê? Não, por favor não me ataquem!",
  ui_story_5004_50043001_86_dialog_content = "Se fizerem isso, eu... eu vou ter que matar vocês!",
  ui_story_5004_50043001_87_dialog_content = "E vocês não podem morrer tão cedo! Foi difícil chegar aqui, então por que não descobrem mais sobre esse lugar?",
  ui_story_5004_50043001_88_dialog_content = "Por favor, não podemos conversar? Não me ataquem! Eu servirei chá pra vocês!",
  ui_story_5004_50043001_89_dialog_content = "Um, dois, três, quatro, cinco... Vou providenciar porções para cinco agora mesmo!",
  ui_story_5004_50043001_90_dialog_content = "Ela foi embora... Ei, espera, não estamos em seis?",
  ui_story_5004_50043001_91_dialog_content = "Cadê a Bonacie?",
  ui_story_5004_50043001_92_dialog_content = "Parada aí! O que você fez com a Bonacie?",
  ui_story_5004_50043001_93_dialog_content = "Que grosseria! Eu a mandei pra um lugar mais adequado pra um chá!",
  ui_story_5004_50043001_94_dialog_content = "Devolva-a. Agora!",
  ui_story_5004_50043001_95_dialog_content = "Isso é uma ordem? Haha, que adorável meu convidado me dando ordens!",
  ui_story_5004_50043001_96_dialog_content = "Seu insolente, atrapalhando meu chá... Não, eu não quero matá-lo. Preciso me controlar!",
  ui_story_5004_50043001_97_dialog_content = "Ei, você é de Lumópolis, certo? Posso sentir isso.",
  ui_story_5004_50043001_98_dialog_content = "Arrogante, teimoso e reprovador.",
  ui_story_5004_50043001_99_dialog_content = "De volta pra você. Como Capitã dos Guardiões de Lumópolis...",
  ui_story_5004_50043001_100_dialog_content = "Qualquer Eclipsita ameaçando a existência dos Aurorians deve conhecer a minha ira!",
  ui_story_5004_50043001_101_dialog_content = "He...",
  ui_story_5004_50043001_102_dialog_content = "Heheh...",
  ui_story_5004_50043001_103_dialog_content = "Hahaha!",
  ui_story_5004_50043001_104_dialog_content = "Bem dito, muito bem dito!",
  ui_story_5004_50043001_105_dialog_content = "Não consigo mais lutar contra isso, querida Capitã, não consigo!",
  ui_story_5004_50043001_106_dialog_content = "Se você insiste, então irá brincar com os meus brinquedos!",
  ui_story_5004_50043001_107_dialog_content = "Aaarrgh!",
  ui_story_5004_50043001_108_dialog_content = "Cuidado, os monstros estão vindo!",
  ui_story_5004_50043101_1_dialog_content = "Isso foi emocionante, minha capitãzinha.",
  ui_story_5004_50043101_2_dialog_content = "Eu tomei umas xícaras de chá vendo vocês lutarem e isso me fez sentir muito melhor.",
  ui_story_5004_50043101_3_dialog_content = "Mas vejo que todos vocês têm mais algumas feridas e seus golpes estão ficando lentos.",
  ui_story_5004_50043101_4_dialog_content = "Acho que os Aurorians não são tão fortes, já que tiveram dificuldade em derrotar os meus brinquedos.",
  ui_story_5004_50043101_5_dialog_content = "Sugiro não me inquietar, nem investir contra mim. Conversem comigo, ou pelo menos ganhem um pouco de tempo.",
  ui_story_5004_50043101_6_dialog_content = "Todos esses anos escrevendo nos diários, isso é a coisa mais excitante que aconteceu em muito tempo.",
  ui_story_5004_50043101_7_dialog_content = "Por favor, me façam companhia por mais algum tempo.",
  ui_story_5004_50043101_8_dialog_content = "O que você realmente quer?",
  ui_story_5004_50043101_9_dialog_content = "O quê? Deixa eu pensar... Cansei do trabalho de pesquisa, então que tal me tornar chefe de cozinha?",
  ui_story_5004_50043101_10_dialog_content = "Como o meu favorito, “Como cozinhar Celestitas”, eu deveria escrever “Como cozinhar Aurorians”!",
  ui_story_5004_50043101_11_dialog_content = "Espere, não, eu fico empolgada só de pensar nisso, e isso pode me fazer querer matar vocês de novo!",
  ui_story_5004_50043101_12_dialog_content = "Não, é chato simplesmente matar vocês, e o Monarca deve participar do chá que planejei por tanto tempo...",
  ui_story_5004_50043101_13_dialog_content = "Esse é o meu Monarca Desolado, meu novo mestre, que me concedeu poder. Ele vai amar jantar os lanches feitos de vocês.",
  ui_story_5004_50043101_14_dialog_content = "Sim, vocês vão testemunhar o meu poder e sentir o medo e o desespero...",
  ui_story_5004_50043101_15_dialog_content = "Isso vai torná-los ainda mais saborosos e deliciosos!",
  ui_story_5004_50043101_16_dialog_content = "Isso não é poder, são só uns truques sofisticados!",
  ui_story_5004_50043101_17_dialog_content = "Pare de bravatear, Eclipsita.",
  ui_story_5004_50043101_18_dialog_content = "As suas criações são só pedras no caminho.",
  ui_story_5004_50043101_19_dialog_content = "Criar e controlar esses fantoches vai te custar caro.",
  ui_story_5004_50043101_20_dialog_content = "Quando encontrarmos o seu verdadeiro eu, estará acabado!",
  ui_story_5004_50043101_21_dialog_content = "Verdade, eu não tenho um poder tão grande, mas o Monarca tem.",
  ui_story_5004_50043101_22_dialog_content = "“Algumas pessoas em Lumópolis cobiçam o grande poder dos Eclipsitas.”",
  ui_story_5004_50043101_23_dialog_content = "“Alguns até fariam acordos com os Eclipsitas, trocando até mesmo seus corpos e vidas para obter Fluxo Escuro.”",
  ui_story_5004_50043101_24_dialog_content = "Deixe-me ver... Esse livro tem mais de uma década. Lumópolis ainda é assim?",
  ui_story_5004_50043101_25_dialog_content = "Você se importaria de me contar como é proteger aqueles traidores, querida Capitã?",
  ui_story_5004_50043101_26_dialog_content = "Suas palavras não podem me tentar, herege.",
  ui_story_5004_50043101_27_dialog_content = "Nada mal. Vejo que é preciso mais do que músculos pra ser um capitão.",
  ui_story_5004_50043101_28_dialog_content = "Então você já sabe a bagunça que é Lumópolis.",
  ui_story_5004_50043101_29_dialog_content = "Sim, a tal cidade que nunca cai, as altas torres brancas...",
  ui_story_5004_50043101_30_dialog_content = "Os supostos defensores da esperança são na verdade nobres mentirosos...",
  ui_story_5004_50043101_31_dialog_content = "Os charlatões desonestos e hipócritas!",
  ui_story_5004_50043101_32_dialog_content = "Quem pensaria que impostores pretensiosos poderiam estar entre as suas elites governantes!",
  ui_story_5004_50043101_33_dialog_content = "Não é verdade, hein, hein, hein?",
  ui_story_5004_50043101_34_dialog_content = "<color=#FFB400>Beryl Gautier</color>!",
  ui_story_5004_50043101_35_dialog_content = "Você me conhece... Quem é você? Como você me conhece?",
  ui_story_5004_50043101_36_dialog_content = "Gautier, Gautier, Gautier...",
  ui_story_5004_50043101_37_dialog_content = "Claro que te reconheço, e à sua família ridícula também!",
  ui_story_5004_50043101_38_dialog_content = "O seu nome está em todos os meus diários!",
  ui_story_5004_50043101_39_dialog_content = "Você não está aqui pra se redimir por causa do sangue que corre em suas veias e pecados que carrega?",
  ui_story_5004_50043101_40_dialog_content = "Eles sabiam o quanto o cristal é potente...",
  ui_story_5004_50043101_41_dialog_content = "Ainda assim, tentaram enganar a morte. Que absurdo!",
  ui_story_5004_50043101_42_dialog_content = "Isso é o poder, o puro poder, que deveria ser usado para conquistar e destruir!",
  ui_story_5004_50043101_43_dialog_content = "Não é um brinquedo para palhaços, sobretudo os de Lumópolis!",
  ui_story_5004_50043101_44_dialog_content = "Como você sabe tanto sobre a minha família...?",
  ui_story_5004_50043101_45_dialog_content = "Como? Ah, então você não se lembra. Ótimo! Espera, não, não é ótimo, é uma pena!",
  ui_story_5004_50043101_46_dialog_content = "É uma pena, uma pena... Você pode evitar isso, se tiver um diário que nem eu.",
  ui_story_5004_50043101_47_dialog_content = "Vou preparar uma porção a mais pra você, feita da garota ao seu lado.",
  ui_story_5004_50043101_48_dialog_content = "Não se atreva a tocar na Raphaela!",
  ui_story_5004_50043101_49_dialog_content = "Pequena Beryl...",
  ui_story_5004_50043101_50_dialog_content = "Hã? Tá bom, eu não vou tocar nela. Hehe!",
  ui_story_5004_50043101_51_dialog_content = "Mas mesmo se eu não a tocar, você pensa que pode protegê-la sendo um mero peão?",
  ui_story_5004_50043101_52_dialog_content = "Eu sinceramente escreverei sobre a comovente relação de vocês nos mínimos detalhes!",
  ui_story_5004_50043101_53_dialog_content = "Vocês viverão nos meus escritos mesmo depois de morrer!",
  ui_story_5004_50043101_54_dialog_content = "Como devo chamá-lo? “Tola Inocência”? “A Triste Canção de um Peão”?",
  ui_story_5004_50043101_55_dialog_content = "Todos vocês, Aurorians, me fazem rir com a sua estupidez, tanto que quero amarrar cada um e interrogar pro meu livro!",
  ui_story_5004_50043101_56_dialog_content = "Ah, é, e transformá-los em lanches para comer com o meu chá!",
  ui_story_5004_50043101_57_dialog_content = "Ler as histórias das suas vidas, enquanto provo o gosto dos seus corpos...",
  ui_story_5004_50043101_58_dialog_content = "Por exemplo, aquela Aurorian estúpida, tema do meu livro “Música Tola”.",
  ui_story_5004_50043101_59_dialog_content = "Ela só queria tocar música e involuntariamente quebrou o selo.",
  ui_story_5004_50043101_60_dialog_content = "Eu mandei Eclipsitas ao hotel e <color=#FFB400>montei arapucas</color>... Daí, mantive o Monarca do Oceano para extrair a Lúmina de todos os Aurorians presentes.",
  ui_story_5004_50043101_61_dialog_content = "Todos vocês tiveram um papel importante em reviver o Monarca Desolado!",
  ui_story_5004_50043101_62_dialog_content = "Sou uma perfeita estrategista, conspiradora, jogadora de xadrez... ah, e autora!",
  ui_story_5004_50043101_63_dialog_content = "Você esqueceu de lunática. Você enlouqueceu por ter ficado tanto tempo aqui!",
  ui_story_5004_50043101_64_dialog_content = "O quê? Como ousa... Como ousa dizer algo tão digno de registro!",
  ui_story_5004_50043101_65_dialog_content = "Antes de eu fazer vocês de sobremesa, tentem não ser mortos pelos meus novos brinquedos, eu imploro.",
  ui_story_5004_50043101_66_dialog_content = "Por favor, sobrevivam!",
  ui_story_5004_50043201_1_dialog_content = "Arf, arf...",
  ui_story_5004_50043201_2_dialog_content = "Seu nariz está sangrando de novo, PlayerName. Vai com calma.",
  ui_story_5004_50043201_3_dialog_content = "Estou bem, só um pouco cansado.",
  ui_story_5004_50043201_4_dialog_content = "(A luta constante está me custando um alto preço...)",
  ui_story_5004_50043201_5_dialog_content = "A luta acabou? Estou só começando a próxima sobremesa.",
  ui_story_5004_50043201_6_dialog_content = "Meus comentários sobre a sua última luta são...",
  ui_story_5004_50043201_7_dialog_content = "“Uma criança conduzindo uma briga lutou com a velocidade de uma idosa balançando uma bengala.”",
  ui_story_5004_50043201_8_dialog_content = "Sinceramente, vocês tão cada vez mais lentos. Tem quatro xícaras de chá e lanches esperando por vocês.",
  ui_story_5004_50043201_9_dialog_content = "Você... acha que isso é um jogo?",
  ui_story_5004_50043201_10_dialog_content = "Você tem orgulho de mandar ilusões e clones pra lutar com a gente?",
  ui_story_5004_50043201_11_dialog_content = "Vem aqui lutar com a gente, se tiver coragem!",
  ui_story_5004_50043201_12_dialog_content = "Me chamando pra lutar, quando não conseguiram nem derrotar meus brinquedos patéticos?",
  ui_story_5004_50043201_13_dialog_content = "Quero saber mais sobre vocês, pois a comida é mais saborosa quando recheada de emoções.",
  ui_story_5004_50043201_14_dialog_content = "Além do mais, o Monarca Desolado ainda está reunindo suas forças. Temos tempo pra conversar.",
  ui_story_5004_50043201_15_dialog_content = "Ah, encontrei o primeiro diário! Deixe-me ver o que escrevi...",
  ui_story_5004_50043201_16_dialog_content = "Hahahaha, que achado! Venham aqui e deixe-me ler pra vocês!",
  ui_story_5004_50043201_17_dialog_content = "Hum-hum, pausa enquanto limpo minha garganta.",
  ui_story_5004_50043201_18_dialog_content = "Por que o seu pobre cérebro não consegue entender isso, pequena Gautier?",
  ui_story_5004_50043201_19_dialog_content = "Quem saberia tanto sobre os cristais, e quem poderia lhe chamar em seus sonhos?",
  ui_story_5004_50043201_20_dialog_content = "É você... Você é a única Pyrrhus sobrevivente... que fugiu dos Eclipsitas... Caroline Pyrrhus!",
  ui_story_5004_50043201_21_dialog_content = "Sim, eu mesma!",
  ui_story_5004_50043201_22_dialog_content = "Ah não, é embaraçoso ouvir meu antigo nome Aurorian!",
  ui_story_5004_50043201_23_dialog_content = "Sabia que eu não deveria ler os diários pras pessoas.",
  ui_story_5004_50043201_24_dialog_content = "Mas eu ainda quero, então me ouçam!",
  ui_story_5004_50043201_25_dialog_content = "Você era uma Aurorian?",
  ui_story_5004_50043201_26_dialog_content = "Outra que se submeteu e vendeu sua alma pros Eclipsitas.",
  ui_story_5004_50043201_27_dialog_content = "Hi, isso mesmo. Quase esqueci que já fui uma Aurorian.",
  ui_story_5004_50043201_28_dialog_content = "Mas o diário tá cheio de detalhes de como fiquei livre e feliz depois de me tornar uma Eclipsita.",
  ui_story_5004_50043201_29_dialog_content = "Mil vezes mais feliz do que em Lumópolis!",
  ui_story_5004_50043201_30_dialog_content = "Voltando ao assunto. Como eu disse, diferente da minha família, a sua só queria usar os cristais como fonte de energia...",
  ui_story_5004_50043201_31_dialog_content = "Quando o seu poder impiedoso e brutal deve ser usado como uma arma!",
  ui_story_5004_50043201_34_dialog_content = "Poderia ter sido a força que repeliria os Eclipsitas de Lumópolis, até mesmo mandando-os de volta ao abismo!",
  ui_story_5004_50043201_35_dialog_content = "Mas a sua fraca família reclamou disso com o Senhor da Cidade! Ah, estou ficando zangada de novo ao ler essa parte!",
  ui_story_5004_50043201_36_dialog_content = "Vocês, Pyrrhus, sequestravam Aurorians oprimidos e faziam experiências com eles usando os cristais.",
  ui_story_5004_50043201_37_dialog_content = "Ninguém sensível iria tolerar experiências com seu próprio povo!",
  ui_story_5004_50043201_38_dialog_content = "Admito que eu me envolvi muito com as experiências quando era mais jovem.",
  ui_story_5004_50043201_39_dialog_content = "Mas sem mim, não haveria a Beryl que veem agora, a cobaia da qual mais me orgulho...",
  ui_story_5004_50043201_40_dialog_content = "Não me diga que a Beryl...",
  ui_story_5004_50043201_41_dialog_content = "...",
  ui_story_5004_50043201_42_dialog_content = "O diário contém informações muito detalhadas. Sua comida favorita, esporte favorito...",
  ui_story_5004_50043201_43_dialog_content = "Até o que gosta de segurar enquanto dorme.",
  ui_story_5004_50043201_44_dialog_content = "É como se o autor estivesse apaixonado por você!",
  ui_story_5004_50043201_45_dialog_content = "Espera, eu sou a autora, então isso faz de mim uma voyeur.",
  ui_story_5004_50043201_46_dialog_content = "Mesmo que não seja impecável, foi um marco em meus experimentos.",
  ui_story_5004_50043201_47_dialog_content = "E eu coloquei amor em você...",
  ui_story_5004_50043201_48_dialog_content = "Os cristais em pó especiais feitos com Fluxo Escuro ainda estão crescendo em seu corpo, não estão?",
  ui_story_5004_50043201_49_dialog_content = "Eles vivem dentro de você, se alimentando das suas emoções e vontades.",
  ui_story_5004_50043201_50_dialog_content = "Para...",
  ui_story_5004_50043201_51_dialog_content = "Mas definitivamente são instáveis... Hi, chegamos na minha parte favorita!",
  ui_story_5004_50043201_52_dialog_content = "Ah, aquele incêndio enorme que você causou e os gritos das inúmeras vítimas Aurorians...",
  ui_story_5004_50043201_53_dialog_content = "Para!",
  ui_story_5004_50043201_54_dialog_content = "Não fique convencida!",
  ui_story_5004_50043201_55_dialog_content = "Hi, o Monarca está me chamando...",
  ui_story_5004_50043201_56_dialog_content = "Voltarei logo e transformarei vocês em comidinhas deliciosas, como aqueles Aurorians tostados.",
  ui_story_5004_50043201_57_dialog_content = "Não, não, não, não, não!",
  ui_story_5004_50043201_58_dialog_content = "Calma, Beryl!",
  ui_story_5004_50043201_59_dialog_content = "Raphaela, deixa eu tentar acamá-la usando telepatia!",
  ui_story_5004_50043201_60_dialog_content = "Por favor, rápido. Ela parece estar sofrendo muito...",
  ui_story_5004_50043201_61_dialog_content = "(Sinto uma força selvagem fluindo em seu corpo.)",
  ui_story_5004_50043201_62_dialog_content = "(Com certeza é algo que nenhum Aurorian possuiria, mas também não é Fluxo Escuro.)",
  ui_story_5004_50043201_63_dialog_content = "(Talvez seja uma força maliciosa e destrutiva, como a Caroline disse.)",
  ui_story_5004_50043201_64_dialog_content = "(Beryl tem lutado para mantê-la sob controle, só pra Caroline ir lá e provocá-la...)",
  ui_story_5004_50043201_65_dialog_content = "(E ela está perdendo o controle aos poucos.)",
  ui_story_5004_50043201_66_dialog_content = "Pequena Beryl...",
  ui_story_5004_50043201_67_dialog_content = "Raphaela... Estou bem agora... Obrigada, PlayerName.",
  ui_story_5004_50043201_68_dialog_content = "Desculpa... Eu não quis esconder a meu passado de vocês...",
  ui_story_5004_50043201_69_dialog_content = "Mas isso provavelmente é culpa dos experimentos da Caroline... Ou talvez instintivamente tenha me recusado a lembrar de memórias dolorosas...",
  ui_story_5004_50043201_70_dialog_content = "Não me lembro de quase nada dessa parte do passado...",
  ui_story_5004_50043201_71_dialog_content = "Só me lembro que os Pyrrhus me sequestraram quando era muito jovem.",
  ui_story_5004_50043201_72_dialog_content = "Eles me trancaram em um quarto totalmente escuro... me alimentaram com pó de cristal...",
  ui_story_5004_50043201_73_dialog_content = "Então, meu corpo parecia amaldiçoado... Não conseguia escapar dos cristais que me agoniavam.",
  ui_story_5004_50043201_74_dialog_content = "Só mais tarde eu descobri... que isso era um experimento dos Pyrrhus pra transformar Aurorians em armas... usando os cristais.",
  ui_story_5004_50043201_75_dialog_content = "Tá tudo bem, Beryl. Todo mundo tem o próprio passado.",
  ui_story_5004_50043201_76_dialog_content = "Compartilhe os momentos felizes e esqueça os ruins. Ninguém vai te culpar por querer uma vida nova.",
  ui_story_5004_50043201_77_dialog_content = "Por mim, tá tudo bem. Digo, meu passado não é muito melhor que o seu.",
  ui_story_5004_50043201_78_dialog_content = "Eu também não ligo. Não precisa se envergonhar.",
  ui_story_5004_50043201_79_dialog_content = "Somos amigas e eu confio na Beryl do presente, não importa o que aconteceu no passado!",
  ui_story_5004_50043201_80_dialog_content = "Sem dúvida, o mais urgente é punir Caroline pelos pecados que cometeu e impedir que mais tragédias aconteçam.",
  ui_story_5004_50043201_81_dialog_content = "Estou com vocês, claro.",
  ui_story_5004_50043201_82_dialog_content = "Obrigada, pessoal...",
  ui_story_5004_50043201_83_dialog_content = "Caroline Pyrrhus... Ela com certeza não tem mais nenhuma honra em si, como uma ex-nobre.",
  ui_story_5004_50043201_84_dialog_content = "Ela não só conspirou com os Eclipsitas, como também cometeu atrocidades contra o seu próprio povo.",
  ui_story_5004_50043201_85_dialog_content = "E tem também o Monarca que ela venera. Se ele for tão poderoso quanto ela o descreveu...",
  ui_story_5004_50043201_86_dialog_content = "Precisamos impedir que o Monarca seja despertado.",
  ui_story_5004_50043201_87_dialog_content = "Mas como vamos encontrar a sua forma real nessa ilusão?",
  ui_story_5004_50043201_88_dialog_content = "Bom, quando PlayerName estava me ajudando por telepatia...",
  ui_story_5004_50043201_89_dialog_content = "Acho que senti um ponto com muitos cristais...",
  ui_story_5004_50043201_90_dialog_content = "Lá deve ser provavelmente onde eles estão se escondendo...",
  ui_story_5004_50043201_91_dialog_content = "Bom trabalho! Vamos pra lá!",
  ui_story_5004_50043201_92_dialog_content = "Sim, e vai ser uma batalha árdua.",
  ui_story_5004_50043201_93_dialog_content = "Não se preocupe, Beryl. Vou me vingar daquela bruxa por você!",
  ui_story_5004_50043201_94_dialog_content = "É... Daí vamos pra Lumópolis, como prometemos.",
  ui_story_5004_50043201_95_dialog_content = "Independentemente dos inimigos que nos aguardam, eu não vou recuar!",
  ui_story_5004_50043301_1_dialog_content = "Uau, não pensei que poderiam encontrar esse lugar.",
  ui_story_5004_50043301_2_dialog_content = "Hum-hum! “Agradeço a todos por virem à <color=#FFB400>Sala do Trono</color> se ajoelhar diante do seu novo soberano.”",
  ui_story_5004_50043301_3_dialog_content = "“Essa é a minha nova forma, criada a partir dos cristais, com poderes idênticos aos seus, Beryl.”",
  ui_story_5004_50043301_4_dialog_content = "“A diferença é que você é apenas um protótipo, e eu o resultado final, capaz de controlar todo o poder dos cristais.”",
  ui_story_5004_50043301_5_dialog_content = "“E o <color=#FFB400>Monarca Desolado</color> também reviverá através dos cristais e reinará novamente.”",
  ui_story_5004_50043301_6_dialog_content = "Hum-hum, esse é o início do panegírico que escrevi para vocês. Vocês gostaram?",
  ui_story_5004_50043301_7_dialog_content = "<color=#e8d9bb>Caroline faz um gesto com as mãos e os cristais se estilhaçam. Então, a nuvem de pó é absorvida pelo Monarca.</color>",
  ui_story_5004_50043301_8_dialog_content = "...",
  ui_story_5004_50043301_9_dialog_content = "Vocês viram isso? Como o poder do cristal é compatível com os Eclipsitas!",
  ui_story_5004_50043301_10_dialog_content = "E eu pensei que era uma bênção dos deuses pros Aurorians! Sinto vergonha de ter pensado isso!",
  ui_story_5004_50043301_11_dialog_content = "É obviamente um presente para os Eclipsitas!",
  ui_story_5004_50043301_12_dialog_content = "Estou farta da sua tagarelice.",
  ui_story_5004_50043301_13_dialog_content = "Vamos lutar lá fora!",
  ui_story_5004_50043301_14_dialog_content = "Finalmente, finalmente... Hi... Haha! Cheguei num ponto em que quero matar vocês agora!",
  ui_story_5004_50043301_15_dialog_content = "Rápido, rápido! Mais dor, mais desespero pra dar mais sabor!",
  ui_story_5004_50043302_1_dialog_content = "Droga, eles não param de vir!",
  ui_story_5004_50043302_2_dialog_content = "Parem de brincar com os peões... Queima, queima!",
  ui_story_5004_50043302_3_dialog_content = "Impossível... Eu...",
  ui_story_5004_50043302_4_dialog_content = "Na cabeça! O brilho tá diminuindo!",
  ui_story_5004_50043302_5_dialog_content = "Conseguimos?",
  ui_story_5004_50043302_6_dialog_content = "...",
  ui_story_5004_50043302_7_dialog_content = "Hi, enganei vocês!",
  ui_story_5004_50043302_8_dialog_content = "!",
  ui_story_5004_50043302_9_dialog_content = "A Smokey!",
  ui_story_5004_50043302_10_dialog_content = "Essa doeu... Sai de cima de mim!",
  ui_story_5004_50043302_11_dialog_content = "Não esperava pela emboscada. Obrigado por cuidar de mim.",
  ui_story_5004_50043302_12_dialog_content = "Espera, é uma ferida profunda. Deixa a Raphaela curá-la pra você!",
  ui_story_5004_50043302_13_dialog_content = "(Droga, não tá diminuindo! Enquanto isso, os Eclipsitas continuam surgindo de todos os lugares...)",
  ui_story_5004_50043302_14_dialog_content = "(Isso é impossível, nunca encontrei um Eclipsita convertido assim tão poderoso antes!)",
  ui_story_5004_50043302_15_dialog_content = "(Teria o Monarca algo a ver com isso...?)",
  ui_story_5004_50043302_16_dialog_content = "Concentre-se, PlayerName! A maré da batalha pode virar a qualquer momento!",
  ui_story_5004_50043302_17_dialog_content = "Procure uma abertura.",
  ui_story_5004_50043302_18_dialog_content = "Você aí, fala mais alto pra eu poder escrever as suas últimas palavras no meu diário!",
  ui_story_5004_50043302_19_dialog_content = "Floresça!",
  ui_story_5004_50043302_20_dialog_content = "*Tosse*... Que fumaça densa. A Beryl detonou os cristais na Caroline como defesa?",
  ui_story_5004_50043302_21_dialog_content = "...",
  ui_story_5004_50043302_22_dialog_content = "Nada mal, nada mal.",
  ui_story_5004_50043302_23_dialog_content = "Como isso é possível...?",
  ui_story_5004_50043302_24_dialog_content = "Como assim ela tá sem nenhum arranhão?",
  ui_story_5004_50043302_25_dialog_content = "Não é possível...",
  ui_story_5004_50043302_26_dialog_content = "Muito impressionante pra um protótipo.",
  ui_story_5004_50043302_27_dialog_content = "Enfim, minha pobre Beryl, meu pobre experimento fracassado...",
  ui_story_5004_50043302_28_dialog_content = "Você continua inútil como sempre.",
  ui_story_5004_50043302_29_dialog_content = "Você matou tantas pessoas, matou seus pais... Quem você acha que pode salvar agora?",
  ui_story_5004_50043302_30_dialog_content = "Eu te avisei, você será a morte de todos que te são queridos antes de cair no abismo.",
  ui_story_5004_50043302_31_dialog_content = "Eu não...",
  ui_story_5004_50043302_32_dialog_content = "Pais...?",
  ui_story_5004_50043302_33_dialog_content = "Aahhhhhh!",
  ui_story_5004_50043302_34_dialog_content = "Não me parem, monstros!",
  ui_story_5004_50043302_35_dialog_content = "Carleen e Vice, cubram a Raphaela!",
  ui_story_5004_50043302_36_dialog_content = "Eu sei que você ainda se lembra de como matou seus pais indefesos...",
  ui_story_5004_50043302_37_dialog_content = "Aceite o seu fim. É a redenção pelos seus crimes. É a sua salvação.",
  ui_story_5004_50043302_38_dialog_content = "Sinto muito, pessoal... Mãe, pai... sinto muito...",
  ui_story_5004_50043302_39_dialog_content = "Beryl!",
  ui_story_5004_50043302_40_dialog_content = "Não dê ouvidos a ela, Beryl. Ela matou os seus pais!",
  ui_story_5004_50043302_41_dialog_content = "Você perdeu o controle e causou o incêndio, mas então você desmaiou imediatamente!",
  ui_story_5004_50043302_42_dialog_content = "Ela te fez de refém e assassinou os seus pais e a sua família!",
  ui_story_5004_50043302_43_dialog_content = "...",
  ui_story_5004_50043302_44_dialog_content = "É a confissão dos membros dos Pyrrhus presos, então é a verdade!",
  ui_story_5004_50043302_45_dialog_content = "Seu intrometido!",
  ui_story_5004_50043302_46_dialog_content = "Argh!",
  ui_story_5004_50043302_47_dialog_content = "Hehe, essa foi uma reviravolta inesperada.",
  ui_story_5004_50043302_48_dialog_content = "Mas, mas... Haha!",
  ui_story_5004_50043302_49_dialog_content = "Você realmente acreditou!",
  ui_story_5004_50043302_50_dialog_content = "!",
  ui_story_5004_50043302_51_dialog_content = "Então, você se lembra mesmo de como os corpos dos seus pais estavam quando você veio?",
  ui_story_5004_50043302_52_dialog_content = "Eu encenei aquilo especificamente pra você, só pra você pensar que os tinha matado!",
  ui_story_5004_50043302_53_dialog_content = "Muito, muito , muito estúpido da sua parte realmente acreditar nisso! E por tanto tempo!",
  ui_story_5004_50043302_54_dialog_content = "Mas por que...",
  ui_story_5004_50043302_55_dialog_content = "Me arrepio de emoção quando chego nessa parte do diário!",
  ui_story_5004_50043302_56_dialog_content = "Você deve ter pensado que matou seus pais durante todo esse tempo!",
  ui_story_5004_50043302_57_dialog_content = "Esse diário é o meu bem mais valioso, e eu quero dividi-lo com você!",
  ui_story_5004_50043302_58_dialog_content = "Um grande motivo pra ter te deixado viver foi pra poder registrar a expressão do seu rosto agora!",
  ui_story_5004_50043302_59_dialog_content = "Tá feliz agora? Você viveu achando que tinha matado seus entes queridos por todo esse tempo.",
  ui_story_5004_50043302_60_dialog_content = "A sua expressão quando finalmente descobriu a verdade foi extraordinária!",
  ui_story_5004_50043302_61_dialog_content = "Vou arrancar o seu rosto e usar como capa do meu diário!",
  ui_story_5004_50043302_62_dialog_content = "Gautier, Gautier! É assim que um Gautier traidor deve acabar!",
  ui_story_5004_50043302_63_dialog_content = "Como ousa fazer isso!",
  ui_story_5004_50043302_64_dialog_content = "Um protótipo fracassado como você não pode nem sonhar em se opor a mim, infalível, e ao Monarca desperto!",
  ui_story_5004_50043302_65_dialog_content = "Por me culpar pelos assassinatos e tentar machucar meus amigos...",
  ui_story_5004_50043302_66_dialog_content = "Eu nunca vou te perdoar!",
  ui_story_5004_50043302_67_dialog_content = "Esse é o poder que a Beryl estava reprimindo todo esse tempo?",
  ui_story_5004_50043302_68_dialog_content = "Se você liberar o poder, poderá se tornar um monstro como Caroline!",
  ui_story_5004_50043302_69_dialog_content = "Eu perdi quem amava, e me atolei em dor e culpa por ser pequena e fraca...",
  ui_story_5004_50043302_70_dialog_content = "A culpada está agora diante de mim e está tentando ferir os que são próximos a mim!",
  ui_story_5004_50043302_71_dialog_content = "Caroline Pyrrhus!",
  ui_story_5004_50043302_72_dialog_content = "Vou te arrastar pro inferno comigo, mesmo que tenha que perder o controle!",
  ui_story_5004_50043302_73_dialog_content = "Que ataque de cristais furioso...",
  ui_story_5004_50043302_74_dialog_content = "Caroline tá presa! Espera, mesmo com os cristais a imobilizando, não a estamos derrotando!",
  ui_story_5004_50043302_75_dialog_content = "Truque do salão! Me conceda mais poder, meu senhor! Me permita punir todos que ousaram te desafiar!",
  ui_story_5004_50043302_76_dialog_content = "...",
  ui_story_5004_50043302_77_dialog_content = "Acho que consegui! Mas não tenho certeza.",
  ui_story_5004_50043302_78_dialog_content = "A imortalidade da Caroline está vinculada ao Monarca!",
  ui_story_5004_50043302_79_dialog_content = "Concentrem seus ataques neles enquanto Caroline está presa!",
  ui_story_5004_50043402_1_dialog_content = "...!",
  ui_story_5004_50043402_2_dialog_content = "Por que você... Você ousa...!",
  ui_story_5004_50043402_3_dialog_content = "Ousa destruir o que me custou anos pra alcançar!",
  ui_story_5004_50043402_4_dialog_content = "Agora é a nossa vez de contra-atacar!",
  ui_story_5004_50043402_5_dialog_content = "Você vai pagar com a sua vida por me ferir!",
  ui_story_5004_50043402_6_dialog_content = "Não pode ser... É impossível, não posso perder pra fracotes como vocês!",
  ui_story_5004_50043402_7_dialog_content = "Vocês são meras peças... Impossível... Sou uma cristalógrafa de Lumópolis... Sou a Rainha aqui!",
  ui_story_5004_50043402_8_dialog_content = "Meu senhor! Me dê mais poder! Por que não consigo te ouvir?",
  ui_story_5004_50043402_9_dialog_content = "Preciso... continuar... Não acabou! Meu chá...!",
  ui_story_5004_50043402_10_dialog_content = "Amaldiçoo todos vocês! Juntem-se e teremos mais Aurorians saborosos! Seus traidores insolentes!",
  ui_story_5004_50043402_11_dialog_content = "Banirei vocês pra sempre para...",
  ui_story_5004_50043402_12_dialog_content = "Não quero saber mais das suas besteiras. Desapareça!",
  ui_story_5004_50043402_13_dialog_content = "Não deixarei que arruínem... o chá... Aghhh!",
  ui_story_5004_50043402_14_dialog_content = "Arf, arf...",
  ui_story_5004_50043402_15_dialog_content = "Conseguimos dessa vez?",
  ui_story_5004_50043402_16_dialog_content = "Você tava com vários cristais, Beryl!",
  ui_story_5004_50043402_17_dialog_content = "Tá tudo bem, Raphaela... desde que você e todo mundo estejam bem...",
  ui_story_5004_50043402_18_dialog_content = "Finalmente... Vinguei a minha família... e protegi vocês... Excelente...",
  ui_story_5004_50043402_19_dialog_content = "Acorda, Beryl! Não durma!",
  ui_story_5004_50043402_20_dialog_content = "Precisamos levar a Beryl pra Lumópolis agora, PlayerName!",
  ui_story_5004_50043402_21_dialog_content = "Mas ainda não conseguimos achar a Bonacie e não sabemos como sair daqui...",
  ui_story_5004_50043402_22_dialog_content = "Pera aí, o chão está se desintegrando!",
  ui_story_5004_50043402_23_dialog_content = "Cuidado!",
  ui_story_5004_50043402_24_dialog_content = "!",
  ui_story_5004_50043402_25_dialog_content = "Aonde vamos cair dessa vez?",
  ui_story_5004_50043402_26_dialog_content = "Banirei vocês pra sempre para...",
  ui_story_5004_50043402_27_dialog_content = "O banquete... o chá... nunca vão terminar...",
  ui_story_5004_50043402_28_dialog_content = "Hi hi..."
}
return config
